window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JHN"]={"book":"JHN","editions":{"fin-biblia1776":[[1,1,"Alussa oli sana, ja se Sana oli Jumalan tykönä, ja Jumala oli se Sana.","Alussa oli sana, ja se Sana oli Jumalan tykönä, ja Jumala oli se Sana."],[1,2,"Tämä oli alussa Jumalan tykönä.","Tämä oli alussa Jumalan tykönä."],[1,3,"Kaikki ovat sen kautta tehdyt, ja ilman sitä ei ole mitään tehty, joka tehty on.","Kaikki ovat sen kautta tehdyt, ja ilman sitä ei ole mitään tehty, joka tehty on."],[1,4,"Hänessä oli elämä, ja elämä oli ihmisten valkeus,","Hänessä oli elämä, ja elämä oli ihmisten valkeus,"],[1,5,"Ja valkeus paistaa pimeydessä, jota ei pimeys käsittänyt.","Ja valkeus paistaa pimeydessä, jota ei pimeys käsittänyt."],[1,6,"Yksi mies oli lähetetty Jumalalta, jonka nimi oli Johannes:","Yksi mies oli lähetetty Jumalalta, jonka nimi oli Johannes:"],[1,7,"Se tuli valkeudesta todistamaan, että kaikki uskoisivat hänen kauttansa.","Se tuli valkeudesta todistamaan, että kaikki uskoisivat hänen kauttansa."],[1,8,"Ei hän ollut valkeus, mutta hän oli lähetetty valkeudesta todistamaan.","Ei hän ollut valkeus, mutta hän oli lähetetty valkeudesta todistamaan."],[1,9,"Se oli totinen valkeus, joka valistaa kaikki ihmiset, jotka maailmaan tulevat;","Se oli totinen valkeus, joka valistaa kaikki ihmiset, jotka maailmaan tulevat;"],[1,10,"Se oli maailmassa, ja maailma oli hänen kauttansa tehty, ja ei maailma häntä tuntenut.","Se oli maailmassa, ja maailma oli hänen kauttansa tehty, ja ei maailma häntä tuntenut."],[1,11,"Hän tuli omillensa, ja ei hänen omansa häntä ottaneet vastaan,","Hän tuli omillensa, ja ei hänen omansa häntä ottaneet vastaan,"],[1,12,"Mutta niille, jotka hänen ottivat vastaan, antoi hän voiman Jumalan lapsiksi tulla, jotka uskovat hänen nimensä päälle,","Mutta niille, jotka hänen ottivat vastaan, antoi hän voiman Jumalan lapsiksi tulla, jotka uskovat hänen nimensä päälle,"],[1,13,"Jotka ei verestä eikä lihan tahdosta ei myös miehen tahdosta, mutta Jumalasta syntyneet ovat.","Jotka ei verestä eikä lihan tahdosta ei myös miehen tahdosta, mutta Jumalasta syntyneet ovat."],[1,14,"Ja Sana tuli lihaksi ja asui meidän seassamme, (ja me näimme hänen kunniansa niinkuin ainoan Pojan kunnian Isästä,) täynnä armoa ja totuutta.","Ja Sana tuli lihaksi ja asui meidän seassamme, (ja me näimme hänen kunniansa niinkuin ainoan Pojan kunnian Isästä,) täynnä armoa ja totuutta."],[1,15,"Johannes todisti hänestä, ja huusi, sanoen: tämä oli se, josta minä sanoin: minun jälkeeni on tuleva, joka minun edelläni on ollut; sillä hän oli ennen kuin minä.","Johannes todisti hänestä, ja huusi, sanoen: tämä oli se, josta minä sanoin: minun jälkeeni on tuleva, joka minun edelläni on ollut; sillä hän oli ennen kuin minä."],[1,16,"Ja me olemme kaikki hänen täydellisyydestänsä saaneet ja armon armosta.","Ja me olemme kaikki hänen täydellisyydestänsä saaneet ja armon armosta."],[1,17,"Sillä laki on Moseksen kautta annettu: armo ja totuus on Jesuksen Kristuksen kautta tullut.","Sillä laki on Moseksen kautta annettu: armo ja totuus on Jesuksen Kristuksen kautta tullut."],[1,18,"Ei ole kenkään koskaan Jumalaa nähnyt: ainokainen Poika, joka on Isän helmassa, hän ilmoitti meille.","Ei ole kenkään koskaan Jumalaa nähnyt: ainokainen Poika, joka on Isän helmassa, hän ilmoitti meille."],[1,19,"Ja tämä on Johenneksen todistus, kuin Juudalaiset lähettivät Jerusalemista papit ja Leviläiset kysymään häneltä: kukas olet?","Ja tämä on Johenneksen todistus, kuin Juudalaiset lähettivät Jerusalemista papit ja Leviläiset kysymään häneltä: kukas olet?"],[1,20,"Ja hän todisti ja ei kieltänyt, ja hän todisti, sanoen: en minä ole Kristus.","Ja hän todisti ja ei kieltänyt, ja hän todisti, sanoen: en minä ole Kristus."],[1,21,"Ja he kysyivät häneltä: kukas siis? oletkos Elias? Hän sanoi: en. Oletkos propheta? Hän vastasi: en.","Ja he kysyivät häneltä: kukas siis? oletkos Elias? Hän sanoi: en. Oletkos propheta? Hän vastasi: en."],[1,22,"Niin he sanoivat hänelle: kukas olet? että me antaisimme niille vastauksen, jotka meidät lähettivät: mitäs sanot itsestäs?","Niin he sanoivat hänelle: kukas olet? että me antaisimme niille vastauksen, jotka meidät lähettivät: mitäs sanot itsestäs?"],[1,23,"Hän sanoi: minä olen huutava ääni korvessa: valmistakaat Herran tietä, niinkuin Jesaias propheta sanoi.","Hän sanoi: minä olen huutava ääni korvessa: valmistakaat Herran tietä, niinkuin Jesaias propheta sanoi."],[1,24,"Ja jotka lähetetyt olivat, olivat Pharisealaisista.","Ja jotka lähetetyt olivat, olivat Pharisealaisista."],[1,25,"Ja he kysyivät häneltä ja sanoivat hänelle: miksi siis sinä kastat, jos et ole Kristus, etkä Elias, etkä propheta?","Ja he kysyivät häneltä ja sanoivat hänelle: miksi siis sinä kastat, jos et ole Kristus, etkä Elias, etkä propheta?"],[1,26,"Johannes vastasi heitä ja sanoi: minä kastan vedellä; mutta teidän keskellänne seisoo, jota ette tunne:","Johannes vastasi heitä ja sanoi: minä kastan vedellä; mutta teidän keskellänne seisoo, jota ette tunne:"],[1,27,"Hän on se, joka minun jälkeeni tulee, joka minun edelläni on ollut, jonka kengän rihmoja en minä ole kelvollinen päästämään.","Hän on se, joka minun jälkeeni tulee, joka minun edelläni on ollut, jonka kengän rihmoja en minä ole kelvollinen päästämään."],[1,28,"Nämät tapahtuivat Betabarassa, sillä puolella Jordania, kussa Johannes kasti.","Nämät tapahtuivat Betabarassa, sillä puolella Jordania, kussa Johannes kasti."],[1,29,"Toisena päivänä näki Johannes Jesuksen tykönsä tulevan, ja sanoi: katso, Jumalan Karitsa, joka pois ottaa maailman synnin!","Toisena päivänä näki Johannes Jesuksen tykönsä tulevan, ja sanoi: katso, Jumalan Karitsa, joka pois ottaa maailman synnin!"],[1,30,"Tämä on se, josta minä sanoin: minun jälkeeni tulee mies, joka minun edelläni on ollut; sillä hän oli ennen kuin minä.","Tämä on se, josta minä sanoin: minun jälkeeni tulee mies, joka minun edelläni on ollut; sillä hän oli ennen kuin minä."],[1,31,"Ja en minä häntä tuntenut; mutta että hän ilmestyisi Israelissa, sentähden tulin minä vedellä kastamaan.","Ja en minä häntä tuntenut; mutta että hän ilmestyisi Israelissa, sentähden tulin minä vedellä kastamaan."],[1,32,"Ja Johannes todisti, sanoen: minä näin Hengen taivaasta tulevan alas niinkuin kyyhkyisen ja seisahtavan hänen päällensä.","Ja Johannes todisti, sanoen: minä näin Hengen taivaasta tulevan alas niinkuin kyyhkyisen ja seisahtavan hänen päällensä."],[1,33,"Ja en minä häntä tuntenut; mutta joka minun lähetti vedellä kastamaan, se sanoi minulle: jonka päälle sinä näet Hengen tulevan alas ja seisahtavan hänen päällesä, hän on se, joka kastaa Pyhällä Hengellä.","Ja en minä häntä tuntenut; mutta joka minun lähetti vedellä kastamaan, se sanoi minulle: jonka päälle sinä näet Hengen tulevan alas ja seisahtavan hänen päällesä, hän on se, joka kastaa Pyhällä Hengellä."],[1,34,"Ja minä näin sen ja todistin hänen olevan Jumalan Pojan.","Ja minä näin sen ja todistin hänen olevan Jumalan Pojan."],[1,35,"Toisena päivänä seisoi Johannes taas ja kaksi hänen opetuslapsistansa,","Toisena päivänä seisoi Johannes taas ja kaksi hänen opetuslapsistansa,"],[1,36,"Ja kuin hän näki Jesuksen käyvän, sanoi hän: katso, Jumalan Karitsa!","Ja kuin hän näki Jesuksen käyvän, sanoi hän: katso, Jumalan Karitsa!"],[1,37,"Ja ne kaksi opetuslasta kuulivat hänen puhuvan, ja seurasivat Jesusta.","Ja ne kaksi opetuslasta kuulivat hänen puhuvan, ja seurasivat Jesusta."],[1,38,"Mutta Jesus käänsi itsensä ja näki ne seuraavan, ja sanoi heille:","Mutta Jesus käänsi itsensä ja näki ne seuraavan, ja sanoi heille:"],[1,39,"Mitä te etsitte? Niin he sanoivat hänelle: Rabbi (se on niin paljo sanottu: opettaja) kussas asut?","Mitä te etsitte? Niin he sanoivat hänelle: Rabbi (se on niin paljo sanottu: opettaja) kussas asut?"],[1,40,"Hän sanoi heille: tulkaat ja katsokaat; ja he tulivat ja näkivät, kussa hän asui, ja olivat sen päivän hänen tykönänsä, ja se oli lähes kymmenes hetki.","Hän sanoi heille: tulkaat ja katsokaat; ja he tulivat ja näkivät, kussa hän asui, ja olivat sen päivän hänen tykönänsä, ja se oli lähes kymmenes hetki."],[1,41,"Andreas, Simon Pietarin veli, oli yksi niistä kahdesta, jotka sen Johannekselta kuulleet olivat ja häntä seurasivat.","Andreas, Simon Pietarin veli, oli yksi niistä kahdesta, jotka sen Johannekselta kuulleet olivat ja häntä seurasivat."],[1,42,"Tämä löysi ensin veljensä Simonin, ja sanoi hänelle: me löysimme Messiaan; se on niin paljo kuin: voideltu.","Tämä löysi ensin veljensä Simonin, ja sanoi hänelle: me löysimme Messiaan; se on niin paljo kuin: voideltu."],[1,43,"Ja hän toi hänen Jesuksen tykö. Mutta kuin Jesus katsoi hänen päällensä, sanoi hän: sinä olet Simon Jonan poika, ja sinä pitää kutsuttaman Kephas; se on niin paljo kuin: kallio.","Ja hän toi hänen Jesuksen tykö. Mutta kuin Jesus katsoi hänen päällensä, sanoi hän: sinä olet Simon Jonan poika, ja sinä pitää kutsuttaman Kephas; se on niin paljo kuin: kallio."],[1,44,"Toisena päivänä tahtoi Jesus mennä Galileaan, ja löysi Philippuksen ja sanoi hänelle: seuraa minua!","Toisena päivänä tahtoi Jesus mennä Galileaan, ja löysi Philippuksen ja sanoi hänelle: seuraa minua!"],[1,45,"Mutta Philippus oli Betsaidasta, Andreaksen ja Pietarin kaupungista.","Mutta Philippus oli Betsaidasta, Andreaksen ja Pietarin kaupungista."],[1,46,"Philippus löysi Natanaelin ja sanoi hänelle: me olemme löytäneet sen, josta Moses kirjoitti laissa ja prophetat, Jesuksen, Josephin pojan Natsaretista.","Philippus löysi Natanaelin ja sanoi hänelle: me olemme löytäneet sen, josta Moses kirjoitti laissa ja prophetat, Jesuksen, Josephin pojan Natsaretista."],[1,47,"Ja Natanael sanoi hänelle: tulleeko Natsaretista jotain hyvää? Philippus sanoi hänelle: tule ja katso.","Ja Natanael sanoi hänelle: tulleeko Natsaretista jotain hyvää? Philippus sanoi hänelle: tule ja katso."],[1,48,"Jesus näki Natanaelin tykönsä tulevan, ja sanoi hänestä: katso, totisesti oikia Israelilainen, jossa ei petosta ole.","Jesus näki Natanaelin tykönsä tulevan, ja sanoi hänestä: katso, totisesti oikia Israelilainen, jossa ei petosta ole."],[1,49,"Natanael sanoi hänelle: mistäs minut tunnet? Jesus vastasi ja sanoi hänelle: ennen kuin Philippus kutsui sinua fikunapuun alla ollessas, näin minä sinun.","Natanael sanoi hänelle: mistäs minut tunnet? Jesus vastasi ja sanoi hänelle: ennen kuin Philippus kutsui sinua fikunapuun alla ollessas, näin minä sinun."],[1,50,"Vastasi Natanael ja sanoi hänelle: Rabbi, sinä olet Jumalan Poika, sinä olet Israelin kuningas.","Vastasi Natanael ja sanoi hänelle: Rabbi, sinä olet Jumalan Poika, sinä olet Israelin kuningas."],[1,51,"Jesus vastasi ja sanoi hänelle: sinä uskot, että minä sanoin sinulle: minä näin sinut fikunapuun alla. Sinä saat vielä suurempia nähdä. Ja sanoi hänelle: totisesti, totisesti sanon minä teille: tästedes pitää teidän näkemän taivaan avoinna, ja Jumalan enkelit astuvan ylös ja tulevan alas Ihmisen Pojan päälle.","Jesus vastasi ja sanoi hänelle: sinä uskot, että minä sanoin sinulle: minä näin sinut fikunapuun alla. Sinä saat vielä suurempia nähdä. Ja sanoi hänelle: totisesti, totisesti sanon minä teille: tästedes pitää teidän näkemän taivaan avoinna, ja Jumalan enkelit astuvan ylös ja tulevan alas Ihmisen Pojan päälle."],[2,1,"Ja kolmantena päivänä olivat häät Galilean Kaanassa, ja Jesuksen äiti oli siellä;","Ja kolmantena päivänä olivat häät Galilean Kaanassa, ja Jesuksen äiti oli siellä;"],[2,2,"Niin Jesus ja hänen opetuslapsensa kutsuttiin myös häihin.","Niin Jesus ja hänen opetuslapsensa kutsuttiin myös häihin."],[2,3,"Ja kun viina puuttui, sanoi Jesuksen äiti hänelle: ei heillä ole viinaa.","Ja kun viina puuttui, sanoi Jesuksen äiti hänelle: ei heillä ole viinaa."],[2,4,"Jesus sanoi hänelle: vaimo! mitä minun on sinun kanssas? ei minun aikani ole vielä tullut.","Jesus sanoi hänelle: vaimo! mitä minun on sinun kanssas? ei minun aikani ole vielä tullut."],[2,5,"Hänen äitinsä sanoi palvelijoille: mitä hän teille sanoo, se tehkäät.","Hänen äitinsä sanoi palvelijoille: mitä hän teille sanoo, se tehkäät."],[2,6,"Niin siellä oli kuusi kivistä vesi-astiaa pantuna Juudalaisten puhdistamisen tavan jälkeen, ja kukin veti kaksi eli kolme mittaa.","Niin siellä oli kuusi kivistä vesi-astiaa pantuna Juudalaisten puhdistamisen tavan jälkeen, ja kukin veti kaksi eli kolme mittaa."],[2,7,"Jesus sanoi heille: täyttäkäät vesi-astiat vedellä. Ja he täyttivät ne ylen täyteen.","Jesus sanoi heille: täyttäkäät vesi-astiat vedellä. Ja he täyttivät ne ylen täyteen."],[2,8,"Ja hän sanoi heille: pankaat nyt sisälle ja viekäät edeskäyvälle. Ja he veivät.","Ja hän sanoi heille: pankaat nyt sisälle ja viekäät edeskäyvälle. Ja he veivät."],[2,9,"Mutta kuin edeskäypä maisti sitä vettä, joka viinaksi tullut oli, (eikä tietänyt, kusta se tuli, mutta palveliat tiesivät, jotka veden ammensivat,) kutsui edeskäypä yljän,","Mutta kuin edeskäypä maisti sitä vettä, joka viinaksi tullut oli, (eikä tietänyt, kusta se tuli, mutta palveliat tiesivät, jotka veden ammensivat,) kutsui edeskäypä yljän,"],[2,10,"Ja sanoi hänelle: jokainen antaa ensisti hyvää viinaa, ja kuin juovutaan, niin sitte huonompaa: sinä kätkit hyvän viinan tähän asti.","Ja sanoi hänelle: jokainen antaa ensisti hyvää viinaa, ja kuin juovutaan, niin sitte huonompaa: sinä kätkit hyvän viinan tähän asti."],[2,11,"Tämä on ensimäinen tunnustähti, jonka Jesus teki Galilean Kaanassa, ja ilmoitti kunniansa. Ja hänen opetuslapsensa uskoivat hänen päällensä.","Tämä on ensimäinen tunnustähti, jonka Jesus teki Galilean Kaanassa, ja ilmoitti kunniansa. Ja hänen opetuslapsensa uskoivat hänen päällensä."],[2,12,"Sitte meni hän alas Kapernaumiin ja hänen äitinsä ja hänen veljensä ja hänen opetuslapsensa, eikä siellä kauvan viipyneet.","Sitte meni hän alas Kapernaumiin ja hänen äitinsä ja hänen veljensä ja hänen opetuslapsensa, eikä siellä kauvan viipyneet."],[2,13,"Ja Juudalaisten pääsiäinen oli läsnä, ja Jesus meni ylös Jerusalemiin,","Ja Juudalaisten pääsiäinen oli läsnä, ja Jesus meni ylös Jerusalemiin,"],[2,14,"Ja löysi templissä istuvan ne, jotka karjaa, lampaita ja kyykyläisiä myyskentelivät, ja vaihettajat.","Ja löysi templissä istuvan ne, jotka karjaa, lampaita ja kyykyläisiä myyskentelivät, ja vaihettajat."],[2,15,"Ja hän teki ruoskan köysistä, ja ajoi ulos ne kaikki temppelistä ja lampaat ja karjan, ja heitti pois vaihettajain rahat ja maahan kukisti pöydät.","Ja hän teki ruoskan köysistä, ja ajoi ulos ne kaikki temppelistä ja lampaat ja karjan, ja heitti pois vaihettajain rahat ja maahan kukisti pöydät."],[2,16,"Ja sanoi niille, jotka kyhkyisiä myivät: viekäät nämät täältä pois ja älkäät tehkö minun Isäni huonetta kauppahuoneeksi.","Ja sanoi niille, jotka kyhkyisiä myivät: viekäät nämät täältä pois ja älkäät tehkö minun Isäni huonetta kauppahuoneeksi."],[2,17,"Mutta hänen opetuslapsensa muistivat kirjoitetuksi: sinun huonees kiivaus on minun syönyt.","Mutta hänen opetuslapsensa muistivat kirjoitetuksi: sinun huonees kiivaus on minun syönyt."],[2,18,"Niin vastasivat Juudalaiset ja sanoivat hänelle: mitä merkkiä sinä meille osoitat, ettäs näitä teet?","Niin vastasivat Juudalaiset ja sanoivat hänelle: mitä merkkiä sinä meille osoitat, ettäs näitä teet?"],[2,19,"Jesus vastasi ja sanoi heille: jaottakaat maahan tämä templi, ja minä tahdon sen kolmantena päivänä rakentaa ylös.","Jesus vastasi ja sanoi heille: jaottakaat maahan tämä templi, ja minä tahdon sen kolmantena päivänä rakentaa ylös."],[2,20,"Niin Juudalaiset sanoivat: tätä templiä on rakennettu kuusiviidettäkymmentä ajastaikaa, ja sinä rakennat sen kolmena päivänä?","Niin Juudalaiset sanoivat: tätä templiä on rakennettu kuusiviidettäkymmentä ajastaikaa, ja sinä rakennat sen kolmena päivänä?"],[2,21,"Mutta hän sanoi ruumiinsa templistä.","Mutta hän sanoi ruumiinsa templistä."],[2,22,"Kuin hän siis oli kuolleista noussut, muistivat hänen opetuslapsensa hänen sen heille sanoneeksi, ja uskoivat Raamatun ja puheen, minkä Jesus oli puhunut.","Kuin hän siis oli kuolleista noussut, muistivat hänen opetuslapsensa hänen sen heille sanoneeksi, ja uskoivat Raamatun ja puheen, minkä Jesus oli puhunut."],[2,23,"Mutta kuin hän pääsiäis-juhlapäivänä oli Jerusalemissa, uskoivat monta hänen nimensä päälle, kuin he näkivät ne tunnustähdet mitkä hän teki.","Mutta kuin hän pääsiäis-juhlapäivänä oli Jerusalemissa, uskoivat monta hänen nimensä päälle, kuin he näkivät ne tunnustähdet mitkä hän teki."],[2,24,"Mutta ei Jesus uskonut itsiänsä heille; sillä hän tunsi heidät kaikki,","Mutta ei Jesus uskonut itsiänsä heille; sillä hän tunsi heidät kaikki,"],[2,25,"Ja ei tarvinnut, että joku olis ihmisestä todistanut; sillä hän tiesi, mitä ihmisessä oli.","Ja ei tarvinnut, että joku olis ihmisestä todistanut; sillä hän tiesi, mitä ihmisessä oli."],[3,1,"Niin oli yksi mies Pharisealaisista, Nikodemus nimeltä, Juudalaisten ylimmäinen.","Niin oli yksi mies Pharisealaisista, Nikodemus nimeltä, Juudalaisten ylimmäinen."],[3,2,"Se tuli yöllä Jesuksen tykö ja sanoi hänelle: Mestari, me tiedämme, että sinä olet Jumalasta opettajaksi tullut; sillä ei taida kenkään niitä tunnustähtiä tehdä, joita sinä teet, jollei Jumala ole hänen kanssansa.","Se tuli yöllä Jesuksen tykö ja sanoi hänelle: Mestari, me tiedämme, että sinä olet Jumalasta opettajaksi tullut; sillä ei taida kenkään niitä tunnustähtiä tehdä, joita sinä teet, jollei Jumala ole hänen kanssansa."],[3,3,"Jesus vastasi ja sanoi hänelle: totisesti, totisesti sanon minä sinulle: ellei joku vastuudesta synny, ei hän taida Jumalan valtakuntaa nähdä.","Jesus vastasi ja sanoi hänelle: totisesti, totisesti sanon minä sinulle: ellei joku vastuudesta synny, ei hän taida Jumalan valtakuntaa nähdä."],[3,4,"Nikodemus sanoi hänelle: kuinka taitaa ihminen vanhana syntyä? taitaako hän äitinsä kohtuun jälleen mennä, ja syntyä?","Nikodemus sanoi hänelle: kuinka taitaa ihminen vanhana syntyä? taitaako hän äitinsä kohtuun jälleen mennä, ja syntyä?"],[3,5,"Jesus vastasi: totisesti, totisesti sanon minä sinulle: ellei joku synny vedestä ja Hengestä ei hän taida Jumalan valtakuntaan sisälle tulla.","Jesus vastasi: totisesti, totisesti sanon minä sinulle: ellei joku synny vedestä ja Hengestä ei hän taida Jumalan valtakuntaan sisälle tulla."],[3,6,"Mitä lihasta syntynyt on, se on liha, ja mitä Hengestä syntynyt on se on henki.","Mitä lihasta syntynyt on, se on liha, ja mitä Hengestä syntynyt on se on henki."],[3,7,"Älä ihmettele, että minä sanoin sinulle: teidän pitää uudesta syntymän.","Älä ihmettele, että minä sanoin sinulle: teidän pitää uudesta syntymän."],[3,8,"Tuuli puhaltaa, kussa hän tahtoo, ja sinä kuulet hänen humunsa, ja et tiedä, kusta hän tulee taikka kuhunka hän menee: näin on jokainen, joka Hengestä syntynyt on.","Tuuli puhaltaa, kussa hän tahtoo, ja sinä kuulet hänen humunsa, ja et tiedä, kusta hän tulee taikka kuhunka hän menee: näin on jokainen, joka Hengestä syntynyt on."],[3,9,"Vastasi Nikodemus ja sanoi hänelle: kuinka ne taitavat tapahtua?","Vastasi Nikodemus ja sanoi hänelle: kuinka ne taitavat tapahtua?"],[3,10,"Jesus vastasi ja sanoi hänelle: sinä olet mestari Israelissa, ja et näitä tiedä!","Jesus vastasi ja sanoi hänelle: sinä olet mestari Israelissa, ja et näitä tiedä!"],[3,11,"Totisesti, totisesti sanon minä sinulle: me puhumme, mitä me tiedämme, ja todistamme, mitä me näemme, ja ette ota vastaan meidän todistustamme.","Totisesti, totisesti sanon minä sinulle: me puhumme, mitä me tiedämme, ja todistamme, mitä me näemme, ja ette ota vastaan meidän todistustamme."],[3,12,"Jos minä maallisia teille sanoin, ja ette usko: kuinka te uskoisitte, jos minä taivaallisia teille sanoisin?","Jos minä maallisia teille sanoin, ja ette usko: kuinka te uskoisitte, jos minä taivaallisia teille sanoisin?"],[3,13,"Ei astu kenkään ylös taivaasen, vaan joka taivaasta astui alas, Ihmisen Poika, joka on taivaassa.","Ei astu kenkään ylös taivaasen, vaan joka taivaasta astui alas, Ihmisen Poika, joka on taivaassa."],[3,14,"Ja niinkuin Moses ylensi kärmeen korvessa, niin myös Ihmisen Poika pitää ylennettämän.","Ja niinkuin Moses ylensi kärmeen korvessa, niin myös Ihmisen Poika pitää ylennettämän."],[3,15,"Että jokainen, joka uskoo hänen päällensä, ei pidä hukkuman, mutta ijankaikkisen elämän saaman.","Että jokainen, joka uskoo hänen päällensä, ei pidä hukkuman, mutta ijankaikkisen elämän saaman."],[3,16,"Sillä niin on Jumala maailmaa rakastanut, että hän antoi ainoan Poikansa, että jokainen, joka uskoo hänen päällensä, ei pidä hukkuman, mutta ijankaikkisen elämän saaman.","Sillä niin on Jumala maailmaa rakastanut, että hän antoi ainoan Poikansa, että jokainen, joka uskoo hänen päällensä, ei pidä hukkuman, mutta ijankaikkisen elämän saaman."],[3,17,"Sillä ei Jumala lähettänyt Poikaansa maailmaan, tuomitsemaan maailmaa, mutta että maailma pitää hänen kauttansa vapahdettaman.","Sillä ei Jumala lähettänyt Poikaansa maailmaan, tuomitsemaan maailmaa, mutta että maailma pitää hänen kauttansa vapahdettaman."],[3,18,"Joka hänen päällensä uskoo, ei häntä tuomita; mutta joka ei usko, se on jo tuomittu; sillä ei hän uskonut Jumalan ainoan Pojan nimen päälle.","Joka hänen päällensä uskoo, ei häntä tuomita; mutta joka ei usko, se on jo tuomittu; sillä ei hän uskonut Jumalan ainoan Pojan nimen päälle."],[3,19,"Mutta tämä on tuomio: että valkeus tuli maailmaan, ja ihmiset rakastivat enemmin pimeyttä kuin valkeutta; sillä heidän työnsä olivat pahat.","Mutta tämä on tuomio: että valkeus tuli maailmaan, ja ihmiset rakastivat enemmin pimeyttä kuin valkeutta; sillä heidän työnsä olivat pahat."],[3,20,"Sillä jokainen, joka pahaa tekee, se vihaa valkeutta eikä tule valkeuteen, ettei hänen töitänsä pitäisi laitettaman.","Sillä jokainen, joka pahaa tekee, se vihaa valkeutta eikä tule valkeuteen, ettei hänen töitänsä pitäisi laitettaman."],[3,21,"Mutta joka totuuden tekee, se tulee valkeuteen, että hänen työnsä nähtäisiin; sillä ne ovat Jumalassa tehdyt.","Mutta joka totuuden tekee, se tulee valkeuteen, että hänen työnsä nähtäisiin; sillä ne ovat Jumalassa tehdyt."],[3,22,"Sitte tuli Jesus ja hänen opetuslapsensa Juudean maahan, ja asui siellä heidän kanssansa, ja kasti.","Sitte tuli Jesus ja hänen opetuslapsensa Juudean maahan, ja asui siellä heidän kanssansa, ja kasti."],[3,23,"Mutta Johannes kasti myös Enonissa läsnä Salimia, sillä siellä oli palto vettä; ja he tulivat ja kastettiin.","Mutta Johannes kasti myös Enonissa läsnä Salimia, sillä siellä oli palto vettä; ja he tulivat ja kastettiin."],[3,24,"Sillä ei Johannes ollut vielä silloin vankiuteen heitetty.","Sillä ei Johannes ollut vielä silloin vankiuteen heitetty."],[3,25,"Niin tuli kysymys Johanneksen opetuslasten ja Juudalaisten välillä puhdistuksesta.","Niin tuli kysymys Johanneksen opetuslasten ja Juudalaisten välillä puhdistuksesta."],[3,26,"Ja he tulivat Johanneksen tykö ja sanoivat hänelle: opettaja, se joka sinun kanssas oli toisella puolella Jordania, josta sinä todistit, katso, hän kastaa, ja jokainen menee hänen tykönsä.","Ja he tulivat Johanneksen tykö ja sanoivat hänelle: opettaja, se joka sinun kanssas oli toisella puolella Jordania, josta sinä todistit, katso, hän kastaa, ja jokainen menee hänen tykönsä."],[3,27,"Johannes vastasi ja sanoi: ei ihminen taida mitään ottaa, ellei hänelle anneta taivaasta.","Johannes vastasi ja sanoi: ei ihminen taida mitään ottaa, ellei hänelle anneta taivaasta."],[3,28,"Te olette itse minun todistajani, että minä olen sanonut: en minä ole Kristus, vaan minä olen hänen edellänsä lähetetty.","Te olette itse minun todistajani, että minä olen sanonut: en minä ole Kristus, vaan minä olen hänen edellänsä lähetetty."],[3,29,"Jolla on morsian, se on ylkä; mutta yljän ystävä, joka seisoo ja kuultelee häntä, se iloittaa itsiänsä yljän äänestä sangen suuresti; sentähden on tämä minun iloni täytetty.","Jolla on morsian, se on ylkä; mutta yljän ystävä, joka seisoo ja kuultelee häntä, se iloittaa itsiänsä yljän äänestä sangen suuresti; sentähden on tämä minun iloni täytetty."],[3,30,"Hänen tulee kasvaa, mutta minun pitää vähenemän.","Hänen tulee kasvaa, mutta minun pitää vähenemän."],[3,31,"Joka ylhäältä tulee, se on kaikkein päällä, ja joka maasta on, se on maasta ja puhuu maasta. Joka taivaasta tulee, hän on kaikkein ylin.","Joka ylhäältä tulee, se on kaikkein päällä, ja joka maasta on, se on maasta ja puhuu maasta. Joka taivaasta tulee, hän on kaikkein ylin."],[3,32,"Ja mitä hän nähnyt ja kuullut on, sen hän todistaa, ja ei kenkään ota vastaan hänen todistustansa.","Ja mitä hän nähnyt ja kuullut on, sen hän todistaa, ja ei kenkään ota vastaan hänen todistustansa."],[3,33,"Joka hänen todistuksensa otti vastaan, se päätti Jumalan olevan totisen.","Joka hänen todistuksensa otti vastaan, se päätti Jumalan olevan totisen."],[3,34,"Sillä jonka Jumala lähetti, se puhuu Jumalan sanoja; sillä ei Jumala anna Henkeä mitalla.","Sillä jonka Jumala lähetti, se puhuu Jumalan sanoja; sillä ei Jumala anna Henkeä mitalla."],[3,35,"Isä rakastaa Poikaa, ja antoi kaikki hänen käteensä.","Isä rakastaa Poikaa, ja antoi kaikki hänen käteensä."],[3,36,"Joka uskoo Pojan päälle, hänellä on ijankaikkinen elämä; mutta joka ei usko Pojan päälle, ei hänen pidä elämää näkemän, mutta Jumalan viha pysyy hänen päällänsä.","Joka uskoo Pojan päälle, hänellä on ijankaikkinen elämä; mutta joka ei usko Pojan päälle, ei hänen pidä elämää näkemän, mutta Jumalan viha pysyy hänen päällänsä."],[4,1,"Kuin siis Herra ymmärsi Pharisealaisten kuulleeksi, että Jesus teki enemmin opetuslapsia ja kasti kuin Johannes;","Kuin siis Herra ymmärsi Pharisealaisten kuulleeksi, että Jesus teki enemmin opetuslapsia ja kasti kuin Johannes;"],[4,2,"(Vaikka ei Jesus itse kastanut, mutta hänen opetuslapsensa,)","(Vaikka ei Jesus itse kastanut, mutta hänen opetuslapsensa,)"],[4,3,"Jätti hän Juudean ja meni jälleen Galileaan.","Jätti hän Juudean ja meni jälleen Galileaan."],[4,4,"Mutta hänen piti Samarian kautta vaeltaman.","Mutta hänen piti Samarian kautta vaeltaman."],[4,5,"Niin hän tuli Samarian kaupunkiin, joka kutsuttiin Sikar, lähes sitä maakartanoa, jonka Jakob oli pojallensa Josephille antanut.","Niin hän tuli Samarian kaupunkiin, joka kutsuttiin Sikar, lähes sitä maakartanoa, jonka Jakob oli pojallensa Josephille antanut."],[4,6,"Niin siellä oli Jakobin lähde. Kuin Jesus matkasta oli väsynyt, istui hän lähteen päälle, ja se oli liki kuudetta hetkeä.","Niin siellä oli Jakobin lähde. Kuin Jesus matkasta oli väsynyt, istui hän lähteen päälle, ja se oli liki kuudetta hetkeä."],[4,7,"Niin tuli yksi Samarian vaimo vettä ammentamaan, ja Jesus sanoi hänelle: anna minun juodakseni.","Niin tuli yksi Samarian vaimo vettä ammentamaan, ja Jesus sanoi hänelle: anna minun juodakseni."],[4,8,"Sillä hänen opetuslapsensa olivat menneet kaupunkiin ruokaa ostamaan.","Sillä hänen opetuslapsensa olivat menneet kaupunkiin ruokaa ostamaan."],[4,9,"Sanoi Samarian vaimo hänelle: kuinka sinä minulta juoda anot, joka olet Juudalainen, ja minä olen Samarialainen? sillä ei Juudalaiset pidä yhtään kanssakäymistä Samarialaisten kanssa.","Sanoi Samarian vaimo hänelle: kuinka sinä minulta juoda anot, joka olet Juudalainen, ja minä olen Samarialainen? sillä ei Juudalaiset pidä yhtään kanssakäymistä Samarialaisten kanssa."],[4,10,"Jesus vastasi ja sanoi hänelle: jos sinä tietäisit Jumalan lahjan, ja kuka se on, joka sinulle sanoo: anna minun juodakseni! niin sinä anoisit häneltä, ja hän antaisi sinulle elävää vettä.","Jesus vastasi ja sanoi hänelle: jos sinä tietäisit Jumalan lahjan, ja kuka se on, joka sinulle sanoo: anna minun juodakseni! niin sinä anoisit häneltä, ja hän antaisi sinulle elävää vettä."],[4,11,"Sanoi vaimo hänelle: Herra, eipä sinulla ole, milläs ammennat, ja lähde on syvä: kusta siis sinulla on elävää vettä?","Sanoi vaimo hänelle: Herra, eipä sinulla ole, milläs ammennat, ja lähde on syvä: kusta siis sinulla on elävää vettä?"],[4,12,"Oletkos sinä suurempi kuin meidän isämme Jakob, joka meille tämän kaivon antoi? ja hän joi itse siitä, ja hänen lapsensa, ja hänen karjansa.","Oletkos sinä suurempi kuin meidän isämme Jakob, joka meille tämän kaivon antoi? ja hän joi itse siitä, ja hänen lapsensa, ja hänen karjansa."],[4,13,"Jesus vastasi ja sanoi hänelle: jokainen, joka juo tästä vedestä, hän janoo jälleen;","Jesus vastasi ja sanoi hänelle: jokainen, joka juo tästä vedestä, hän janoo jälleen;"],[4,14,"Mutta joka siitä vedestä juo, jonka minä hänelle annan, ei hän janoo ijankaikkisesti; vaan se vesi, jonka minä hänelle annan, tulee hänessä sen veden lähteeksi, joka kuohuu ijankaikkiseen elämään.","Mutta joka siitä vedestä juo, jonka minä hänelle annan, ei hän janoo ijankaikkisesti; vaan se vesi, jonka minä hänelle annan, tulee hänessä sen veden lähteeksi, joka kuohuu ijankaikkiseen elämään."],[4,15,"Sanoi vaimo hänelle: Herra, anna minulle sitä vettä, etten minä janoaisi enkä tarvitsisi tulla tänne ammentamaan.","Sanoi vaimo hänelle: Herra, anna minulle sitä vettä, etten minä janoaisi enkä tarvitsisi tulla tänne ammentamaan."],[4,16,"Jesus sanoi hänelle: mene, kutsu miehes, ja tule tänne.","Jesus sanoi hänelle: mene, kutsu miehes, ja tule tänne."],[4,17,"Vaimo vastasi ja sanoi hänelle: ei minulla ole miestä. Sanoi Jesus hänelle: oikein sinä sanoit: ei minulla ole miestä.","Vaimo vastasi ja sanoi hänelle: ei minulla ole miestä. Sanoi Jesus hänelle: oikein sinä sanoit: ei minulla ole miestä."],[4,18,"Sillä viisi miestä on sinulla ollut, ja se joka sinulla nyt on, ei ole sinun miehes. Sen sinä oikein sanoit.","Sillä viisi miestä on sinulla ollut, ja se joka sinulla nyt on, ei ole sinun miehes. Sen sinä oikein sanoit."],[4,19,"Vaimo sanoi hänelle: Herra, minä näen, että sinä olet propheta.","Vaimo sanoi hänelle: Herra, minä näen, että sinä olet propheta."],[4,20,"Meidän isämme ovat tällä vuorella kumartaneet ja rukoilleet, ja te sanotte: Jerusalemissa on se sia, jossa pitää rukoiltaman.","Meidän isämme ovat tällä vuorella kumartaneet ja rukoilleet, ja te sanotte: Jerusalemissa on se sia, jossa pitää rukoiltaman."],[4,21,"Jesus sanoi hänelle: vaimo, usko minua: se aika tulee, ettette tällä vuorella eikä Jerusalemissa Isää rukoile.","Jesus sanoi hänelle: vaimo, usko minua: se aika tulee, ettette tällä vuorella eikä Jerusalemissa Isää rukoile."],[4,22,"Ette tiedä, mitä te rukoilette, mutta me tiedämme, mitä me rukoilemme; sillä autuus on Juudalaisista.","Ette tiedä, mitä te rukoilette, mutta me tiedämme, mitä me rukoilemme; sillä autuus on Juudalaisista."],[4,23,"Mutta hetki tulee, ja jo nyt on, että totiset rukoiliat rukoilevat Isää hengessä ja totuudessa; sillä Isä tahtoo myös senkaltaisia, jotka häntä rukoilevat.","Mutta hetki tulee, ja jo nyt on, että totiset rukoiliat rukoilevat Isää hengessä ja totuudessa; sillä Isä tahtoo myös senkaltaisia, jotka häntä rukoilevat."],[4,24,"Jumala on Henki, ja jotka häntä rukoilevat, niiden pitää hengessä ja totuudessa häntä rukoileman.","Jumala on Henki, ja jotka häntä rukoilevat, niiden pitää hengessä ja totuudessa häntä rukoileman."],[4,25,"Vaimo sanoi hänelle: minä tiedän, että Messias on tuleva, joka kutsutaan Kristus: kuin hän tulee, niin hän ilmoittaa meille kaikki.","Vaimo sanoi hänelle: minä tiedän, että Messias on tuleva, joka kutsutaan Kristus: kuin hän tulee, niin hän ilmoittaa meille kaikki."],[4,26,"Jesus sanoi hänelle: minä olen se, joka sinun kanssas puhun.","Jesus sanoi hänelle: minä olen se, joka sinun kanssas puhun."],[4,27,"Silloin tulivat hänen opetuslapsensa ja ihmettelivät, että hän sitä vaimoa puhutteli: ei kuitenkaan kenkään sanonut: mitäs kysyt? eli mitäs häntä puhuttelet?","Silloin tulivat hänen opetuslapsensa ja ihmettelivät, että hän sitä vaimoa puhutteli: ei kuitenkaan kenkään sanonut: mitäs kysyt? eli mitäs häntä puhuttelet?"],[4,28,"Niin vaimo jätti vesi-astiansa, ja meni kaupunkiin, ja sanoi niille ihmisille:","Niin vaimo jätti vesi-astiansa, ja meni kaupunkiin, ja sanoi niille ihmisille:"],[4,29,"Tulkaa katsomaan sitä ihmistä, joka minulle sanoi kaikki, mitä minä tehnyt olen: olleeko hän Kristus?","Tulkaa katsomaan sitä ihmistä, joka minulle sanoi kaikki, mitä minä tehnyt olen: olleeko hän Kristus?"],[4,30,"Niin he läksivät kaupungista ja menivät hänen tykönsä.","Niin he läksivät kaupungista ja menivät hänen tykönsä."],[4,31,"Mutta sillä välillä rukoilivat opetuslapset häntä, sanoen: Rabbi, syö.","Mutta sillä välillä rukoilivat opetuslapset häntä, sanoen: Rabbi, syö."],[4,32,"Vaan hän sanoi heille: minulla on ruokaa syödäkseni, jota ette tiedä.","Vaan hän sanoi heille: minulla on ruokaa syödäkseni, jota ette tiedä."],[4,33,"Niin opetuslapset sanoivat keskenänsä: lieneekö joku hänelle syötävää tuonut?","Niin opetuslapset sanoivat keskenänsä: lieneekö joku hänelle syötävää tuonut?"],[4,34,"Jesus sanoi heille: minun ruokani on se, että minä teen hänen tahtonsa, joka minun lähetti, ja täytän hänen tekonsa.","Jesus sanoi heille: minun ruokani on se, että minä teen hänen tahtonsa, joka minun lähetti, ja täytän hänen tekonsa."],[4,35,"Ettekö te sano: vielä ovat neljä kuukautta ja elonaika tulee? katso, minä sanon teille: nostakaat silmänne ylös ja katsokaat vainioita: sillä ne ovat jo valkiat elonajaksi.","Ettekö te sano: vielä ovat neljä kuukautta ja elonaika tulee? katso, minä sanon teille: nostakaat silmänne ylös ja katsokaat vainioita: sillä ne ovat jo valkiat elonajaksi."],[4,36,"Ja joka niittää, hän saa palkan ja kokoo hedelmän ijankaikkiseen elämään: että kylväjä ja niittäjä ynnä iloitsisivat.","Ja joka niittää, hän saa palkan ja kokoo hedelmän ijankaikkiseen elämään: että kylväjä ja niittäjä ynnä iloitsisivat."],[4,37,"Sillä tässä on se sana tosi; toinen on, joka kylvää, ja toinen, joka niittää.","Sillä tässä on se sana tosi; toinen on, joka kylvää, ja toinen, joka niittää."],[4,38,"Minä lähetin teidät niittämään, jossa ette ole työtä tehneet: muut ovat työtä tehneet ja te olette heidän työnsä päälle tulleet.","Minä lähetin teidät niittämään, jossa ette ole työtä tehneet: muut ovat työtä tehneet ja te olette heidän työnsä päälle tulleet."],[4,39,"Mutta monta Samarialaista siitä kaupungista uskoivat hänen päällensä sen vaimon puheen tähden, joka sanoi: hän on minulle kaikki sanonut, mitä minä tehnyt olen.","Mutta monta Samarialaista siitä kaupungista uskoivat hänen päällensä sen vaimon puheen tähden, joka sanoi: hän on minulle kaikki sanonut, mitä minä tehnyt olen."],[4,40,"Kuin siis Samarialaiset tulivat hänen tykönsä, rukoilivat he häntä viipymään heidän tykönänsä. Ja hän viipyi siellä kaksi päivää.","Kuin siis Samarialaiset tulivat hänen tykönsä, rukoilivat he häntä viipymään heidän tykönänsä. Ja hän viipyi siellä kaksi päivää."],[4,41,"Ja paljo usiammat uskoivat hänen sanansa tähden.","Ja paljo usiammat uskoivat hänen sanansa tähden."],[4,42,"Ja sanoivat sille vaimolle: emme nyt silleen usko sinun puhees tähden; sillä me olemme itse kuulleet ja tiedämme, että hän on totisesti Kristus, maailman Vapahtaja.","Ja sanoivat sille vaimolle: emme nyt silleen usko sinun puhees tähden; sillä me olemme itse kuulleet ja tiedämme, että hän on totisesti Kristus, maailman Vapahtaja."],[4,43,"Mutta kahden päivän perästä läksi hän sieltä ja meni Galileaan.","Mutta kahden päivän perästä läksi hän sieltä ja meni Galileaan."],[4,44,"Sillä Jesus todisti itse, ettei propheta maksa isänsä maalla mitään.","Sillä Jesus todisti itse, ettei propheta maksa isänsä maalla mitään."],[4,45,"Kuin hän siis tuli Galileaan, ottivat Galilealaiset hänen vastaan, jotka olivat nähneet kaikki ne, mitä hän Jerusalemissa juhlana tehnyt oli: sillä he olivat myös juhlalle tulleet.","Kuin hän siis tuli Galileaan, ottivat Galilealaiset hänen vastaan, jotka olivat nähneet kaikki ne, mitä hän Jerusalemissa juhlana tehnyt oli: sillä he olivat myös juhlalle tulleet."],[4,46,"Niin Jesus tuli taas Galilean Kaanaan, kussa hän meden viinaksi tehnyt oli. Ja oli kuninkaan mies, jonka poika sairasti Kapernaumissa.","Niin Jesus tuli taas Galilean Kaanaan, kussa hän meden viinaksi tehnyt oli. Ja oli kuninkaan mies, jonka poika sairasti Kapernaumissa."],[4,47,"Kuin hän kuuli, että Jesus oli tullut Juudeasta Galileaan, meni hän hänen tykönsä ja rukoili häntä tulemaan alas ja parantamaan hänen poikansa, joka oli kuolemallansa.","Kuin hän kuuli, että Jesus oli tullut Juudeasta Galileaan, meni hän hänen tykönsä ja rukoili häntä tulemaan alas ja parantamaan hänen poikansa, joka oli kuolemallansa."],[4,48,"Sanoi siis Jesus hänelle: ellette näe tunnustähtiä ja ihmeitä, niin ette usko.","Sanoi siis Jesus hänelle: ellette näe tunnustähtiä ja ihmeitä, niin ette usko."],[4,49,"Sanoi kuninkaan mies hänelle: Herra, tule alas ennenkuin minun poikani kuolee.","Sanoi kuninkaan mies hänelle: Herra, tule alas ennenkuin minun poikani kuolee."],[4,50,"Jesus sanoi hänelle: mene, sinun poikas elää. Ja mies uskoi sanan, jonka Jesus sanoi hänelle, ja meni.","Jesus sanoi hänelle: mene, sinun poikas elää. Ja mies uskoi sanan, jonka Jesus sanoi hänelle, ja meni."],[4,51,"Niin hänen mennessänsä, kohtasivat hänen palveliansa hänen ja ilmoittivat hänelle, sanoen: sinun poikas elää.","Niin hänen mennessänsä, kohtasivat hänen palveliansa hänen ja ilmoittivat hänelle, sanoen: sinun poikas elää."],[4,52,"Niin hän tutki heiltä hetkeä, jolla hän parani, ja he sanoivat hänelle: eilen seitsemännellä hetkellä antoi vilutauti hänen ylön.","Niin hän tutki heiltä hetkeä, jolla hän parani, ja he sanoivat hänelle: eilen seitsemännellä hetkellä antoi vilutauti hänen ylön."],[4,53,"Niin isä ymmärsi sen siksi hetkeksi, jolla Jesus sanoi hänelle: sinun poikas elää. Ja hän uskoi ja koko hänen huoneensa.","Niin isä ymmärsi sen siksi hetkeksi, jolla Jesus sanoi hänelle: sinun poikas elää. Ja hän uskoi ja koko hänen huoneensa."],[4,54,"Tämä on toinen tunnustähti, jonka Jesus teki tullessansa Juudeasta Galileaan.","Tämä on toinen tunnustähti, jonka Jesus teki tullessansa Juudeasta Galileaan."],[5,1,"Sitte oli Juudalaisten juhlapäivä, ja Jesus meni ylös Jerusalemiin.","Sitte oli Juudalaisten juhlapäivä, ja Jesus meni ylös Jerusalemiin."],[5,2,"Mutta Jerusalemissa on Lammasportin tykönä lammikko, joka Hebrean kielellä kutsutaan Betesda, jossa oli viisi vajaa,","Mutta Jerusalemissa on Lammasportin tykönä lammikko, joka Hebrean kielellä kutsutaan Betesda, jossa oli viisi vajaa,"],[5,3,"Joissa makasi suuri joukko sairaita, sokeita, ontuvia, halvatuita, jotka veden liikuttamista odottivat.","Joissa makasi suuri joukko sairaita, sokeita, ontuvia, halvatuita, jotka veden liikuttamista odottivat."],[5,4,"Sillä enkeli tuli alas määrätyllä ajalla lammikkoon ja sekoitti veden: joka siis ensimäisenä veteen astui, kuin se sekoitettu oli, niin se parani, ehkä missä ikänä taudissa hän oli.","Sillä enkeli tuli alas määrätyllä ajalla lammikkoon ja sekoitti veden: joka siis ensimäisenä veteen astui, kuin se sekoitettu oli, niin se parani, ehkä missä ikänä taudissa hän oli."],[5,5,"Niin oli siellä mies, joka kahdeksanneljättäkymmentä ajastaikaa oli sairastanut.","Niin oli siellä mies, joka kahdeksanneljättäkymmentä ajastaikaa oli sairastanut."],[5,6,"Kuin Jesus hänen näki makaavan ja tunsi hänen jo kauvan sairastaneen, sanoi hän hänelle: tahdotkos tulla terveeksi?","Kuin Jesus hänen näki makaavan ja tunsi hänen jo kauvan sairastaneen, sanoi hän hänelle: tahdotkos tulla terveeksi?"],[5,7,"Sairas vastasi häntä: Herra, ei ole minulla sitä ihmistä, joka minun vie, kuin vesi sekoitettu on, lammikkoon; mutta kuin minä tulen, niin on toinen minun edelläni siihen astunut.","Sairas vastasi häntä: Herra, ei ole minulla sitä ihmistä, joka minun vie, kuin vesi sekoitettu on, lammikkoon; mutta kuin minä tulen, niin on toinen minun edelläni siihen astunut."],[5,8,"Jesus sanoi hänelle: nouse, ota vuotees ja käy.","Jesus sanoi hänelle: nouse, ota vuotees ja käy."],[5,9,"Ja kohta parani se ihminen, ja otti vuoteensa ja kävi. Ja se päivä oli sabbati.","Ja kohta parani se ihminen, ja otti vuoteensa ja kävi. Ja se päivä oli sabbati."],[5,10,"Sanoivat siis Juudalaiset paratulle: nyt on sabbati, ei sinun sovi vuodetta kantaa.","Sanoivat siis Juudalaiset paratulle: nyt on sabbati, ei sinun sovi vuodetta kantaa."],[5,11,"Hän vastasi heitä: joka minun paransi, se sanoi minulle: ota vuotees ja käy.","Hän vastasi heitä: joka minun paransi, se sanoi minulle: ota vuotees ja käy."],[5,12,"Niin he kysyivät häneltä: kuka on se ihminen, joka sinulle sanoi: ota vuotees ja käy?","Niin he kysyivät häneltä: kuka on se ihminen, joka sinulle sanoi: ota vuotees ja käy?"],[5,13,"Mutta ei parattu tietänyt, kuka se oli; sillä Jesus oli mennyt pois kansan tähden, joka siinä paikassa oli.","Mutta ei parattu tietänyt, kuka se oli; sillä Jesus oli mennyt pois kansan tähden, joka siinä paikassa oli."],[5,14,"Sitte löysi Jesus hänen templissä ja sanoi hänelle: katso, sinä olet parattu: älä silleen syntiä tee, ettei jotain pahempaa sinulle tapahtuisi.","Sitte löysi Jesus hänen templissä ja sanoi hänelle: katso, sinä olet parattu: älä silleen syntiä tee, ettei jotain pahempaa sinulle tapahtuisi."],[5,15,"Niin se ihminen meni pois ja ilmoitti Juudalaisille, että Jesus oli se, joka hänen parantanut oli.","Niin se ihminen meni pois ja ilmoitti Juudalaisille, että Jesus oli se, joka hänen parantanut oli."],[5,16,"Ja Juudalaiset vainosivat sentähden Jesusta ja etsivät häntä tappaaksensa, että hän senkaltaisia teki sabbatina.","Ja Juudalaiset vainosivat sentähden Jesusta ja etsivät häntä tappaaksensa, että hän senkaltaisia teki sabbatina."],[5,17,"Niin Jesus vastasi heitä: minun isäni tekee työtä hamaan tähän asti, ja minä myös teen työtä.","Niin Jesus vastasi heitä: minun isäni tekee työtä hamaan tähän asti, ja minä myös teen työtä."],[5,18,"Sentähden etsivät Juudalaiset häntä vielä enemmin tappaaksensa, ettei hän ainoastaan sabbatia rikkonut, mutta myös sanoi Jumalan isäksensä, ja teki itsensä Jumalan kaltaiseksi.","Sentähden etsivät Juudalaiset häntä vielä enemmin tappaaksensa, ettei hän ainoastaan sabbatia rikkonut, mutta myös sanoi Jumalan isäksensä, ja teki itsensä Jumalan kaltaiseksi."],[5,19,"Niin Jesus vastasi ja sanoi heille: totisesti, totisesti sanon minä teille: ei taida Poika itsestänsä mitään tehdä, ellei hän näe Isän tekevän; sillä mitä ikänä hän tekee, sitä myös Poika niin tekee.","Niin Jesus vastasi ja sanoi heille: totisesti, totisesti sanon minä teille: ei taida Poika itsestänsä mitään tehdä, ellei hän näe Isän tekevän; sillä mitä ikänä hän tekee, sitä myös Poika niin tekee."],[5,20,"Sillä Isä rakastaa Poikaa ja osoittaa hänelle kaikki, mitä hän itse tekee, ja hän on vielä suurempia töitä hänelle osoittava, kuin nämät ovat, että teidän pitää ihmettelemän.","Sillä Isä rakastaa Poikaa ja osoittaa hänelle kaikki, mitä hän itse tekee, ja hän on vielä suurempia töitä hänelle osoittava, kuin nämät ovat, että teidän pitää ihmettelemän."],[5,21,"Sillä niinkuin Isä herättää ja virvoittaa kuolleita, niin myös Poika virvoittaa, joita hän tahtoo.","Sillä niinkuin Isä herättää ja virvoittaa kuolleita, niin myös Poika virvoittaa, joita hän tahtoo."],[5,22,"Sillä ei Isä ketään tuomitse, vaan antoi kaiken tuomion Pojalle:","Sillä ei Isä ketään tuomitse, vaan antoi kaiken tuomion Pojalle:"],[5,23,"Että kaikki Poikaa kunnioittaisivat, niinkuin he Isää kunnioittavat. Joka ei Poikaa kunnioita, ei se kunnioita Isää, joka hänen lähetti.","Että kaikki Poikaa kunnioittaisivat, niinkuin he Isää kunnioittavat. Joka ei Poikaa kunnioita, ei se kunnioita Isää, joka hänen lähetti."],[5,24,"Totisesti, totisesti sanon minä teille: joka kuulee minun sanani ja uskoo sen, joka minun lähetti, hänellä on ijankaikkinen elämä, ja ei hän tule tuomioon, vaan menee kuolemasta elämään.","Totisesti, totisesti sanon minä teille: joka kuulee minun sanani ja uskoo sen, joka minun lähetti, hänellä on ijankaikkinen elämä, ja ei hän tule tuomioon, vaan menee kuolemasta elämään."],[5,25,"Totisesti, totisesti sanon minä teille: hetki tulee, ja nyt jo on, että kuolleet saavat kuulla Jumalan Pojan äänen; ja jotka sen kuulevat, ne saavat elää.","Totisesti, totisesti sanon minä teille: hetki tulee, ja nyt jo on, että kuolleet saavat kuulla Jumalan Pojan äänen; ja jotka sen kuulevat, ne saavat elää."],[5,26,"Sillä niinkuin Isällä on elämä itsessänsä, niin antoi hän myös elämän Pojalle itsessänsä olemaan,","Sillä niinkuin Isällä on elämä itsessänsä, niin antoi hän myös elämän Pojalle itsessänsä olemaan,"],[5,27,"Ja on hänellä myös antanut vallan tuomita, että hän on Ihmisen Poika.","Ja on hänellä myös antanut vallan tuomita, että hän on Ihmisen Poika."],[5,28,"Älkää tätä ihmetelkö; sillä hetki tulee, jona kaikki ne, jotka haudoissa ovat, saavat kuulla hänen äänensä.","Älkää tätä ihmetelkö; sillä hetki tulee, jona kaikki ne, jotka haudoissa ovat, saavat kuulla hänen äänensä."],[5,29,"Ja pitää tuleman edes ne, jotka hyvää tehneet ovat, elämän ylösnousemiseen, mutta jotka pahaa tehneet ovat, tuomion ylösnousemiseen.","Ja pitää tuleman edes ne, jotka hyvää tehneet ovat, elämän ylösnousemiseen, mutta jotka pahaa tehneet ovat, tuomion ylösnousemiseen."],[5,30,"En minä itsestäni taida mitään tehdä: niinkuin minä kuulen, niin minä tuomitsen, ja minun tuomioni on oikia; sillä en minä etsi minun tahtoani, vaan Isän tahtoa, joka minun lähetti.","En minä itsestäni taida mitään tehdä: niinkuin minä kuulen, niin minä tuomitsen, ja minun tuomioni on oikia; sillä en minä etsi minun tahtoani, vaan Isän tahtoa, joka minun lähetti."],[5,31,"Jos minä itsestäni todistaisin, niin ei minun todistukseni olisi tosi.","Jos minä itsestäni todistaisin, niin ei minun todistukseni olisi tosi."],[5,32,"Toinen on, joka todistaa minusta, ja minä tiedän, että hänen todistuksensa on tosi, jonka hän minusta todistaa.","Toinen on, joka todistaa minusta, ja minä tiedän, että hänen todistuksensa on tosi, jonka hän minusta todistaa."],[5,33,"Te lähetitte Johanneksen tykö, ja hän todisti totuuden.","Te lähetitte Johanneksen tykö, ja hän todisti totuuden."],[5,34,"Mutta en minä ihmiseltä todistusta ota; vaan minä sanoin näitä, että te autuaaksi tulisitte.","Mutta en minä ihmiseltä todistusta ota; vaan minä sanoin näitä, että te autuaaksi tulisitte."],[5,35,"Hän oli palavainen ja paistavainen kynttilä; mutta te tahdoitte ainoastaan vähän aikaan riemuita hänen valkeudessansa.","Hän oli palavainen ja paistavainen kynttilä; mutta te tahdoitte ainoastaan vähän aikaan riemuita hänen valkeudessansa."],[5,36,"Mutta minulla on suurempi todistus kuin Johanneksen; sillä ne työt, jotka Isä antoi minulle täyttääkseni, ne työt, jotka minä teen, todistavat minusta, että Isä minun lähetti,","Mutta minulla on suurempi todistus kuin Johanneksen; sillä ne työt, jotka Isä antoi minulle täyttääkseni, ne työt, jotka minä teen, todistavat minusta, että Isä minun lähetti,"],[5,37,"Ja Isä, joka minun lähetti, hän todistaa minusta. Ette ole koskaan hänen ääntänsä kuulleet eli hänen muotoansa nähneet,","Ja Isä, joka minun lähetti, hän todistaa minusta. Ette ole koskaan hänen ääntänsä kuulleet eli hänen muotoansa nähneet,"],[5,38,"Ja ei teillä ole hänen sanansa pysyväinen; sillä ette usko sitä, jonka hän lähetti.","Ja ei teillä ole hänen sanansa pysyväinen; sillä ette usko sitä, jonka hän lähetti."],[5,39,"Tutkikaat Raamatuita; sillä niissä te luulette teillänne ijankaikkisen elämän olevan, ja ne ovat, jotka todistavat minusta.","Tutkikaat Raamatuita; sillä niissä te luulette teillänne ijankaikkisen elämän olevan, ja ne ovat, jotka todistavat minusta."],[5,40,"Ja ette tahdo tulla minun tyköni, että te saisitte elämän.","Ja ette tahdo tulla minun tyköni, että te saisitte elämän."],[5,41,"En minä pyydä kunniaa ihmisiltä;","En minä pyydä kunniaa ihmisiltä;"],[5,42,"Vaan minä tunnen teidät, ettei teissä ole Jumalan rakkaus.","Vaan minä tunnen teidät, ettei teissä ole Jumalan rakkaus."],[5,43,"Minä tulin Isäni nimeen, ja ette minua ota vastaan; jos joku tulee omalla nimellänsä, niin te sen otatte vastaan.","Minä tulin Isäni nimeen, ja ette minua ota vastaan; jos joku tulee omalla nimellänsä, niin te sen otatte vastaan."],[5,44,"Kuinka te taidatte uskoa, jotka otatte kunnian toinen toiseltanne, ja sitä kunniaa, joka ainoalta Jumalalta tulee, ette etsi?","Kuinka te taidatte uskoa, jotka otatte kunnian toinen toiseltanne, ja sitä kunniaa, joka ainoalta Jumalalta tulee, ette etsi?"],[5,45,"Älkäät luulko, että minä minä kannan Isän edessä teidän päällenne: se on, joka teidän päällenne kantaa, Moses, johonka te turvaatte.","Älkäät luulko, että minä minä kannan Isän edessä teidän päällenne: se on, joka teidän päällenne kantaa, Moses, johonka te turvaatte."],[5,46,"Sillä jos te olisitte Moseksen uskoneet, niin te olisitte minun uskoneet; sillä minusta on hän kirjoittanut.","Sillä jos te olisitte Moseksen uskoneet, niin te olisitte minun uskoneet; sillä minusta on hän kirjoittanut."],[5,47,"Jos ette hänen kirjoituksiansa usko, kuinkas te minun sanani uskotte?","Jos ette hänen kirjoituksiansa usko, kuinkas te minun sanani uskotte?"],[6,1,"Sitte meni Jesus Galilean meren ylitse, joka on Tiberiaan,","Sitte meni Jesus Galilean meren ylitse, joka on Tiberiaan,"],[6,2,"Ja häntä seurasi paljo kansaa, että he näkivät hänen merkkinsä, joita hän teki sairaissa.","Ja häntä seurasi paljo kansaa, että he näkivät hänen merkkinsä, joita hän teki sairaissa."],[6,3,"Niin Jesus meni ylös vuorelle ja istui siellä opetuslastensa kanssa.","Niin Jesus meni ylös vuorelle ja istui siellä opetuslastensa kanssa."],[6,4,"Ja lähestyi pääsiäinen, Juudalaisten juhla.","Ja lähestyi pääsiäinen, Juudalaisten juhla."],[6,5,"Kuin siis Jesus nosti silmänsä ja näki tulevan paljon kansaa tykönsä, sanoi hän Philippukselle: kusta me ostamme leipiä näiden syödä?","Kuin siis Jesus nosti silmänsä ja näki tulevan paljon kansaa tykönsä, sanoi hän Philippukselle: kusta me ostamme leipiä näiden syödä?"],[6,6,"(Mutta sen hän sanoi, kiusaten häntä: sillä hän tiesi, mitä hän tekevä oli.)","(Mutta sen hän sanoi, kiusaten häntä: sillä hän tiesi, mitä hän tekevä oli.)"],[6,7,"Vastasi Philippus häntä: kahdensadan penningin leivät ei täytyisi heille, että kukin heistä vähänkin sais.","Vastasi Philippus häntä: kahdensadan penningin leivät ei täytyisi heille, että kukin heistä vähänkin sais."],[6,8,"Sanoi yksi hänen opetuslapsistansa hänelle: Andreas, Simon Pietarin veli:","Sanoi yksi hänen opetuslapsistansa hänelle: Andreas, Simon Pietarin veli:"],[6,9,"Tässä on poikainen, jolla on viisi ohrasta leipää ja kaksi kalaista; vaan mitä ne ovat näin paljolle?","Tässä on poikainen, jolla on viisi ohrasta leipää ja kaksi kalaista; vaan mitä ne ovat näin paljolle?"],[6,10,"Mutta Jesus sanoi: asettakaat kansa atrioitsemaan. ja siinä paikassa oli paljo ruohoa. Niin atrioitsi lähes viisituhatta miestä.","Mutta Jesus sanoi: asettakaat kansa atrioitsemaan. ja siinä paikassa oli paljo ruohoa. Niin atrioitsi lähes viisituhatta miestä."],[6,11,"Ja Jesus otti leivät, kiitti ja antoi opetuslapsille, mutta opetuslapset jakoivat atrioitseville, niin myös kaloista niin paljo kuin hän tahtoi.","Ja Jesus otti leivät, kiitti ja antoi opetuslapsille, mutta opetuslapset jakoivat atrioitseville, niin myös kaloista niin paljo kuin hän tahtoi."],[6,12,"Mutta kuin he ravitut olivat, sanoi hän opetuslapsillensa: kootkaat murut, jotka jäivät, ettei mitään hukkuisi.","Mutta kuin he ravitut olivat, sanoi hän opetuslapsillensa: kootkaat murut, jotka jäivät, ettei mitään hukkuisi."],[6,13,"Niin he kokosivat ja täyttivät kaksitoistakymmentä koria muruilla, viidestä ohraisesta leivästä, jotka niiltä liiaksi olivat, jotka atrioitsivat.","Niin he kokosivat ja täyttivät kaksitoistakymmentä koria muruilla, viidestä ohraisesta leivästä, jotka niiltä liiaksi olivat, jotka atrioitsivat."],[6,14,"Kuin siis ne ihmiset sen merkin näkivät, minkä Jesus teki, sanoivat he: tämä on totisesti se Propheta, joka maailmaan tuleva oli.","Kuin siis ne ihmiset sen merkin näkivät, minkä Jesus teki, sanoivat he: tämä on totisesti se Propheta, joka maailmaan tuleva oli."],[6,15,"Kuin Jesus ymmärsi, että he tahtoivat tulla ja väkivallalla tehdä hänen kuninkaaksi, meni hän pois taas vuorelle yksinänsä.","Kuin Jesus ymmärsi, että he tahtoivat tulla ja väkivallalla tehdä hänen kuninkaaksi, meni hän pois taas vuorelle yksinänsä."],[6,16,"Mutta kuin ehtoo tuli, menivät hänen opetuslapsensa alas meren tykö,","Mutta kuin ehtoo tuli, menivät hänen opetuslapsensa alas meren tykö,"],[6,17,"Ja astuivat haahteen ja menivät ylitse meren Kapernaumia päin. Ja jo oli pimiä tullut, ja ei Jesus tullut heidän tykönsä.","Ja astuivat haahteen ja menivät ylitse meren Kapernaumia päin. Ja jo oli pimiä tullut, ja ei Jesus tullut heidän tykönsä."],[6,18,"Niin meri nousi, että suuri tuuli puhalsi.","Niin meri nousi, että suuri tuuli puhalsi."],[6,19,"Ja kuin he olivat soutaneet lähes viisikolmattakymmentä eli kolmekymmentä vakomittaa, näkivät he Jesuksen käyvän meren päällä ja lähenevän haahta; ja he peljästyivät.","Ja kuin he olivat soutaneet lähes viisikolmattakymmentä eli kolmekymmentä vakomittaa, näkivät he Jesuksen käyvän meren päällä ja lähenevän haahta; ja he peljästyivät."],[6,20,"Niin hän sanoi heille: minä olen; älkäät peljätkö.","Niin hän sanoi heille: minä olen; älkäät peljätkö."],[6,21,"Niin he tahtoivat ottaa hänen haahteen; ja haaksi oli jo sen maan tykönä, johonka he menivät.","Niin he tahtoivat ottaa hänen haahteen; ja haaksi oli jo sen maan tykönä, johonka he menivät."],[6,22,"Toisena päivänä, kuin kansa, joka sillä puolella merta oli, näki, ettei siellä muuta venhettä ollut kuin se yksi, johonka hänen opetuslapsensa olivat astuneet, ja ettei Jesus ollut astunut haahteen opetuslastensa kanssa, vaan hänen opetuslapsensa olivat ainoastaan matkaan lähteneet;","Toisena päivänä, kuin kansa, joka sillä puolella merta oli, näki, ettei siellä muuta venhettä ollut kuin se yksi, johonka hänen opetuslapsensa olivat astuneet, ja ettei Jesus ollut astunut haahteen opetuslastensa kanssa, vaan hänen opetuslapsensa olivat ainoastaan matkaan lähteneet;"],[6,23,"Mutta muut venheet tulivat Tiberiaasta, lähes sitä paikkaa, jossa he olivat leipää syöneet, sitte kuin Herra oli kiittänyt;","Mutta muut venheet tulivat Tiberiaasta, lähes sitä paikkaa, jossa he olivat leipää syöneet, sitte kuin Herra oli kiittänyt;"],[6,24,"Koska kansa sen näki, ettei Jesus siellä ollut eikä hänen opetuslapsensa, astuivat he myös haaksiin ja menivät Kapernaumiin etsein Jesusta.","Koska kansa sen näki, ettei Jesus siellä ollut eikä hänen opetuslapsensa, astuivat he myös haaksiin ja menivät Kapernaumiin etsein Jesusta."],[6,25,"Ja kuin he hänen siltä puolen merta löysivät, sanoivat he hänelle: Rabbi, koskas tänne tulit?","Ja kuin he hänen siltä puolen merta löysivät, sanoivat he hänelle: Rabbi, koskas tänne tulit?"],[6,26,"Jesus vastasi heitä ja sanoi: totisesti, totisesti sanon minä teille: ette etsi minua, että te näitte ihmeen, vaan että te saitte leipää syödä ja olette ravitut.","Jesus vastasi heitä ja sanoi: totisesti, totisesti sanon minä teille: ette etsi minua, että te näitte ihmeen, vaan että te saitte leipää syödä ja olette ravitut."],[6,27,"Älkäät tehkö sitä ruokaa, joka on katoovainen, vaan sitä ruokaa, joka pysyy ijankaikkiseen elämään, jonka Ihmisen Poika teille antava on; sillä Isä Jumala on sen vahvistanut.","Älkäät tehkö sitä ruokaa, joka on katoovainen, vaan sitä ruokaa, joka pysyy ijankaikkiseen elämään, jonka Ihmisen Poika teille antava on; sillä Isä Jumala on sen vahvistanut."],[6,28,"Niin he sanoivat hänelle: mitä meidän pitää tekemän, että me taitaisimme Jumalan töitä tehdä?","Niin he sanoivat hänelle: mitä meidän pitää tekemän, että me taitaisimme Jumalan töitä tehdä?"],[6,29,"Jesus vastasi ja sanoi heille: se on Jumalan työ, että te uskotte sen päälle, jonka hän lähetti.","Jesus vastasi ja sanoi heille: se on Jumalan työ, että te uskotte sen päälle, jonka hän lähetti."],[6,30,"Niin he sanoivat hänelle: mitä ihmettä siis sinä teet, että me näkisimme ja uskoisimme sinun päälles? Mitä työtä sinä teet?","Niin he sanoivat hänelle: mitä ihmettä siis sinä teet, että me näkisimme ja uskoisimme sinun päälles? Mitä työtä sinä teet?"],[6,31,"Meidän isämme söivät mannaa korvessa, niinkuin kirjoitettu on: hän antoi heille leipää taivaasta syödäksensä.","Meidän isämme söivät mannaa korvessa, niinkuin kirjoitettu on: hän antoi heille leipää taivaasta syödäksensä."],[6,32,"Niin Jesus sanoi heille: totisesti, totisesti sanon minä teille: ei Moses sitä leipää antanut teille taivaasta; mutta minun Isäni antaa totisen leivän taivaasta.","Niin Jesus sanoi heille: totisesti, totisesti sanon minä teille: ei Moses sitä leipää antanut teille taivaasta; mutta minun Isäni antaa totisen leivän taivaasta."],[6,33,"Sillä Jumalan leipä on se, joka taivaasta tulee alas ja antaa maailmalle elämän.","Sillä Jumalan leipä on se, joka taivaasta tulee alas ja antaa maailmalle elämän."],[6,34,"Niin he sanoivat hänelle: Herra, anna meille aina sitä leipää.","Niin he sanoivat hänelle: Herra, anna meille aina sitä leipää."],[6,35,"Jesus sanoi heille: minä olen elämän leipä: joka tulee minun tyköni, ei hän suinkaan isoo, ja joka uskoo minun päälleni, ei hän koskaan janoo.","Jesus sanoi heille: minä olen elämän leipä: joka tulee minun tyköni, ei hän suinkaan isoo, ja joka uskoo minun päälleni, ei hän koskaan janoo."],[6,36,"Mutta minä sanoin teille, että te näitte minun, ette sittekään usko.","Mutta minä sanoin teille, että te näitte minun, ette sittekään usko."],[6,37,"Kaikki, mitä minun Isäni antaa minulle, se tulee minun tyköni: ja joka minun tyköni tulee, sitä en minä heitä ulos.","Kaikki, mitä minun Isäni antaa minulle, se tulee minun tyköni: ja joka minun tyköni tulee, sitä en minä heitä ulos."],[6,38,"Sillä minä tulin taivaasta alas, en tekemään minun tahtoani, vaan sen tahtoa, joka minun lähetti.","Sillä minä tulin taivaasta alas, en tekemään minun tahtoani, vaan sen tahtoa, joka minun lähetti."],[6,39,"Mutta se on Isän tahto, joka minun lähetti, ettei minun pidä yhtäkään niistä kaikista kadottaman, jotka hän minulle antoi, mutta olen ne herättävä viimeisenä päivänä.","Mutta se on Isän tahto, joka minun lähetti, ettei minun pidä yhtäkään niistä kaikista kadottaman, jotka hän minulle antoi, mutta olen ne herättävä viimeisenä päivänä."],[6,40,"Tämä on sen tahto, joka minun lähetti, että jokainen joka näkee Pojan ja uskoo hänen päällensä, hänellä pitää ijankaikkinen elämä oleman, ja minä herätän hänen viimeisenä päivänä.","Tämä on sen tahto, joka minun lähetti, että jokainen joka näkee Pojan ja uskoo hänen päällensä, hänellä pitää ijankaikkinen elämä oleman, ja minä herätän hänen viimeisenä päivänä."],[6,41,"Niin Juudalaiset napisivat sitä, kuin hän sanoi: minä olen se leipä, joka taivaasta tuli alas,","Niin Juudalaiset napisivat sitä, kuin hän sanoi: minä olen se leipä, joka taivaasta tuli alas,"],[6,42,"Ja sanoivat: eikö tämä ole Jesus, Josephin poika, jonka isän ja äidin me tunnemme? Kuinkas hän sanoo: minä olen tullut taivaasta alas.","Ja sanoivat: eikö tämä ole Jesus, Josephin poika, jonka isän ja äidin me tunnemme? Kuinkas hän sanoo: minä olen tullut taivaasta alas."],[6,43,"Niin Jesus vastasi ja sanoi heille: älkäät napisko keskenänne.","Niin Jesus vastasi ja sanoi heille: älkäät napisko keskenänne."],[6,44,"Ei taida kenkään minun tyköni tulla, ellei Isä, joka minun lähetti, vedä häntä, ja minä herätän hänen viimeisenä päivänä.","Ei taida kenkään minun tyköni tulla, ellei Isä, joka minun lähetti, vedä häntä, ja minä herätän hänen viimeisenä päivänä."],[6,45,"Se on prophetaissa kirjoitettu: heidän pitää kaikki Jumalalta opetetuksi tuleman. Sentähden jokainen, joka sen on Isältä kuullut ja oppinut, hän tulee minun tyköni.","Se on prophetaissa kirjoitettu: heidän pitää kaikki Jumalalta opetetuksi tuleman. Sentähden jokainen, joka sen on Isältä kuullut ja oppinut, hän tulee minun tyköni."],[6,46,"Ei niin, että joku on Isän nähnyt, vaan joka on Jumalasta, se on Isän nähnyt.","Ei niin, että joku on Isän nähnyt, vaan joka on Jumalasta, se on Isän nähnyt."],[6,47,"Totisesti, totisesti sanon minä teille: joka uskoo minun päälleni, hänellä on ijankaikkinen elämä.","Totisesti, totisesti sanon minä teille: joka uskoo minun päälleni, hänellä on ijankaikkinen elämä."],[6,48,"Minä olen elämän leipä.","Minä olen elämän leipä."],[6,49,"Teidän isänne söivät mannaa korvessa ja kuolivat.","Teidän isänne söivät mannaa korvessa ja kuolivat."],[6,50,"Tämä on se leipä, joka taivaasta tuli alas, ja joka siitä syö, ei hänen pidä kuoleman.","Tämä on se leipä, joka taivaasta tuli alas, ja joka siitä syö, ei hänen pidä kuoleman."],[6,51,"Minä olen elävä leipä, joka taivaasta tuli alas: se joka tästä leivästä syö, hän elää ijankaikkisesti. Ja se leipä, jonka minä annan, on minun lihani, jonka minun pitää antaman maailman elämän edestä.","Minä olen elävä leipä, joka taivaasta tuli alas: se joka tästä leivästä syö, hän elää ijankaikkisesti. Ja se leipä, jonka minä annan, on minun lihani, jonka minun pitää antaman maailman elämän edestä."],[6,52,"Niin Juudalaiset riitelivät keskenänsä, sanoen: kuinka tämä taitaa antaa lihansa meille syödä?","Niin Juudalaiset riitelivät keskenänsä, sanoen: kuinka tämä taitaa antaa lihansa meille syödä?"],[6,53,"Jesus sanoi heille: totisesti, totisesti sanon minä teille: ellette syö Ihmisen Pojan lihaa ja juo hänen vertansa, niin ei ole elämä teissä.","Jesus sanoi heille: totisesti, totisesti sanon minä teille: ellette syö Ihmisen Pojan lihaa ja juo hänen vertansa, niin ei ole elämä teissä."],[6,54,"Joka syö minun lihani ja juo minun vereni, hänellä on ijankaikkinen elämä, ja minä olen herättävä hänen viimeisenä päivänä.","Joka syö minun lihani ja juo minun vereni, hänellä on ijankaikkinen elämä, ja minä olen herättävä hänen viimeisenä päivänä."],[6,55,"sillä minun lihani on totinen ruoka, ja minun vereni on totinen juoma.","sillä minun lihani on totinen ruoka, ja minun vereni on totinen juoma."],[6,56,"Joka syö minun lihani ja juo minun vereni, hän on minussa ja minä hänessä.","Joka syö minun lihani ja juo minun vereni, hän on minussa ja minä hänessä."],[6,57,"Niinkuin elävä Isä minun lähetti ja minä elän Isäni tähden, niin myös se, joka minua syö, hän elää minun tähteni.","Niinkuin elävä Isä minun lähetti ja minä elän Isäni tähden, niin myös se, joka minua syö, hän elää minun tähteni."],[6,58,"Tämä on se leipä, joka taivaasta tuli alas: ei niinkuin teidän isänne söivät mannaa ja kuolivat: Joka tätä leipää syö, hän saa elää ijankaikkisesti.","Tämä on se leipä, joka taivaasta tuli alas: ei niinkuin teidän isänne söivät mannaa ja kuolivat: Joka tätä leipää syö, hän saa elää ijankaikkisesti."],[6,59,"Näitä sanoi hän synagogassa, opettaissansa Kapernaumissa.","Näitä sanoi hän synagogassa, opettaissansa Kapernaumissa."],[6,60,"Niin monta hänen opetuslapsistansa, kuin he tämän kuulivat, sanoivat: tämä on kova puhe: kuka voi sitä kuulla?","Niin monta hänen opetuslapsistansa, kuin he tämän kuulivat, sanoivat: tämä on kova puhe: kuka voi sitä kuulla?"],[6,61,"Mutta kuin Jesus tiesi itsestänsä, että hänen opetuslapsensa siitä napisivat, sanoi hän heille: pahoittaako tämä teitä?","Mutta kuin Jesus tiesi itsestänsä, että hänen opetuslapsensa siitä napisivat, sanoi hän heille: pahoittaako tämä teitä?"],[6,62,"Mitä sitte, jos te näette Ihmisen Pojan sinne menevän ylös, kussa hän ennen oli?","Mitä sitte, jos te näette Ihmisen Pojan sinne menevän ylös, kussa hän ennen oli?"],[6,63,"Henki on se, joka eläväksi tekee, ei liha mitään auta: ne sanat, jotka minä teille puhun, ovat henki ja elämä.","Henki on se, joka eläväksi tekee, ei liha mitään auta: ne sanat, jotka minä teille puhun, ovat henki ja elämä."],[6,64,"Mutta muutamat teistä ovat, jotka ei usko. Sillä Jesus tiesi alusta, kutka ovat, jotka ei uskoneet, ja kuka hänen oli pettävä.","Mutta muutamat teistä ovat, jotka ei usko. Sillä Jesus tiesi alusta, kutka ovat, jotka ei uskoneet, ja kuka hänen oli pettävä."],[6,65,"Ja hän sanoi: sentähden sanoin minä teille: ei taida kenkään tulla minun tyköni, ellei se ole annettu hänelle minun Isältäni.","Ja hän sanoi: sentähden sanoin minä teille: ei taida kenkään tulla minun tyköni, ellei se ole annettu hänelle minun Isältäni."],[6,66,"Siitä ajasta luopuivat monta hänen opetuslastansa hänestä ja menivät pois, eikä hänen kanssansa enempi vaeltaneet.","Siitä ajasta luopuivat monta hänen opetuslastansa hänestä ja menivät pois, eikä hänen kanssansa enempi vaeltaneet."],[6,67,"Niin Jesus sanoi niille kahdelletoistakymmenelle: ettekö te myös tahdo mennä pois?","Niin Jesus sanoi niille kahdelletoistakymmenelle: ettekö te myös tahdo mennä pois?"],[6,68,"Simon Pietari vastasi häntä: Herra, kenenkäs tykö me menemme? sinulla on ijankaikkisen elämän sanat,","Simon Pietari vastasi häntä: Herra, kenenkäs tykö me menemme? sinulla on ijankaikkisen elämän sanat,"],[6,69,"Ja me uskomme ja olemme ymmärtäneet, että sinä olet Kristus, elävän Jumalan Poika?","Ja me uskomme ja olemme ymmärtäneet, että sinä olet Kristus, elävän Jumalan Poika?"],[6,70,"Jesus vastasi heitä: enkö minä ole teitä kahtatoistakymmentä valinnut? ja yksi teistä on perkele.","Jesus vastasi heitä: enkö minä ole teitä kahtatoistakymmentä valinnut? ja yksi teistä on perkele."],[6,71,"Mutta sen hän sanoi Juudaasta, Simonin pojasta Iskariotista; sillä hän oli hänen pettävä, ja oli yksi niistä kahdestatoistakymmenestä.","Mutta sen hän sanoi Juudaasta, Simonin pojasta Iskariotista; sillä hän oli hänen pettävä, ja oli yksi niistä kahdestatoistakymmenestä."],[7,1,"Ja sitte vaelsi Jesus Galileassa; sillä ei hän tahtonut vaeltaa Juudeassa, että Juudalaiset pyysivät häntä tappaa.","Ja sitte vaelsi Jesus Galileassa; sillä ei hän tahtonut vaeltaa Juudeassa, että Juudalaiset pyysivät häntä tappaa."],[7,2,"Niin Juudalaisten lehtimajan juhla oli läsnä.","Niin Juudalaisten lehtimajan juhla oli läsnä."],[7,3,"Ja hänen veljensä sanoivat hänelle: lähde täältä ja mene Juudeaan, että myös sinun opetuslapses näkisivät sinun työs, joita sinä teet.","Ja hänen veljensä sanoivat hänelle: lähde täältä ja mene Juudeaan, että myös sinun opetuslapses näkisivät sinun työs, joita sinä teet."],[7,4,"Sillä ei kenkään tee mitään salaa, ja tahtoo itse julki olla. Jos siis sinä näitä teet, niin julista itses maailman edessä.","Sillä ei kenkään tee mitään salaa, ja tahtoo itse julki olla. Jos siis sinä näitä teet, niin julista itses maailman edessä."],[7,5,"Sillä ei hänen veljensäkään uskoneet hänen päällensä.","Sillä ei hänen veljensäkään uskoneet hänen päällensä."],[7,6,"Niin Jesus sanoi heille: ei ole minun aikani vielä tullut; vaan teidän aikanne on aina valmis.","Niin Jesus sanoi heille: ei ole minun aikani vielä tullut; vaan teidän aikanne on aina valmis."],[7,7,"Ei maailma taida teitä vihata, mutta minua hän vihaa; sillä minä todistan hänestä, että hänen työnsä ovat pahat.","Ei maailma taida teitä vihata, mutta minua hän vihaa; sillä minä todistan hänestä, että hänen työnsä ovat pahat."],[7,8,"Menkäät te ylös juhlalle: en minä vielä tälle juhlalle mene, sillä ei minun aikani ole vielä täytetty.","Menkäät te ylös juhlalle: en minä vielä tälle juhlalle mene, sillä ei minun aikani ole vielä täytetty."],[7,9,"Ja kuin hän näitä heille puhunut oli, niin hän jäi Galileaan.","Ja kuin hän näitä heille puhunut oli, niin hän jäi Galileaan."],[7,10,"Mutta kuin hänen veljensä olivat menneet ylös, meni hän myös juhlalle, ei julki, vaan niinkuin salaa.","Mutta kuin hänen veljensä olivat menneet ylös, meni hän myös juhlalle, ei julki, vaan niinkuin salaa."],[7,11,"Niin Juudalaiset etsivät häntä juhlana ja sanoivat: kussa hän on?","Niin Juudalaiset etsivät häntä juhlana ja sanoivat: kussa hän on?"],[7,12,"Ja suuri napina oli hänestä kansan seassa; sillä muutamat sanoivat: hän on hyvä, mutta toiset sanoivat: ei, vaan hän viettelee kansan.","Ja suuri napina oli hänestä kansan seassa; sillä muutamat sanoivat: hän on hyvä, mutta toiset sanoivat: ei, vaan hän viettelee kansan."],[7,13,"Ei kuitenkaan yksikään hänestä julkisesti puhunut; sillä he pelkäsivät Juudalaisia.","Ei kuitenkaan yksikään hänestä julkisesti puhunut; sillä he pelkäsivät Juudalaisia."],[7,14,"Mutta kuin jo puoli juhlaa oli kulunut, meni Jesus ylös templiin, ja opetti.","Mutta kuin jo puoli juhlaa oli kulunut, meni Jesus ylös templiin, ja opetti."],[7,15,"Ja Juudalaiset ihmettelivät, sanoen: kuinka tämä taitaa kirjaa, joka ei ole oppinut?","Ja Juudalaiset ihmettelivät, sanoen: kuinka tämä taitaa kirjaa, joka ei ole oppinut?"],[7,16,"Vastasi Jesus ja sanoi heille: ei minun oppini ole minun, mutta sen, joka minun lähetti.","Vastasi Jesus ja sanoi heille: ei minun oppini ole minun, mutta sen, joka minun lähetti."],[7,17,"Jos joku tahtoo tehdä hänen tahtonsa, niin hänen pitää tietämän tästä opista, josko se on Jumalasta, eli jos minä itsestäni puhun.","Jos joku tahtoo tehdä hänen tahtonsa, niin hänen pitää tietämän tästä opista, josko se on Jumalasta, eli jos minä itsestäni puhun."],[7,18,"Joka itsestänsä puhuu, se etsii omaa kunniaansa: mutta joka etsii sen kunniaa, joka hänen lähetti, se on vakaa ja ei hänessä ole vääryyttä.","Joka itsestänsä puhuu, se etsii omaa kunniaansa: mutta joka etsii sen kunniaa, joka hänen lähetti, se on vakaa ja ei hänessä ole vääryyttä."],[7,19,"Eikö Moses antanut teille lakia, ja ei kenkään teistä lakia taytä? Miksi te etsitte minua tappaaksenne?","Eikö Moses antanut teille lakia, ja ei kenkään teistä lakia taytä? Miksi te etsitte minua tappaaksenne?"],[7,20,"Vastasi kansa ja sanoi: sinulla on perkele: kuka sinua etsii tappaaksensa?","Vastasi kansa ja sanoi: sinulla on perkele: kuka sinua etsii tappaaksensa?"],[7,21,"Jesus vastasi ja sanoi heille: yhden työn minä tein, ja te kaikki ihmettelette.","Jesus vastasi ja sanoi heille: yhden työn minä tein, ja te kaikki ihmettelette."],[7,22,"Sentähden antoi Moses teille ympärileikkauksen, (ei että se Mosekselta oli, vaan isiltä), ja te ympärileikkaatte sabbatina ihmisen.","Sentähden antoi Moses teille ympärileikkauksen, (ei että se Mosekselta oli, vaan isiltä), ja te ympärileikkaatte sabbatina ihmisen."],[7,23,"Jos ihminen sabbatina ympärileikataan, ettei Moseksen laki rikottaisi: närkästyttekö te minusta, että minä koko ihmisen sabbatina paransin?","Jos ihminen sabbatina ympärileikataan, ettei Moseksen laki rikottaisi: närkästyttekö te minusta, että minä koko ihmisen sabbatina paransin?"],[7,24,"Älkäät tuomitko näkemisen jälkeen, vaan sanokaat oikia tuomio.","Älkäät tuomitko näkemisen jälkeen, vaan sanokaat oikia tuomio."],[7,25,"Sanoivat siis muutamat Jerusalemin asuvaisista: eikö tämä se ole, jota he etsivät tappaaksensa?","Sanoivat siis muutamat Jerusalemin asuvaisista: eikö tämä se ole, jota he etsivät tappaaksensa?"],[7,26,"Ja katso, hän puhuu rohkiasti, ja ei he hänelle mitään puhu: tietänevätkö ylimmäiset oikein, että hän on totisesti Kristus?","Ja katso, hän puhuu rohkiasti, ja ei he hänelle mitään puhu: tietänevätkö ylimmäiset oikein, että hän on totisesti Kristus?"],[7,27,"Mutta me kyllä tiedämme, kusta tämä on: vaan kusta Kristus tulee ja kusta hän on, ei kenkään tiedä.","Mutta me kyllä tiedämme, kusta tämä on: vaan kusta Kristus tulee ja kusta hän on, ei kenkään tiedä."],[7,28,"Niin Jesus huusi templissä, opetti ja sanoi: ja te tunnette minun, ja tiedätte, kusta minä olen: ja en minä ole tullut itsestäni, mutta hän on vakaa, joka minun lähetti, jota ette tunne.","Niin Jesus huusi templissä, opetti ja sanoi: ja te tunnette minun, ja tiedätte, kusta minä olen: ja en minä ole tullut itsestäni, mutta hän on vakaa, joka minun lähetti, jota ette tunne."],[7,29,"Mutta minä tunnen hänen, sillä minä olen hänestä, ja hän lähetti minun.","Mutta minä tunnen hänen, sillä minä olen hänestä, ja hän lähetti minun."],[7,30,"Niin he etsivät häntä käsittääksensä; vaan ei kenkään laskenut kättänsä hänen päällensä, sillä ei hänen aikansa ollut vielä tullut.","Niin he etsivät häntä käsittääksensä; vaan ei kenkään laskenut kättänsä hänen päällensä, sillä ei hänen aikansa ollut vielä tullut."],[7,31,"Mutta paljo kansasta uskoivat hänen päällensä ja sanoivat: kuin Kristus tulee, tehneekö hän enemmän ihmeitä kuin tämä on tehnyt?","Mutta paljo kansasta uskoivat hänen päällensä ja sanoivat: kuin Kristus tulee, tehneekö hän enemmän ihmeitä kuin tämä on tehnyt?"],[7,32,"Pharisealaiset kuulivat kansan hänestä senkaltaisia napisevan, ja Pharisealaiset ja ylimmäiset papit lähettivät palveliat häntä ottamaan kiinni.","Pharisealaiset kuulivat kansan hänestä senkaltaisia napisevan, ja Pharisealaiset ja ylimmäiset papit lähettivät palveliat häntä ottamaan kiinni."],[7,33,"Niin Jesus sanoi heille: minä olen vielä vähän aikaa teidän kanssanne, ja menen sitte hänen tykönsä, joka minun lähetti.","Niin Jesus sanoi heille: minä olen vielä vähän aikaa teidän kanssanne, ja menen sitte hänen tykönsä, joka minun lähetti."],[7,34,"Teidän pitää minua etsimän ja ei löytämän, ja kussa minä olen, ette taida sinne tulla.","Teidän pitää minua etsimän ja ei löytämän, ja kussa minä olen, ette taida sinne tulla."],[7,35,"Niin Juudalaiset sanoivat keskenänsä: kuhunkas hän menee, ettemme häntä löydä? meneekö hän Grekiläisten sekaan, jotka sinne ja tänne hajoitetut ovat, Grekiläisiä opettamaan?","Niin Juudalaiset sanoivat keskenänsä: kuhunkas hän menee, ettemme häntä löydä? meneekö hän Grekiläisten sekaan, jotka sinne ja tänne hajoitetut ovat, Grekiläisiä opettamaan?"],[7,36,"Mikä puhe se on, minkä hän sanoi: teidän pitää etsimän minua ja ei löytämän, ja kussa minä olen, ette taida sinne tulla?","Mikä puhe se on, minkä hän sanoi: teidän pitää etsimän minua ja ei löytämän, ja kussa minä olen, ette taida sinne tulla?"],[7,37,"Mutta viimeisenä suurena juhlapäivänä seisoi Jesus ja huusi, sanoen: joka janoo, se tulkaan minun tyköni ja juokaan.","Mutta viimeisenä suurena juhlapäivänä seisoi Jesus ja huusi, sanoen: joka janoo, se tulkaan minun tyköni ja juokaan."],[7,38,"Joka uskoo minun päälleni, niinkuin Raamattu sanoo, hänen kohdustansa pitää vuotaman elämän veden virrat.","Joka uskoo minun päälleni, niinkuin Raamattu sanoo, hänen kohdustansa pitää vuotaman elämän veden virrat."],[7,39,"(Mutta sen hän sanoi siitä hengestä, jonka niiden piti saaman, jotka uskovat hänen päällensä; sillä ei Pyhä Henki vielä silloin saapuvilla ollut, ettei Jesus ollut vielä kirkastettu.)","(Mutta sen hän sanoi siitä hengestä, jonka niiden piti saaman, jotka uskovat hänen päällensä; sillä ei Pyhä Henki vielä silloin saapuvilla ollut, ettei Jesus ollut vielä kirkastettu.)"],[7,40,"Monta siis kansasta, jotka tämän puheen kuulivat, sanoivat: tämä on totisesti propheta.","Monta siis kansasta, jotka tämän puheen kuulivat, sanoivat: tämä on totisesti propheta."],[7,41,"Muut sanoivat: tämä on Kristus; mutta muutamat sanoivat: tulleeko Kristus Galileasta?","Muut sanoivat: tämä on Kristus; mutta muutamat sanoivat: tulleeko Kristus Galileasta?"],[7,42,"Eikö Raamattu sano Davidin siemenestä ja Betlehemin kaupungista, kussa David oli, Kristuksen tulevan?","Eikö Raamattu sano Davidin siemenestä ja Betlehemin kaupungista, kussa David oli, Kristuksen tulevan?"],[7,43,"Niin nousi riita kansan seassa hänen tähtensä.","Niin nousi riita kansan seassa hänen tähtensä."],[7,44,"Mutta muutamat tahtoivat hänen ottaa kiinni, ja ei kuitenkaan kenkään laskenut käsiänsä hänen päällensä.","Mutta muutamat tahtoivat hänen ottaa kiinni, ja ei kuitenkaan kenkään laskenut käsiänsä hänen päällensä."],[7,45,"Niin palveliat tulivat Pharisealaisten ja ylimmäisten pappein tykö, ja he sanoivat heille: miksi ette häntä tänne tuoneet?","Niin palveliat tulivat Pharisealaisten ja ylimmäisten pappein tykö, ja he sanoivat heille: miksi ette häntä tänne tuoneet?"],[7,46,"Palveliat vastasivat: ei ole ihminen ikänä niin puhunut kuin se ihminen.","Palveliat vastasivat: ei ole ihminen ikänä niin puhunut kuin se ihminen."],[7,47,"Pharisealaiset vastasivat heitä: oletteko te myös vietellyt?","Pharisealaiset vastasivat heitä: oletteko te myös vietellyt?"],[7,48,"Onko joku päämiehistä taikka Pharisealaisista uskonut hänen päällensä?","Onko joku päämiehistä taikka Pharisealaisista uskonut hänen päällensä?"],[7,49,"Vaan tämä kansa, joka ei tiedä lakia, on kirottu.","Vaan tämä kansa, joka ei tiedä lakia, on kirottu."],[7,50,"Niin sanoi heille Nikodemus, joka yöllä oli hänen tykönsä tullut, ja oli yksi heistä:","Niin sanoi heille Nikodemus, joka yöllä oli hänen tykönsä tullut, ja oli yksi heistä:"],[7,51,"Tuomitseeko meidän lakimme jonkun ihmisen, ennenkuin kuullaan eli tietää saadaan, mitä hän teki?","Tuomitseeko meidän lakimme jonkun ihmisen, ennenkuin kuullaan eli tietää saadaan, mitä hän teki?"],[7,52,"He vastasivat ja sanoivat hänelle: oletko sinäkin Galilealainen? tutki ja näe, ettei Galileasta ole yhtään prophetaa tullut.","He vastasivat ja sanoivat hänelle: oletko sinäkin Galilealainen? tutki ja näe, ettei Galileasta ole yhtään prophetaa tullut."],[7,53,"Ja niin kukin meni kotiansa.","Ja niin kukin meni kotiansa."],[8,1,"Mutta Jesus meni Öljymäelle,","Mutta Jesus meni Öljymäelle,"],[8,2,"Ja tuli varhain huomeneltain jälleen templiin ja kaikki kansa tuli hänen tykönsä, ja hän istui ja opetti heitä.","Ja tuli varhain huomeneltain jälleen templiin ja kaikki kansa tuli hänen tykönsä, ja hän istui ja opetti heitä."],[8,3,"Mutta kirjanoppineet ja Pharisealaiset toivat vaimon hänen tykönsä huoruudesta otetun kiinni. Ja kuin he olivat sen hänen eteensä asettaneet,","Mutta kirjanoppineet ja Pharisealaiset toivat vaimon hänen tykönsä huoruudesta otetun kiinni. Ja kuin he olivat sen hänen eteensä asettaneet,"],[8,4,"Sanoivat he hänelle: Mestari, tämä vaimo on löydetty itse työssä, kuin hän teki huorin.","Sanoivat he hänelle: Mestari, tämä vaimo on löydetty itse työssä, kuin hän teki huorin."],[8,5,"Mutta Moses on laissa meitä käskenyt, että senkaltaiset kivillä surmattaisiin. Mitäs sinä sanot?","Mutta Moses on laissa meitä käskenyt, että senkaltaiset kivillä surmattaisiin. Mitäs sinä sanot?"],[8,6,"Mutta sen he sanoivat, kiusaten häntä, kantaaksensa hänen päällensä. Mutta Jesus kumarsi ja kirjoitti sormellansa maahan.","Mutta sen he sanoivat, kiusaten häntä, kantaaksensa hänen päällensä. Mutta Jesus kumarsi ja kirjoitti sormellansa maahan."],[8,7,"Mutta kuin he seisoivat kysymyksensä päälle, ojensi hän itsensä ja sanoi heille: joka teistä on synnitön, se heittäkään ensin häntä kivellä.","Mutta kuin he seisoivat kysymyksensä päälle, ojensi hän itsensä ja sanoi heille: joka teistä on synnitön, se heittäkään ensin häntä kivellä."],[8,8,"Ja hän kumarsi taas ja kirjoitti maahan.","Ja hän kumarsi taas ja kirjoitti maahan."],[8,9,"Kuin he tämän kuulivat ja olivat omaltatunnoltansa voitetut, läksivät he ulos yksittäin, ruveten vanhimmista, viimeisiin asti; ja Jesus jäi yksinänsä, ja vaimo seisoi siinä.","Kuin he tämän kuulivat ja olivat omaltatunnoltansa voitetut, läksivät he ulos yksittäin, ruveten vanhimmista, viimeisiin asti; ja Jesus jäi yksinänsä, ja vaimo seisoi siinä."],[8,10,"Mutta kuin Jesus ojensi itsensä, ja ei nähnyt ketään paitsi vaimoa, sanoi hän hänelle: vaimo, kussa ovat sinun päällekantajas? Onko sinua kenkään tuominnut?","Mutta kuin Jesus ojensi itsensä, ja ei nähnyt ketään paitsi vaimoa, sanoi hän hänelle: vaimo, kussa ovat sinun päällekantajas? Onko sinua kenkään tuominnut?"],[8,11,"Hän sanoi: Herra, ei kenkään. Niin Jesus sanoi: en minä myös sinua tuomitse: mene, ja älä silleen syntiä tee.","Hän sanoi: Herra, ei kenkään. Niin Jesus sanoi: en minä myös sinua tuomitse: mene, ja älä silleen syntiä tee."],[8,12,"Niin Jesus puhui taas heille ja sanoi: minä olen maailman valkeus: joka minua seuraa, ei hän pimeydessä vaella, mutta saa elämän valkeuden.","Niin Jesus puhui taas heille ja sanoi: minä olen maailman valkeus: joka minua seuraa, ei hän pimeydessä vaella, mutta saa elämän valkeuden."],[8,13,"Pharisealaiset sanoivat hänelle: sinä todistat itsestäs; ei sinun todistukses ole tosi.","Pharisealaiset sanoivat hänelle: sinä todistat itsestäs; ei sinun todistukses ole tosi."],[8,14,"Jesus vastasi ja sanoi heille: vaikka minä itsestäni todistan, niin minun todistukseni on tosi; sillä minä tiedän, kusta minä tulin ja kuhunka minä menen; mutta ette tiedä, kusta minä tulin ja kuhunka minä menen.","Jesus vastasi ja sanoi heille: vaikka minä itsestäni todistan, niin minun todistukseni on tosi; sillä minä tiedän, kusta minä tulin ja kuhunka minä menen; mutta ette tiedä, kusta minä tulin ja kuhunka minä menen."],[8,15,"Te tuomitsette lihan jälkeen, en minä ketään tuomitse.","Te tuomitsette lihan jälkeen, en minä ketään tuomitse."],[8,16,"Ja vaikka minä tuomitsisin, niin minun tuomioni on tosi; sillä en minä ole yksinäni, vaan minä ja Isä, joka minun lähetti.","Ja vaikka minä tuomitsisin, niin minun tuomioni on tosi; sillä en minä ole yksinäni, vaan minä ja Isä, joka minun lähetti."],[8,17,"Ja teidän laissanne on myös kirjoitettu, että kahden ihmisen todistus on tosi.","Ja teidän laissanne on myös kirjoitettu, että kahden ihmisen todistus on tosi."],[8,18,"Minä olen se, joka itsestäni todistan, ja Isä, joka minun lähetti, todistaa myös minusta.","Minä olen se, joka itsestäni todistan, ja Isä, joka minun lähetti, todistaa myös minusta."],[8,19,"Niin he sanoivat hänelle: kussas Isäs on? Jesus vastasi: ette tunne minua ettekä minun Isääni: jos te tuntisitte minun, niin te tuntisitte myös minun Isäni.","Niin he sanoivat hänelle: kussas Isäs on? Jesus vastasi: ette tunne minua ettekä minun Isääni: jos te tuntisitte minun, niin te tuntisitte myös minun Isäni."],[8,20,"Nämät sanat puhui Jesus uhri-arkun tykönä, opettain tenplissä, ja ei häntä kenkään ottanut kiinni; sillä ei hänen aikansa ollut vielä tullut.","Nämät sanat puhui Jesus uhri-arkun tykönä, opettain tenplissä, ja ei häntä kenkään ottanut kiinni; sillä ei hänen aikansa ollut vielä tullut."],[8,21,"Niin Jesus sanoi taas heille: minä menen pois, ja te etsitte minua, ja teidän pitää kuoleman teidän synneissänne. Kuhunka minä menen, ette sinne taida tulla.","Niin Jesus sanoi taas heille: minä menen pois, ja te etsitte minua, ja teidän pitää kuoleman teidän synneissänne. Kuhunka minä menen, ette sinne taida tulla."],[8,22,"Niin sanoivat Juudalaiset; tappaneeko hän itsensä, sillä hän sanoo: kuhunka minä menen, ette sinne taida tulla.","Niin sanoivat Juudalaiset; tappaneeko hän itsensä, sillä hän sanoo: kuhunka minä menen, ette sinne taida tulla."],[8,23,"Ja hän sanoi heille: te olette alhaalta, ja minä olen ylhäältä: te olette maailmasta, en minä ole maailmasta.","Ja hän sanoi heille: te olette alhaalta, ja minä olen ylhäältä: te olette maailmasta, en minä ole maailmasta."],[8,24,"Sentähden sanoin minä teille: teidän pitää kuoleman synneissänne; sillä jos ette usko, että minä se olen, niin teidän pitää kuoleman synneissänne.","Sentähden sanoin minä teille: teidän pitää kuoleman synneissänne; sillä jos ette usko, että minä se olen, niin teidän pitää kuoleman synneissänne."],[8,25,"Niin he sanoivat hänelle: kuka sinä olet? Jesus sanoi heille: se kuin minä alusta puhuin teille.","Niin he sanoivat hänelle: kuka sinä olet? Jesus sanoi heille: se kuin minä alusta puhuin teille."],[8,26,"Minulla on paljon teistä puhumista ja tuomitsemista, vaan se on totinen, joka minun lähetti; ja mitä minä olen häneltä kuullut, niitä minä puhun maailmalle.","Minulla on paljon teistä puhumista ja tuomitsemista, vaan se on totinen, joka minun lähetti; ja mitä minä olen häneltä kuullut, niitä minä puhun maailmalle."],[8,27,"Mutta ei he ymmärtäneet, että hän puhui heille Isästä.","Mutta ei he ymmärtäneet, että hän puhui heille Isästä."],[8,28,"Sanoi siis Jesus heille: kuin te olette Ihmisen Pojan ylentäneet, niin te ymmärrätte, että minä se olen, ja etten minä tee itsestäni mitään, vaan niinkuin Isä on minun opettanut, niitä minä puhun.","Sanoi siis Jesus heille: kuin te olette Ihmisen Pojan ylentäneet, niin te ymmärrätte, että minä se olen, ja etten minä tee itsestäni mitään, vaan niinkuin Isä on minun opettanut, niitä minä puhun."],[8,29,"Ja se, joka minun lähetti, on minun kanssani. Ei Isä jättänyt minua yksinäni, sillä minä teen aina niitä, mitkä hänelle kelvolliset ovat.","Ja se, joka minun lähetti, on minun kanssani. Ei Isä jättänyt minua yksinäni, sillä minä teen aina niitä, mitkä hänelle kelvolliset ovat."],[8,30,"Kuin hän näitä puhui, niin moni uskoi hänen päällensä.","Kuin hän näitä puhui, niin moni uskoi hänen päällensä."],[8,31,"Niin Jesus sanoi niille Juudalaisille, jotka hänen uskoivat: jos te pysytte minun puheessani, niin te totisesti minun opetuslapseni olette.","Niin Jesus sanoi niille Juudalaisille, jotka hänen uskoivat: jos te pysytte minun puheessani, niin te totisesti minun opetuslapseni olette."],[8,32,"Ja teidän pitää totuuden ymmärtämän, ja totuuden pitää teidät vapahtaman.","Ja teidän pitää totuuden ymmärtämän, ja totuuden pitää teidät vapahtaman."],[8,33,"Niin he vastasivat häntä: me olemme Abrahamin siemen, emmekä ole koskaan kenenkään orjina olleet; kuinka siis sinä sanot: teidän pitää vapaiksi tuleman?","Niin he vastasivat häntä: me olemme Abrahamin siemen, emmekä ole koskaan kenenkään orjina olleet; kuinka siis sinä sanot: teidän pitää vapaiksi tuleman?"],[8,34,"Jesus vastasi heitä ja sanoi: totisesti, totisesti sanon minä teille: jokainen, joka tekee syntiä, hän on synnin orja.","Jesus vastasi heitä ja sanoi: totisesti, totisesti sanon minä teille: jokainen, joka tekee syntiä, hän on synnin orja."],[8,35,"Mutta ei orja pysy ijankaikkisesti huoneessa; vaan Poika pysyy ijankaikkisesti.","Mutta ei orja pysy ijankaikkisesti huoneessa; vaan Poika pysyy ijankaikkisesti."],[8,36,"Jos siis Poika teidät vapaiksi tekee, niin te totisesti olette vapaat.","Jos siis Poika teidät vapaiksi tekee, niin te totisesti olette vapaat."],[8,37,"Minä tiedän, että te olette Abrahamin siemen, vaan te etsitte kuolettaaksenne minua; sillä ei minun puheellani ole teissä siaa.","Minä tiedän, että te olette Abrahamin siemen, vaan te etsitte kuolettaaksenne minua; sillä ei minun puheellani ole teissä siaa."],[8,38,"Minä puhun, mitä minä olen isäni tykönä nähnyt, ja te teette, mitä te olette nähneet teidän isänne tykönä.","Minä puhun, mitä minä olen isäni tykönä nähnyt, ja te teette, mitä te olette nähneet teidän isänne tykönä."],[8,39,"He vastasivat ja sanoivat hänelle: Abraham on meidän isämme. Jesus sanoi heille: jos te olisitte Abrahamin lapset: niin te tekisitte Abrahamin töitä.","He vastasivat ja sanoivat hänelle: Abraham on meidän isämme. Jesus sanoi heille: jos te olisitte Abrahamin lapset: niin te tekisitte Abrahamin töitä."],[8,40,"Mutta nyt te etsitte minua tappaaksenne, sitä ihmistä, joka totuuden on teille puhunut, jonka hän on Jumalalta kuullut: sitä ei Abraham tehnyt.","Mutta nyt te etsitte minua tappaaksenne, sitä ihmistä, joka totuuden on teille puhunut, jonka hän on Jumalalta kuullut: sitä ei Abraham tehnyt."],[8,41,"Te teette teidän isänne tekoja. Niin he sanoivat hänelle: emme ole äpärinä syntyneet: meillä on yksi Isä, Jumala.","Te teette teidän isänne tekoja. Niin he sanoivat hänelle: emme ole äpärinä syntyneet: meillä on yksi Isä, Jumala."],[8,42,"Jesus sanoi heille: jos Jumala olis teidän Isänne, niin te tosin rakastaisitte minua; sillä minä läksin ja tulin Jumalasta, en minä itsestäni tullut, vaan hän lähetti minun.","Jesus sanoi heille: jos Jumala olis teidän Isänne, niin te tosin rakastaisitte minua; sillä minä läksin ja tulin Jumalasta, en minä itsestäni tullut, vaan hän lähetti minun."],[8,43,"Miksi ette ymmärrä tätä minun puhettani? Ette taida kuulla sitä minun sanaani.","Miksi ette ymmärrä tätä minun puhettani? Ette taida kuulla sitä minun sanaani."],[8,44,"Te olette isästä perkeleestä, ja teidän isänne himoja te tahdotte tehdä. Hän on ollut murhaaja alusta, ja ei pysynyt totuudessa; sillä ei totuus ole hänessä. Kuin hän puhuu valhetta, niin hän puhuu omastansa; sillä hän on valehtelia ja valheen isä.","Te olette isästä perkeleestä, ja teidän isänne himoja te tahdotte tehdä. Hän on ollut murhaaja alusta, ja ei pysynyt totuudessa; sillä ei totuus ole hänessä. Kuin hän puhuu valhetta, niin hän puhuu omastansa; sillä hän on valehtelia ja valheen isä."],[8,45,"Mutta että minä sanon totuuden, niin ette usko minua.","Mutta että minä sanon totuuden, niin ette usko minua."],[8,46,"Kuka teistä nuhtelee minua synnin tähden? jos minä sanon teille totuuden, miksi ette usko minua?","Kuka teistä nuhtelee minua synnin tähden? jos minä sanon teille totuuden, miksi ette usko minua?"],[8,47,"Joka on Jumalasta, se kuulee Jumalan sanat; sentähden ette kuule, ettette Jumalasta ole.","Joka on Jumalasta, se kuulee Jumalan sanat; sentähden ette kuule, ettette Jumalasta ole."],[8,48,"Niin vastasivat Juudalaiset ja sanoivat hänelle: emmekö me oikein sano, että sinä olet Samarialainen, ja sinulla on perkele?","Niin vastasivat Juudalaiset ja sanoivat hänelle: emmekö me oikein sano, että sinä olet Samarialainen, ja sinulla on perkele?"],[8,49,"Jesus vastasi: ei minulla ole perkele, vaan minä kunnioitan minun Isääni, ja te häpäisette minua.","Jesus vastasi: ei minulla ole perkele, vaan minä kunnioitan minun Isääni, ja te häpäisette minua."],[8,50,"En minä etsi omaa kunniaani, yksi on, joka sitä kysyy ja tuomitsee.","En minä etsi omaa kunniaani, yksi on, joka sitä kysyy ja tuomitsee."],[8,51,"Totisesti, totisesti sanon minä teille: joka kätkee minun sanani, ei hänen pidä näkemän kuolemaa ijankaikkisesti.","Totisesti, totisesti sanon minä teille: joka kätkee minun sanani, ei hänen pidä näkemän kuolemaa ijankaikkisesti."],[8,52,"Niin Juudalaiset sanoivat hänelle: nyt me ymmärsimme, että sinulla on perkele. Abraham on kuollut ja prophetat, ja sinä sanot: joka kätkee minun sanani, ei hänen pidä maistaman kuolemaa ijankaikkisesti.","Niin Juudalaiset sanoivat hänelle: nyt me ymmärsimme, että sinulla on perkele. Abraham on kuollut ja prophetat, ja sinä sanot: joka kätkee minun sanani, ei hänen pidä maistaman kuolemaa ijankaikkisesti."],[8,53,"Oletkos sinä suurempi kuin meidän isämme Abraham, joka kuollut on? ja prophetat ovat kuolleet: miksi sinä itses teet?","Oletkos sinä suurempi kuin meidän isämme Abraham, joka kuollut on? ja prophetat ovat kuolleet: miksi sinä itses teet?"],[8,54,"Jesus vastasi: jos minä itsiäni kunnioitan, niin ei minun kunniani ole mitään: minun Isäni on se, joka kunnioittaa minua, jonka te teidän Jumalaksenne sanotte.","Jesus vastasi: jos minä itsiäni kunnioitan, niin ei minun kunniani ole mitään: minun Isäni on se, joka kunnioittaa minua, jonka te teidän Jumalaksenne sanotte."],[8,55,"Ja ette tunne häntä, mutta minä tunnen hänen: ja jos minä sanoisin, etten minä häntä tuntisi, niin minä olisin valehtelia kuin tekin; mutta minä tunnen hänen ja kätken hänen sanansa.","Ja ette tunne häntä, mutta minä tunnen hänen: ja jos minä sanoisin, etten minä häntä tuntisi, niin minä olisin valehtelia kuin tekin; mutta minä tunnen hänen ja kätken hänen sanansa."],[8,56,"Abraham teidän isänne iloitsi, nähdäksensä minun päiväni; hän näki sen, ja ihastui.","Abraham teidän isänne iloitsi, nähdäksensä minun päiväni; hän näki sen, ja ihastui."],[8,57,"Niin Juudalaiset sanoivat hänelle: et sinä ole vielä viidenkymmenen ajastajan vanha ja olet nähnyt Abrahamin?","Niin Juudalaiset sanoivat hänelle: et sinä ole vielä viidenkymmenen ajastajan vanha ja olet nähnyt Abrahamin?"],[8,58,"Jesus sanoi heille: totisesti, totisesti sanon minä teille: ennenkuin Abraham olikaan, olen minä.","Jesus sanoi heille: totisesti, totisesti sanon minä teille: ennenkuin Abraham olikaan, olen minä."],[8,59,"Niin he poimivat kiviä, laskettaaksensa häntä. Mutta Jesus lymyi ja läksi ulos templistä, käyden heidän keskeltänsä; ja niin hän pääsi ulos.","Niin he poimivat kiviä, laskettaaksensa häntä. Mutta Jesus lymyi ja läksi ulos templistä, käyden heidän keskeltänsä; ja niin hän pääsi ulos."],[9,1,"Ja Jesus, käyden ohitse, näki ihmisen, joka oli sokiana syntynyt.","Ja Jesus, käyden ohitse, näki ihmisen, joka oli sokiana syntynyt."],[9,2,"Ja hänen opetuslapsensa kysyivät häneltä, sanoen: Mestari, kuka syntiä teki, tämäkö eli hänen vanhempansa, että hänen piti sokiana syntymän?","Ja hänen opetuslapsensa kysyivät häneltä, sanoen: Mestari, kuka syntiä teki, tämäkö eli hänen vanhempansa, että hänen piti sokiana syntymän?"],[9,3,"Jesus vastasi: ei tämä syntiä tehnyt eikä hänen vanhempansa; mutta että Jumalan työt hänessä ilmoitettaisiin.","Jesus vastasi: ei tämä syntiä tehnyt eikä hänen vanhempansa; mutta että Jumalan työt hänessä ilmoitettaisiin."],[9,4,"Minun tulee tehdä hänen töitänsä, joka minun lähetti, niin kauvan kuin päivä on. Yö tulee, koska ei kenkään taida työtä tehdä.","Minun tulee tehdä hänen töitänsä, joka minun lähetti, niin kauvan kuin päivä on. Yö tulee, koska ei kenkään taida työtä tehdä."],[9,5,"Niinkauvan kuin minä olen maailmassa, niin olen minä maailman valkeus.","Niinkauvan kuin minä olen maailmassa, niin olen minä maailman valkeus."],[9,6,"Kuin hän tämän sanonut oli, sylki hän maahan ja teki loan syljestä ja voiteli sokian silmät loalla,","Kuin hän tämän sanonut oli, sylki hän maahan ja teki loan syljestä ja voiteli sokian silmät loalla,"],[9,7,"Ja sanoi hänelle: mene ja pese itses lammikossa Siloam, se on niin paljo kuin: lähetetty. Niin hän meni ja pesi itsensä ja tuli näkemään.","Ja sanoi hänelle: mene ja pese itses lammikossa Siloam, se on niin paljo kuin: lähetetty. Niin hän meni ja pesi itsensä ja tuli näkemään."],[9,8,"Niin kylän miehet ja ne, jotka hänen ennen olivat nähneet sokiana, sanoivat: eikö tämä se ole, joka istui ja kerjäsi?","Niin kylän miehet ja ne, jotka hänen ennen olivat nähneet sokiana, sanoivat: eikö tämä se ole, joka istui ja kerjäsi?"],[9,9,"Muutamat vastasivat: hän se on. Mutta muut sanoivat: hän on sen muotoinen; vaan hän itse sanoi: minä se olen.","Muutamat vastasivat: hän se on. Mutta muut sanoivat: hän on sen muotoinen; vaan hän itse sanoi: minä se olen."],[9,10,"Niin he sanoivat hänelle: kuinka sinun silmäs aukenivat?","Niin he sanoivat hänelle: kuinka sinun silmäs aukenivat?"],[9,11,"Vastasi hän ja sanoi: se ihminen, joka Jesukseksi kutsutaan, teki loan, ja voiteli minun silmäni, ja sanoi minulle: mene ja pese Siloamin lammikossa. Ja kuin minä menin ja pesin, niin minä sain näköni.","Vastasi hän ja sanoi: se ihminen, joka Jesukseksi kutsutaan, teki loan, ja voiteli minun silmäni, ja sanoi minulle: mene ja pese Siloamin lammikossa. Ja kuin minä menin ja pesin, niin minä sain näköni."],[9,12,"Niin he sanoivat hänelle: kussas hän on? Hän sanoi: en minä tiedä.","Niin he sanoivat hänelle: kussas hän on? Hän sanoi: en minä tiedä."],[9,13,"Niin he veivät sen, joka ennen sokiana ollut oli, Pharisealaisten tykö.","Niin he veivät sen, joka ennen sokiana ollut oli, Pharisealaisten tykö."],[9,14,"Ja se oli sabbatin päivä, jona Jesus teki loan ja avasi hänen silmänsä.","Ja se oli sabbatin päivä, jona Jesus teki loan ja avasi hänen silmänsä."],[9,15,"Niin kysyivät taas häneltä Pharisealaiset, kuinka hän näkönsä saanut oli. Hän sanoi heille: hän pani loan minun silmäini päälle, ja minä pesin, ja näen.","Niin kysyivät taas häneltä Pharisealaiset, kuinka hän näkönsä saanut oli. Hän sanoi heille: hän pani loan minun silmäini päälle, ja minä pesin, ja näen."],[9,16,"Niin muutamat Pharisealaisista sanoivat: ei se ihminen ole Jumalasta, ettei hän pidä sabbatia. Muut sanoivat: kuinka taitaa joku syntinen ihminen senkaltaisia ihmeitä tehdä? Ja riita oli heillä keskenänsä.","Niin muutamat Pharisealaisista sanoivat: ei se ihminen ole Jumalasta, ettei hän pidä sabbatia. Muut sanoivat: kuinka taitaa joku syntinen ihminen senkaltaisia ihmeitä tehdä? Ja riita oli heillä keskenänsä."],[9,17,"He sanoivat taas sokiallle: mitä sinä hänestä sanot, joka sinun silmäs avasi? Hän sanoi: hän on propheta.","He sanoivat taas sokiallle: mitä sinä hänestä sanot, joka sinun silmäs avasi? Hän sanoi: hän on propheta."],[9,18,"Mutta ei Juudalaiset sitä uskoneet, että hän oli sokiana ollut ja näkemään tullut, siihenasti kuin he kutsuivat sen vanhemmat, joka näkönsä saanut oli.","Mutta ei Juudalaiset sitä uskoneet, että hän oli sokiana ollut ja näkemään tullut, siihenasti kuin he kutsuivat sen vanhemmat, joka näkönsä saanut oli."],[9,19,"Ja he kysyivät heiltä, sanoen: onko tämä teidän poikanne, jonka te sanotte sokiana syntyneen? kuinka siis hän nyt näkee?","Ja he kysyivät heiltä, sanoen: onko tämä teidän poikanne, jonka te sanotte sokiana syntyneen? kuinka siis hän nyt näkee?"],[9,20,"Hänen vanhempansa vastasivat heitä ja sanoivat: me tiedämme tämän meidän pojaksemme, ja että hän sokiana syntynyt on.","Hänen vanhempansa vastasivat heitä ja sanoivat: me tiedämme tämän meidän pojaksemme, ja että hän sokiana syntynyt on."],[9,21,"Mutta kuika hän nyt näkee, sitä emme tiedä, ja kuka hänen silmänsä avasi, emme tiedä; hänellä on kyllä ikää, kysykäät häneltä; puhukaan itsestänsä.","Mutta kuika hän nyt näkee, sitä emme tiedä, ja kuka hänen silmänsä avasi, emme tiedä; hänellä on kyllä ikää, kysykäät häneltä; puhukaan itsestänsä."],[9,22,"Niin sanoivat hänen vanhempansa, sillä he pelkäsivät Juudalaisia; sillä Juudalaiset olivat jo niin keskenänsä päättäneet, että jos joku hänen tunnustais Kristukseksi, sen piti synagogasta oleman suljettu ulos.","Niin sanoivat hänen vanhempansa, sillä he pelkäsivät Juudalaisia; sillä Juudalaiset olivat jo niin keskenänsä päättäneet, että jos joku hänen tunnustais Kristukseksi, sen piti synagogasta oleman suljettu ulos."],[9,23,"Sentähden sanoivat hänen vanhempansa: hänellä on kyllä ikää, kysykäät häneltä.","Sentähden sanoivat hänen vanhempansa: hänellä on kyllä ikää, kysykäät häneltä."],[9,24,"Niin he kutsuivat toisen kerran sen ihmisen, joka sokiana oli ollut, ja sanoivat hänelle: anna Jumalalle kunnia! me tiedämme sen ihmisen syntiseksi.","Niin he kutsuivat toisen kerran sen ihmisen, joka sokiana oli ollut, ja sanoivat hänelle: anna Jumalalle kunnia! me tiedämme sen ihmisen syntiseksi."],[9,25,"Hän vastasi ja sanoi: jos hän on syntinen, sitä en minä tiedä: vaan sen minä ainoasti tiedän, että minä, joka sokia olin, nyt näen.","Hän vastasi ja sanoi: jos hän on syntinen, sitä en minä tiedä: vaan sen minä ainoasti tiedän, että minä, joka sokia olin, nyt näen."],[9,26,"He sanoivat taas hänelle: mitä hän sinulle teki? kuinka hän sinun silmäs avasi?","He sanoivat taas hänelle: mitä hän sinulle teki? kuinka hän sinun silmäs avasi?"],[9,27,"Hän vastasi: jo minä sanoin teille, ettekö te kuulleet? Miksi te taas sitä tahdotte kuulla? Tahdotteko te myös hänen opetuslapsiksensa?","Hän vastasi: jo minä sanoin teille, ettekö te kuulleet? Miksi te taas sitä tahdotte kuulla? Tahdotteko te myös hänen opetuslapsiksensa?"],[9,28,"Niin he kiroilivat häntä ja sanoivat: sinä olet hänen opetuslapsensa; mutta me olemme Moseksen opetuslapset.","Niin he kiroilivat häntä ja sanoivat: sinä olet hänen opetuslapsensa; mutta me olemme Moseksen opetuslapset."],[9,29,"Me tiedämme Jumalan Mosesta puhutelleen: mutta kusta tämä on, emme tiedä.","Me tiedämme Jumalan Mosesta puhutelleen: mutta kusta tämä on, emme tiedä."],[9,30,"Niin ihminen vastasi ja sanoi heille: se on tosin ihmeellinen, ettette tiedä, kusta hän on, ja kuitenkin hän avasi minun silmäni.","Niin ihminen vastasi ja sanoi heille: se on tosin ihmeellinen, ettette tiedä, kusta hän on, ja kuitenkin hän avasi minun silmäni."],[9,31,"Mutta me tiedämme, ettei Jumala kuule syntisiä; vaan joka on Jumalan palvelia ja tekee hänen tahtonsa, sitä hän kuulee.","Mutta me tiedämme, ettei Jumala kuule syntisiä; vaan joka on Jumalan palvelia ja tekee hänen tahtonsa, sitä hän kuulee."],[9,32,"Ei ole maailman alusta kuultu, että joku on sen silmät avannut, joka sokiana syntynyt on.","Ei ole maailman alusta kuultu, että joku on sen silmät avannut, joka sokiana syntynyt on."],[9,33,"Ellei hän olisi Jumalasta, niin ei hän taitaisi mitään tehdä.","Ellei hän olisi Jumalasta, niin ei hän taitaisi mitään tehdä."],[9,34,"He vastasivat ja sanoivat hänelle: sinä olet päänänsä synnissä syntynyt, ja sinä opetat meitä? Ja he ajoivat hänen ulos.","He vastasivat ja sanoivat hänelle: sinä olet päänänsä synnissä syntynyt, ja sinä opetat meitä? Ja he ajoivat hänen ulos."],[9,35,"Ja Jesus sai sen kuulla, että he olivat hänen ajaneet ulos, ja kuin hän löysi hänen, sanoi hän hänelle: uskotkos sinä Jumalan Pojan päälle?","Ja Jesus sai sen kuulla, että he olivat hänen ajaneet ulos, ja kuin hän löysi hänen, sanoi hän hänelle: uskotkos sinä Jumalan Pojan päälle?"],[9,36,"Hän vastasi ja sanoi: Herra, kuka se on, että minä hänen päällensä uskoisin?","Hän vastasi ja sanoi: Herra, kuka se on, että minä hänen päällensä uskoisin?"],[9,37,"Niin Jesus sanoi hänelle: sinä olet hänen nähnyt, ja hän on se, joka puhuu sinun kanssas.","Niin Jesus sanoi hänelle: sinä olet hänen nähnyt, ja hän on se, joka puhuu sinun kanssas."],[9,38,"Niin hän sanoi: Herra, minä uskon. Ja hän kumarsi ja rukoili häntä.","Niin hän sanoi: Herra, minä uskon. Ja hän kumarsi ja rukoili häntä."],[9,39,"Ja Jesus sanoi: minä tulin tuomiolle tähän maailmaan, että ne, jotka ei näe, pitää näkemän, ja ne, jotka näkevät, pitää sokiaksi tuleman.","Ja Jesus sanoi: minä tulin tuomiolle tähän maailmaan, että ne, jotka ei näe, pitää näkemän, ja ne, jotka näkevät, pitää sokiaksi tuleman."],[9,40,"Ja muutamat Pharisealaisista, jotka hänen tykönänsä olivat, kuulivat nämät ja sanoivat hänelle: olemmeko mekin sokiat?","Ja muutamat Pharisealaisista, jotka hänen tykönänsä olivat, kuulivat nämät ja sanoivat hänelle: olemmeko mekin sokiat?"],[9,41,"Jesus sanoi heille: jos te sokiat olisitte, niin ei olisi teillä syntiä; mutta että te sanotte: me näemme, sentähden teidän syntinne pysyy.","Jesus sanoi heille: jos te sokiat olisitte, niin ei olisi teillä syntiä; mutta että te sanotte: me näemme, sentähden teidän syntinne pysyy."],[10,1,"Totisesti, totisesti sanon minä teille: joka ei ovesta mene sisälle lammashuoneesen, vaan astuu siihen muualta, se on varas ja ryöväri.","Totisesti, totisesti sanon minä teille: joka ei ovesta mene sisälle lammashuoneesen, vaan astuu siihen muualta, se on varas ja ryöväri."],[10,2,"Mutta joka oven kautta sisälle menee, se on lammasten paimen:","Mutta joka oven kautta sisälle menee, se on lammasten paimen:"],[10,3,"Sille ovenvartia avaa, ja lampaat kuulevat hänen äänensä. Ja omia lampaitansa kutsuu hän nimeltänsä, ja vie heidät ulos.","Sille ovenvartia avaa, ja lampaat kuulevat hänen äänensä. Ja omia lampaitansa kutsuu hän nimeltänsä, ja vie heidät ulos."],[10,4,"Ja kuin hän omat lampaansa päästää ulos, käy hän heidän edellänsä, ja lampaat seuraavat häntä, sillä he tuntevat hänen äänensä.","Ja kuin hän omat lampaansa päästää ulos, käy hän heidän edellänsä, ja lampaat seuraavat häntä, sillä he tuntevat hänen äänensä."],[10,5,"Mutta ei he muukalaista seuraa, vaan pakenevat häntä; sillä ei he tunne muukalaisten ääntä.","Mutta ei he muukalaista seuraa, vaan pakenevat häntä; sillä ei he tunne muukalaisten ääntä."],[10,6,"Tämän tapauksen sanoi Jesus heille; mutta ei he niitä ymmärtäneet, mitä hän heille sanoi.","Tämän tapauksen sanoi Jesus heille; mutta ei he niitä ymmärtäneet, mitä hän heille sanoi."],[10,7,"Niin Jesus sanoi taas heille: totisesti, totisesti sanon minä teille: minä olen lammasten ovi.","Niin Jesus sanoi taas heille: totisesti, totisesti sanon minä teille: minä olen lammasten ovi."],[10,8,"Kaikki, jotka minun edelläni ovat tulleet, ovat varkaat ja ryövärit: vaan ei lampaat kuulleet heitä.","Kaikki, jotka minun edelläni ovat tulleet, ovat varkaat ja ryövärit: vaan ei lampaat kuulleet heitä."],[10,9,"Minä olen ovi: jos joku minun kauttani menee sisälle, se tulee autuaaksi, ja menee sisälle ja ulos, ja löytää laitumen.","Minä olen ovi: jos joku minun kauttani menee sisälle, se tulee autuaaksi, ja menee sisälle ja ulos, ja löytää laitumen."],[10,10,"Ei varas tule muuta kuin varastamaan ja tappamaan ja kadottamaan: minä tulin, että heillä pitää elämä oleman ja yltäkyllä oleman.","Ei varas tule muuta kuin varastamaan ja tappamaan ja kadottamaan: minä tulin, että heillä pitää elämä oleman ja yltäkyllä oleman."],[10,11,"Minä olen hyvä paimen: hyvä paimen antaa henkensä lammasten edestä.","Minä olen hyvä paimen: hyvä paimen antaa henkensä lammasten edestä."],[10,12,"Mutta palkollinen, joka ei ole paimen, eikä lampaat ole hänen omansa: kuin hän näkee suden tulevan, niin hän jättää lampaat ja pakenee; ja susi raatelee ja haaskaa lampaat.","Mutta palkollinen, joka ei ole paimen, eikä lampaat ole hänen omansa: kuin hän näkee suden tulevan, niin hän jättää lampaat ja pakenee; ja susi raatelee ja haaskaa lampaat."],[10,13,"Mutta palkollinen pakenee, sillä hän on palkollinen, eikä tottele lampaista.","Mutta palkollinen pakenee, sillä hän on palkollinen, eikä tottele lampaista."],[10,14,"Minä olen hyvä paimen, joka tunnen omani, ja minä tunnetaan myös omiltani,","Minä olen hyvä paimen, joka tunnen omani, ja minä tunnetaan myös omiltani,"],[10,15,"Niinkuin Isä minun tuntee, ja minä tunnen Isän: ja panen henkeni lammasten edestä.","Niinkuin Isä minun tuntee, ja minä tunnen Isän: ja panen henkeni lammasten edestä."],[10,16,"Minulla on myös muita lampaita, jotka ei ole tästä lammashuoneesta: ne pitää minun myös tänne saattaman: ja he saavat kuulla minun ääneni; ja pitää oleman yksi lammashuone ja yksi paimen.","Minulla on myös muita lampaita, jotka ei ole tästä lammashuoneesta: ne pitää minun myös tänne saattaman: ja he saavat kuulla minun ääneni; ja pitää oleman yksi lammashuone ja yksi paimen."],[10,17,"Sentähden Isä minua rakastaa, sillä minä panen henkeni, että minä sen jälleen otan.","Sentähden Isä minua rakastaa, sillä minä panen henkeni, että minä sen jälleen otan."],[10,18,"Ei ota kenkään sitä minulta, vaan minä panen sen itsestäni. Minulla on valta sitä panna, ja minulla on valta sitä taas ottaa. Sen käskyn minä sain Isältäni.","Ei ota kenkään sitä minulta, vaan minä panen sen itsestäni. Minulla on valta sitä panna, ja minulla on valta sitä taas ottaa. Sen käskyn minä sain Isältäni."],[10,19,"Niin tuli taas riita Juudalaisten keskellä näiden puhetten tähden.","Niin tuli taas riita Juudalaisten keskellä näiden puhetten tähden."],[10,20,"Ja moni heistä sanoi: hänellä on perkele, ja hän on mieletöin: mitä te häntä kuultelette?","Ja moni heistä sanoi: hänellä on perkele, ja hän on mieletöin: mitä te häntä kuultelette?"],[10,21,"Mutta muut sanoivat: ei ne ole riivatun puheet: taitaako perkele sokian silmät avata?","Mutta muut sanoivat: ei ne ole riivatun puheet: taitaako perkele sokian silmät avata?"],[10,22,"Ja Jerusalemissa oli kirkkomessu, ja talvi oli,","Ja Jerusalemissa oli kirkkomessu, ja talvi oli,"],[10,23,"Ja Jesus käveli templissä Salomon esihuoneessa.","Ja Jesus käveli templissä Salomon esihuoneessa."],[10,24,"Niin Juudalaiset piirittivät hänen ja sanoivat hänelle: kuinka kauvan sinä meitä pidät ylös? Jos olet Kristus, niin sano meille selkiästi.","Niin Juudalaiset piirittivät hänen ja sanoivat hänelle: kuinka kauvan sinä meitä pidät ylös? Jos olet Kristus, niin sano meille selkiästi."],[10,25,"Jesus vastasi heitä: minä olen sen teille sanonut, ja ette usko: ne työt, jotka minä teen Isäni nimeen, todistavat minusta.","Jesus vastasi heitä: minä olen sen teille sanonut, ja ette usko: ne työt, jotka minä teen Isäni nimeen, todistavat minusta."],[10,26,"Mutta ette usko: sillä ette ole minun lampaistani, niinkuin minä teille sanoin.","Mutta ette usko: sillä ette ole minun lampaistani, niinkuin minä teille sanoin."],[10,27,"Minun lampaani kuulevat minun ääneni, ja minä tunnen heidät, ja he seuraavat minua:","Minun lampaani kuulevat minun ääneni, ja minä tunnen heidät, ja he seuraavat minua:"],[10,28,"Ja minä annan heille ijankaikkisen elämän, ja ei heidän pidä hukkuman ijankaikkisesti, eikä pidä yhdenkään repäisemän heitä minun kädestäni.","Ja minä annan heille ijankaikkisen elämän, ja ei heidän pidä hukkuman ijankaikkisesti, eikä pidä yhdenkään repäisemän heitä minun kädestäni."],[10,29,"Minun isäni, joka ne minulle antoi, on suurempi kaikkia: ja ei kenkään taida heitä reväistä minun Isäni kädestä.","Minun isäni, joka ne minulle antoi, on suurempi kaikkia: ja ei kenkään taida heitä reväistä minun Isäni kädestä."],[10,30,"Minä ja Isä olemme yhtä.","Minä ja Isä olemme yhtä."],[10,31,"Niin Juudalaiset poimivat taas kiviä häntä kivittääksensä.","Niin Juudalaiset poimivat taas kiviä häntä kivittääksensä."],[10,32,"Jesus vastasi heitä: minä osoitin teille Isältäni monta hyvää työtä: minkä työn tähden niistä te siis minun kivitätte?","Jesus vastasi heitä: minä osoitin teille Isältäni monta hyvää työtä: minkä työn tähden niistä te siis minun kivitätte?"],[10,33,"Juudalaiset vastasivat häntä, sanoen: emme sinua hyvän työn tähden kivitä, vaan pilkan tähden, ja että sinä, joka ihminen olet, teet itses Jumalaksi.","Juudalaiset vastasivat häntä, sanoen: emme sinua hyvän työn tähden kivitä, vaan pilkan tähden, ja että sinä, joka ihminen olet, teet itses Jumalaksi."],[10,34,"Jesus vastasi heitä: eikö teidän laissanne ole kirjoitettu: minä sanon, te olette jumalat?","Jesus vastasi heitä: eikö teidän laissanne ole kirjoitettu: minä sanon, te olette jumalat?"],[10,35,"Jos hän ne kutsui jumaliksi, joille Jumalan sana tapahtui, ja ei kirjoitus taideta rikottaa:","Jos hän ne kutsui jumaliksi, joille Jumalan sana tapahtui, ja ei kirjoitus taideta rikottaa:"],[10,36,"Ja te sanotte hänelle, jonka Isä on pyhittänyt ja lähettänyt maailmaan: sinä pilkkaat Jumalaa, että minä sanoin: minä olen Jumalan Poika.","Ja te sanotte hänelle, jonka Isä on pyhittänyt ja lähettänyt maailmaan: sinä pilkkaat Jumalaa, että minä sanoin: minä olen Jumalan Poika."],[10,37,"Ellen minä tee minun Isäni töitä, niin älkäät minua uskoko.","Ellen minä tee minun Isäni töitä, niin älkäät minua uskoko."],[10,38,"Mutta jos minä niitä teen, ja jos ette minua usko, niin uskokaat ne työt, että te tuntisitte ja uskoisitte Isän olevan minussa ja minun hänessä.","Mutta jos minä niitä teen, ja jos ette minua usko, niin uskokaat ne työt, että te tuntisitte ja uskoisitte Isän olevan minussa ja minun hänessä."],[10,39,"Niin he etsivät taas häntä kiinni ottaaksensa, mutta hän läksi heidän käsistänsä,","Niin he etsivät taas häntä kiinni ottaaksensa, mutta hän läksi heidän käsistänsä,"],[10,40,"Ja meni jälleen toiselle puolelle Jordania, siihen paikkaan, jossa Johannes ensin kasti, ja viipyi siinä.","Ja meni jälleen toiselle puolelle Jordania, siihen paikkaan, jossa Johannes ensin kasti, ja viipyi siinä."],[10,41,"Ja monta tuli hänen tykönsä, ja sanoivat: ei Johannes yhtäkään ihmettä tehnyt; mutta kaikki mitä Johannes tästä sanoi, ne ovat todet.","Ja monta tuli hänen tykönsä, ja sanoivat: ei Johannes yhtäkään ihmettä tehnyt; mutta kaikki mitä Johannes tästä sanoi, ne ovat todet."],[10,42,"Ja monta uskoi sillä hänen päällensä.","Ja monta uskoi sillä hänen päällensä."],[11,1,"Niin mies sairasti, nimeltä Latsarus, Betaniasta, Marian ja hänen sisarensa Martan kylästä.","Niin mies sairasti, nimeltä Latsarus, Betaniasta, Marian ja hänen sisarensa Martan kylästä."],[11,2,"Mutta Maria oli se, joka voiteli Herran voiteella ja hänen jalkansa hiuksillansa kuivaksi, jonka veli Latsarus sairasti.","Mutta Maria oli se, joka voiteli Herran voiteella ja hänen jalkansa hiuksillansa kuivaksi, jonka veli Latsarus sairasti."],[11,3,"Niin hänen sisarensa lähettivät hänen tykönsä, ja sanoivat: Herra, katso, se sairastaa, jotas rakastat.","Niin hänen sisarensa lähettivät hänen tykönsä, ja sanoivat: Herra, katso, se sairastaa, jotas rakastat."],[11,4,"Kuin Jesus sen kuuli, sanoi hän: ei tämä tauti ole kuolemaksi, vaan Jumalan kunniaksi, että Jumalan Poika sen kautta kunnioitettaisiin.","Kuin Jesus sen kuuli, sanoi hän: ei tämä tauti ole kuolemaksi, vaan Jumalan kunniaksi, että Jumalan Poika sen kautta kunnioitettaisiin."],[11,5,"Mutta Jesus rakasti Marttaa, ha hänen sisartansa, ja Latsarusta.","Mutta Jesus rakasti Marttaa, ha hänen sisartansa, ja Latsarusta."],[11,6,"Kuin hän siis kuuli hänen sairastavan, niin hän viipyi siinä paikassa kaksi päivää.","Kuin hän siis kuuli hänen sairastavan, niin hän viipyi siinä paikassa kaksi päivää."],[11,7,"Sitte sanoi hän opetuslapsillensa: menkäämme jälleen Juudeaan.","Sitte sanoi hän opetuslapsillensa: menkäämme jälleen Juudeaan."],[11,8,"Sanoivat hänelle opetuslapset: Rabbi, äsken etsivät Juudalaiset sinua kivittääksensä, ja sinä menet taas sinne.","Sanoivat hänelle opetuslapset: Rabbi, äsken etsivät Juudalaiset sinua kivittääksensä, ja sinä menet taas sinne."],[11,9,"Vastasi Jesus: eikö kaksitoistakymmentä ole päivän hetkeä? Jos joku päivällä vaeltaa, ei hän loukkaa itsiänsä; sillä hän näkee tämän maailman valkeuden.","Vastasi Jesus: eikö kaksitoistakymmentä ole päivän hetkeä? Jos joku päivällä vaeltaa, ei hän loukkaa itsiänsä; sillä hän näkee tämän maailman valkeuden."],[11,10,"Mutta jos joku yöllä vaeltaa, hän loukkaa itsensä; sillä ei valkeus ole hänessä.","Mutta jos joku yöllä vaeltaa, hän loukkaa itsensä; sillä ei valkeus ole hänessä."],[11,11,"Näitä hän puhui, ja sanoi sitte heille: ystävämme Latsarus makaa, mutta minä menen häntä unesta herättämään.","Näitä hän puhui, ja sanoi sitte heille: ystävämme Latsarus makaa, mutta minä menen häntä unesta herättämään."],[11,12,"Niin sanoivat hänen opetuslapsensa: Herra, jos hän makaa, kyllä hän paranee.","Niin sanoivat hänen opetuslapsensa: Herra, jos hän makaa, kyllä hän paranee."],[11,13,"Mutta Jesus sanoi hänen kuolemastansa; vaan he luulivat hänen sanovan unen makaamisesta.","Mutta Jesus sanoi hänen kuolemastansa; vaan he luulivat hänen sanovan unen makaamisesta."],[11,14,"Niin Jesus sanoi heille selkiästi: Latsarus on kuollut.","Niin Jesus sanoi heille selkiästi: Latsarus on kuollut."],[11,15,"Ja minä iloitsen teidän tähtenne, etten minä siellä ollut, että te uskoisitte. Mutta menkäämme hänen tykönsä.","Ja minä iloitsen teidän tähtenne, etten minä siellä ollut, että te uskoisitte. Mutta menkäämme hänen tykönsä."],[11,16,"Niin sanoi Toomas, joka kutsutaan kaksoiseksi, muille opetuslapsille: käykäämme myös me, että me kuolisimme hänen kanssansa.","Niin sanoi Toomas, joka kutsutaan kaksoiseksi, muille opetuslapsille: käykäämme myös me, että me kuolisimme hänen kanssansa."],[11,17,"niin Jesus tuli ja löysi hänen jo neljä päivää maanneen haudassa.","niin Jesus tuli ja löysi hänen jo neljä päivää maanneen haudassa."],[11,18,"Mutta Betania oli läsnä Jerusalemia, lähes viisitoistakymmentä vakomittaa.","Mutta Betania oli läsnä Jerusalemia, lähes viisitoistakymmentä vakomittaa."],[11,19,"Ja monta Juudalaisista oli tullut Martan ja Marian tykö, lohduttamaan heitä heidän veljensä tähden.","Ja monta Juudalaisista oli tullut Martan ja Marian tykö, lohduttamaan heitä heidän veljensä tähden."],[11,20,"Kuin Martta kuuli Jesuksen tulevan, juoksi hän häntä vastaa; mutta Maria istui kotona.","Kuin Martta kuuli Jesuksen tulevan, juoksi hän häntä vastaa; mutta Maria istui kotona."],[11,21,"Niin Martta sanoi Jesukselle: Herra, jos sinä olisit täällä ollut, niin ei minun veljeni olisi kuollut.","Niin Martta sanoi Jesukselle: Herra, jos sinä olisit täällä ollut, niin ei minun veljeni olisi kuollut."],[11,22,"Mutta minä tiedän vielä, että kaikki, mitä sinä anot Jumalalta, ne Jumala sinulle antaa.","Mutta minä tiedän vielä, että kaikki, mitä sinä anot Jumalalta, ne Jumala sinulle antaa."],[11,23,"Jesus sanoi hänelle: sinun veljes on nouseva ylös.","Jesus sanoi hänelle: sinun veljes on nouseva ylös."],[11,24,"Martta sanoi hänelle: minä tiedän hänen nousevan ylösnousemisessa viimeisenä päivänä.","Martta sanoi hänelle: minä tiedän hänen nousevan ylösnousemisessa viimeisenä päivänä."],[11,25,"Sanoi Jesus hänelle: minä olen ylösnousemus ja elämä: joka uskoo minun päälleni, hän elää, ehkä hän olis kuollut.","Sanoi Jesus hänelle: minä olen ylösnousemus ja elämä: joka uskoo minun päälleni, hän elää, ehkä hän olis kuollut."],[11,26,"Ja jokainen, joka elää ja uskoo minun päälleni, ei hänen pidä kuoleman ijankaikkisesti: uskotkos sen?","Ja jokainen, joka elää ja uskoo minun päälleni, ei hänen pidä kuoleman ijankaikkisesti: uskotkos sen?"],[11,27,"Hän sanoi hänelle: jaa Herra, minä uskon sinun Kristukseksi, Jumalan Pojaksi, joka tuleva oli maailmaan.","Hän sanoi hänelle: jaa Herra, minä uskon sinun Kristukseksi, Jumalan Pojaksi, joka tuleva oli maailmaan."],[11,28,"Ja kuin hän näitä sanonut oli, meni hän pois ja kutsui sisarensa Marian salaa, sanoen: Mestari on tullut ja kutsuu sinua.","Ja kuin hän näitä sanonut oli, meni hän pois ja kutsui sisarensa Marian salaa, sanoen: Mestari on tullut ja kutsuu sinua."],[11,29,"Kuin hän sen kuuli, nousi hän kohta ja tuli hänen tykönsä.","Kuin hän sen kuuli, nousi hän kohta ja tuli hänen tykönsä."],[11,30,"(Sillä ei Jesus ollut vielä kylään tullut, vaan oli siinä paikassa, jossa Martta oli hänen kohdannut.)","(Sillä ei Jesus ollut vielä kylään tullut, vaan oli siinä paikassa, jossa Martta oli hänen kohdannut.)"],[11,31,"Kuin siis Juudalaiset, jotka hänen kanssansa huoneessa olivat lohduttamassa häntä, näkivät Marian nousevan ja menevän ulos, seurasivat he häntä, sanoen: hän menee haudalle itkemään.","Kuin siis Juudalaiset, jotka hänen kanssansa huoneessa olivat lohduttamassa häntä, näkivät Marian nousevan ja menevän ulos, seurasivat he häntä, sanoen: hän menee haudalle itkemään."],[11,32,"Kuin Maria sinne tuli, kussa Jesus oli, ja näki hänen, lankesi hän hänen jalkainsa juureen ja sanoi hänelle: Herra, jos olisit täällä ollut, ei olisi minun veljeni kuollut.","Kuin Maria sinne tuli, kussa Jesus oli, ja näki hänen, lankesi hän hänen jalkainsa juureen ja sanoi hänelle: Herra, jos olisit täällä ollut, ei olisi minun veljeni kuollut."],[11,33,"Kuin Jesus näki hänen itkevän ja Juudalaiset, jotka hänen kanssansa tulleet olivat, itkevän, kauhistui hän hengessä ja tuli sangen murheelliseksi,","Kuin Jesus näki hänen itkevän ja Juudalaiset, jotka hänen kanssansa tulleet olivat, itkevän, kauhistui hän hengessä ja tuli sangen murheelliseksi,"],[11,34,"Ja sanoi: kuhunka te hänen panitte? He sanoivat hänelle: Herra, tule ja katso.","Ja sanoi: kuhunka te hänen panitte? He sanoivat hänelle: Herra, tule ja katso."],[11,35,"Ja Jesus itki.","Ja Jesus itki."],[11,36,"Niin sanoivat Juudalaiset: katso, kuinka hän rakasti häntä.","Niin sanoivat Juudalaiset: katso, kuinka hän rakasti häntä."],[11,37,"Mutta muutamat heistä sanoivat: eikö tämä, joka sokian silmät avasi, tainnut tehdä, ettei tämäkään kuollut olisi?","Mutta muutamat heistä sanoivat: eikö tämä, joka sokian silmät avasi, tainnut tehdä, ettei tämäkään kuollut olisi?"],[11,38,"Niin Jesus kauhistui taas itsessänsä, ja tuli haudan tykö. Mutta siinä oli kuoppa, ja kivi sen päälle pantu.","Niin Jesus kauhistui taas itsessänsä, ja tuli haudan tykö. Mutta siinä oli kuoppa, ja kivi sen päälle pantu."],[11,39,"Jesus sanoi: ottakaat kivi pois. Sanoi hänelle Martta, sen sisar, joka kuollut oli: Herra, jo hän haisee, sillä hän on neljä päivää kuolleena ollut.","Jesus sanoi: ottakaat kivi pois. Sanoi hänelle Martta, sen sisar, joka kuollut oli: Herra, jo hän haisee, sillä hän on neljä päivää kuolleena ollut."],[11,40,"Jesus sanoi hänelle: enkö minä sinulle sanonut: jos sinä uskoisit, niin sinä näkisit Jumalan kunnian.","Jesus sanoi hänelle: enkö minä sinulle sanonut: jos sinä uskoisit, niin sinä näkisit Jumalan kunnian."],[11,41,"Ja he ottivat kiven pois sialtansa, johon kuollut pantu oli. Niin Jesus nosti silmänsä ylös ja sanoi: Isä, minä kiitän sinua, ettäs minua kuulit.","Ja he ottivat kiven pois sialtansa, johon kuollut pantu oli. Niin Jesus nosti silmänsä ylös ja sanoi: Isä, minä kiitän sinua, ettäs minua kuulit."],[11,42,"Mutta minä tiedän myös, ettäs aina minua kuulet; vaan kansan tähden, joka tässä ympäri seisoo, sanon minä, että he uskoisivat sinun minun lähettäneeksi.","Mutta minä tiedän myös, ettäs aina minua kuulet; vaan kansan tähden, joka tässä ympäri seisoo, sanon minä, että he uskoisivat sinun minun lähettäneeksi."],[11,43,"Ja kuin hän nämät sanonut oli, huusi hän suurella äänellä: Latsarus, tule ulos.","Ja kuin hän nämät sanonut oli, huusi hän suurella äänellä: Latsarus, tule ulos."],[11,44,"Ja se kuollut tuli ulos sidottuna käsistä ja jaloista kääriliinalla, ja hänen kasvonsa olivat sidotut ympäri hikiliinalla. Jesus sanoi heille: päästäkäät häntä ja antakaat hänen mennä.","Ja se kuollut tuli ulos sidottuna käsistä ja jaloista kääriliinalla, ja hänen kasvonsa olivat sidotut ympäri hikiliinalla. Jesus sanoi heille: päästäkäät häntä ja antakaat hänen mennä."],[11,45,"Niin monta Juudalaista, jotka olivat Marian tykö tulleet, ja näkivät mitä Jesus teki, uskoivat hänen päällensä.","Niin monta Juudalaista, jotka olivat Marian tykö tulleet, ja näkivät mitä Jesus teki, uskoivat hänen päällensä."],[11,46,"Mutta muutamat heistä menivät Pharisealaisten tykö ja ilmoittivat heille, mitä Jesus oli tehnyt.","Mutta muutamat heistä menivät Pharisealaisten tykö ja ilmoittivat heille, mitä Jesus oli tehnyt."],[11,47,"Niin ylimmäiset papit ja Pharisealaiset kokosivat neuvon, ja sanoivat: mitä me teemme? sillä tämä ihminen tekee monta ihmettä.","Niin ylimmäiset papit ja Pharisealaiset kokosivat neuvon, ja sanoivat: mitä me teemme? sillä tämä ihminen tekee monta ihmettä."],[11,48,"Jos me sallimme hänen niin olla, niin kaikki uskovat hänen päällensä, ja Roomalaiset tulevat ja ottavat pois sekä meidän maamme että kansamme.","Jos me sallimme hänen niin olla, niin kaikki uskovat hänen päällensä, ja Roomalaiset tulevat ja ottavat pois sekä meidän maamme että kansamme."],[11,49,"Mutta yksi heistä, Kaiphas nimeltä, joka oli sinä vuonna ylimmäinne pappi, sanoi heille: ette mitään tiedä:","Mutta yksi heistä, Kaiphas nimeltä, joka oli sinä vuonna ylimmäinne pappi, sanoi heille: ette mitään tiedä:"],[11,50,"Ette myös ajattele, että se on meille tarpeellinen, että yksi ihminen kuolee kansan tähden, ettei kaikki kansa hukkuisi.","Ette myös ajattele, että se on meille tarpeellinen, että yksi ihminen kuolee kansan tähden, ettei kaikki kansa hukkuisi."],[11,51,"Mutta ei hän sitä itsestänsä sanonut; vaan että hän oli sinä vuonna ylimmäinen pappi, niin hän ennusti, että Jesuksen piti kuoleman kansan tähden,","Mutta ei hän sitä itsestänsä sanonut; vaan että hän oli sinä vuonna ylimmäinen pappi, niin hän ennusti, että Jesuksen piti kuoleman kansan tähden,"],[11,52,"Ja ei ainoastaan kansan tähden, mutta että hänen piti ne Jumalan lapset, jotka hajoitetut olivat, yhteen kokooman.","Ja ei ainoastaan kansan tähden, mutta että hänen piti ne Jumalan lapset, jotka hajoitetut olivat, yhteen kokooman."],[11,53,"Mutta siitä päivästä pitivät he yhteen neuvoa, kuolettaaksensa häntä.","Mutta siitä päivästä pitivät he yhteen neuvoa, kuolettaaksensa häntä."],[11,54,"Ei siis Jesus vaeltanut enää Juudalaisten seassa julkisesti, vaan meni sieltä yhteen maan paikkaan lähes korpea, siihen kaupunkiin, joka kutsutaan Epharaim, ja oleskeli siellä opetuslastensa kanssa.","Ei siis Jesus vaeltanut enää Juudalaisten seassa julkisesti, vaan meni sieltä yhteen maan paikkaan lähes korpea, siihen kaupunkiin, joka kutsutaan Epharaim, ja oleskeli siellä opetuslastensa kanssa."],[11,55,"Mutta Juudalaisten pääsiäinen lähestyi, ja monta siitä maakunnasta meni pääsiäisen edellä Jerusalemiin puhdistamaan itsiänsä.","Mutta Juudalaisten pääsiäinen lähestyi, ja monta siitä maakunnasta meni pääsiäisen edellä Jerusalemiin puhdistamaan itsiänsä."],[11,56,"Niin he etsivät Jesusta ja puhuivat keskenänsä, seisoen templissä: mitä te luulette, ettei hän ole juhlalle tullut?","Niin he etsivät Jesusta ja puhuivat keskenänsä, seisoen templissä: mitä te luulette, ettei hän ole juhlalle tullut?"],[11,57,"Ja ylimmäiset papit ja Pharisealaiset olivat käskyn antaneet, että jos joku tietäis, kussa hän olis, niin hänen piti sen ilmoittaman, että he ottaisivat hänen kiinni.","Ja ylimmäiset papit ja Pharisealaiset olivat käskyn antaneet, että jos joku tietäis, kussa hän olis, niin hänen piti sen ilmoittaman, että he ottaisivat hänen kiinni."],[12,1,"Kuusi päivää enne pääsiäistä tuli Jesus Betaniaan, jossa Latsarus oli, joka kuollut oli, jonka hän kuolleista herätti.","Kuusi päivää enne pääsiäistä tuli Jesus Betaniaan, jossa Latsarus oli, joka kuollut oli, jonka hän kuolleista herätti."],[12,2,"Niin he valmistivat hänelle siellä ehtoollisen, ja Martta palveli; mutta Latsarus oli yksi niistä, jotka hänen kanssansa atrioitsivat.","Niin he valmistivat hänelle siellä ehtoollisen, ja Martta palveli; mutta Latsarus oli yksi niistä, jotka hänen kanssansa atrioitsivat."],[12,3,"Niin Maria otti naulan turmelematointa ja kallista nardusvoidetta, ja voiteli Jesuksen jalat, ja kuivasi hänen jalkansa hiuksillansa. Ja huone täytettiin voiteen hajusta.","Niin Maria otti naulan turmelematointa ja kallista nardusvoidetta, ja voiteli Jesuksen jalat, ja kuivasi hänen jalkansa hiuksillansa. Ja huone täytettiin voiteen hajusta."],[12,4,"Niin sanoi yksi hänen opetuslapsistansa, Juudas Simonin poika Iskariot, joka hänen sitte petti:","Niin sanoi yksi hänen opetuslapsistansa, Juudas Simonin poika Iskariot, joka hänen sitte petti:"],[12,5,"Miksi et tätä voidetta myyty kolmeensataan penninkiin, ja annettu vaivaisille?","Miksi et tätä voidetta myyty kolmeensataan penninkiin, ja annettu vaivaisille?"],[12,6,"Mutta hän sanoi sen, ei että hän murhetta piti vaivaisista, vaan että hän oli varas, ja hänellä oli kukkaro, jossa hän sen kantoi, mikä siihen pantu oli.","Mutta hän sanoi sen, ei että hän murhetta piti vaivaisista, vaan että hän oli varas, ja hänellä oli kukkaro, jossa hän sen kantoi, mikä siihen pantu oli."],[12,7,"Niin Jesus sanoi: anna hänen olla, hän on sen kätkenyt minun hautaamiseni päiväksi.","Niin Jesus sanoi: anna hänen olla, hän on sen kätkenyt minun hautaamiseni päiväksi."],[12,8,"Sillä teidän tykönänne ovat aina vaivaiset, mutta en minä aina teillä ole.","Sillä teidän tykönänne ovat aina vaivaiset, mutta en minä aina teillä ole."],[12,9,"Niin paljo kansaa Juudalaisista ymmärsi hänen siellä olevan, ja tulivat sinne, ei ainoastaan Jesuksen tähden, vaan että he olisivat myös Latsaruksen nähneet, jonka hän oli kuolleista herättänyt.","Niin paljo kansaa Juudalaisista ymmärsi hänen siellä olevan, ja tulivat sinne, ei ainoastaan Jesuksen tähden, vaan että he olisivat myös Latsaruksen nähneet, jonka hän oli kuolleista herättänyt."],[12,10,"Mutta ylimmäiset papit pitivät neuvoa myös Latsarusta tappaaksensa;","Mutta ylimmäiset papit pitivät neuvoa myös Latsarusta tappaaksensa;"],[12,11,"Sillä monta Juudalaisista meni sinne hänen tähtensä, ja uskoi Jesuksen päälle.","Sillä monta Juudalaisista meni sinne hänen tähtensä, ja uskoi Jesuksen päälle."],[12,12,"Toisena päivänä, kuin paljon kansaa, joka juhlalle tullut oli, kuuli Jesuksen tulleen Jerusalemiin,","Toisena päivänä, kuin paljon kansaa, joka juhlalle tullut oli, kuuli Jesuksen tulleen Jerusalemiin,"],[12,13,"Ottivat he palmu-oksia, menivät häntä vastaan ja huusivat: Hosianna! siunattu on se, joka tulee Herran nimeen, Israelin kuningas!","Ottivat he palmu-oksia, menivät häntä vastaan ja huusivat: Hosianna! siunattu on se, joka tulee Herran nimeen, Israelin kuningas!"],[12,14,"Mutta Jesus sai yhden aasin ja istui sen päälle, niinkuin kirjoitettu on:","Mutta Jesus sai yhden aasin ja istui sen päälle, niinkuin kirjoitettu on:"],[12,15,"Älä pelkää, Sionin tytär! katso, sinun Kuninkaas tulee ja istuu aasin varsan päällä.","Älä pelkää, Sionin tytär! katso, sinun Kuninkaas tulee ja istuu aasin varsan päällä."],[12,16,"Mutta ei hänen opetuslapsensa näitä ensisti ymmärtäneet; vaan sittekuin Jesus oli kirkastettu, silloin he muistivat, että nämät ovat hänestä kirjoitetut, ja että he näitä hänelle tehneet olivat.","Mutta ei hänen opetuslapsensa näitä ensisti ymmärtäneet; vaan sittekuin Jesus oli kirkastettu, silloin he muistivat, että nämät ovat hänestä kirjoitetut, ja että he näitä hänelle tehneet olivat."],[12,17,"Mutta se kansa todisti, joka hänen kanssansa oli, että hän Latsaruksen haudasta kutsui ja kuolleista herätti.","Mutta se kansa todisti, joka hänen kanssansa oli, että hän Latsaruksen haudasta kutsui ja kuolleista herätti."],[12,18,"Sentähden myös kansa meni häntä vastaan, että he kuulivat hänen sen ihmeen tehneeksi.","Sentähden myös kansa meni häntä vastaan, että he kuulivat hänen sen ihmeen tehneeksi."],[12,19,"Niin Pharisealaiset sanoivat keskenänsä: te näette, ettette mitään aikoihin saa; katso, koko maailma juoksee hänen perässänsä.","Niin Pharisealaiset sanoivat keskenänsä: te näette, ettette mitään aikoihin saa; katso, koko maailma juoksee hänen perässänsä."],[12,20,"Mutta muutamat Grekiläiset olivat niistä, jotka menivät ylös juhlana rukoilemaan.","Mutta muutamat Grekiläiset olivat niistä, jotka menivät ylös juhlana rukoilemaan."],[12,21,"Niin he menivät Philippuksen tykö, joka oli Galilean Betsaidasta, ja rukoilivat häntä, sanoen: herra, me tahdomme nähdä Jesusta.","Niin he menivät Philippuksen tykö, joka oli Galilean Betsaidasta, ja rukoilivat häntä, sanoen: herra, me tahdomme nähdä Jesusta."],[12,22,"Philippus meni ja sanoi sen Andreakselle, ja Andreas taas ja Philippus sanoivat sen Jesukselle.","Philippus meni ja sanoi sen Andreakselle, ja Andreas taas ja Philippus sanoivat sen Jesukselle."],[12,23,"Mutta Jesus vastasi heitä ja sanoi: aika on tullut, että Ihmisen Poika pitää kirkastettaman.","Mutta Jesus vastasi heitä ja sanoi: aika on tullut, että Ihmisen Poika pitää kirkastettaman."],[12,24,"Totisesti, totisesti sanon minä teille: ellei maahan pudonnut nisun jyvä kuole, niin se jää yksinänsä; mutta jos se kuolee, niin se tuo paljon hedelmää.","Totisesti, totisesti sanon minä teille: ellei maahan pudonnut nisun jyvä kuole, niin se jää yksinänsä; mutta jos se kuolee, niin se tuo paljon hedelmää."],[12,25,"Joka rakastaa henkeänsä, hän kadottaa sen; mutta joka tässä maailmassa vihaa henkeänsä, hän tuottaa sen ijankaikkiseen elämään.","Joka rakastaa henkeänsä, hän kadottaa sen; mutta joka tässä maailmassa vihaa henkeänsä, hän tuottaa sen ijankaikkiseen elämään."],[12,26,"Jos joku minua palvelee, hän seuratkaan minua: ja kussa minä olen, siellä pitää myös minun palveliani oleman: ja jos joku minua palvelee, häntä on Isä kunnioittava.","Jos joku minua palvelee, hän seuratkaan minua: ja kussa minä olen, siellä pitää myös minun palveliani oleman: ja jos joku minua palvelee, häntä on Isä kunnioittava."],[12,27,"Nyt on minun sieluni suuresti murheissansa, ja mitä minun pitää sanoman? Isä, vapahda minun tästä hetkestä: kuitenkin olen minä sentähden tähän hetkeen tullut.","Nyt on minun sieluni suuresti murheissansa, ja mitä minun pitää sanoman? Isä, vapahda minun tästä hetkestä: kuitenkin olen minä sentähden tähän hetkeen tullut."],[12,28,"Isä, kirkasta sinun nimes. Niin ääni tuli taivaasta ja sanoi: minä olen sen kirkastanut, ja tahdon vielä nyt kirkastaa.","Isä, kirkasta sinun nimes. Niin ääni tuli taivaasta ja sanoi: minä olen sen kirkastanut, ja tahdon vielä nyt kirkastaa."],[12,29,"Niin kansa, joka läsnä seisoi ja sen kuuli, sanoi pitkäisen jylisseen. Muut sanoivat: enkeli puhutteli häntä.","Niin kansa, joka läsnä seisoi ja sen kuuli, sanoi pitkäisen jylisseen. Muut sanoivat: enkeli puhutteli häntä."],[12,30,"Jesus vastasi ja sanoi: ei tämä ääni tullut minun, vaan teidän tähtenne.","Jesus vastasi ja sanoi: ei tämä ääni tullut minun, vaan teidän tähtenne."],[12,31,"Nyt tämä maailma tuomitaan: nyt tämän maailman päämies pitää heittämän ulos.","Nyt tämä maailma tuomitaan: nyt tämän maailman päämies pitää heittämän ulos."],[12,32,"Ja kuin minä maasta nostetaan ylös, niin minä vedän kaikki minun tyköni.","Ja kuin minä maasta nostetaan ylös, niin minä vedän kaikki minun tyköni."],[12,33,"(Mutta sen hän sanoi, muistuttain millä kuolemalla hänen piti kuoleman.)","(Mutta sen hän sanoi, muistuttain millä kuolemalla hänen piti kuoleman.)"],[12,34,"Niin kansa vastasi häntä ja sanoi: me olemme laista kuulleet Kristuksen pysyvän ijankaikkisesti: ja kuinka sinä sanot, että Ihmisen Poika pitää nostettaman ylös? Kuka on se Ihmisen Poika?","Niin kansa vastasi häntä ja sanoi: me olemme laista kuulleet Kristuksen pysyvän ijankaikkisesti: ja kuinka sinä sanot, että Ihmisen Poika pitää nostettaman ylös? Kuka on se Ihmisen Poika?"],[12,35,"Niin Jesus sanoi heille: valkeus on vielä vähän aikaa teidän kanssanne, vaeltakaat niinkauvan kuin teillä valkeus on, ettei pimeys teitä käsittäisi. Joka pimeydessä vaeltaa, ei hän tiedä, kuhunka hän menee.","Niin Jesus sanoi heille: valkeus on vielä vähän aikaa teidän kanssanne, vaeltakaat niinkauvan kuin teillä valkeus on, ettei pimeys teitä käsittäisi. Joka pimeydessä vaeltaa, ei hän tiedä, kuhunka hän menee."],[12,36,"Uskokaat valkeuden päälle, niinkauvan kuin teillä valkeus on, että te tulisitte valkeuden lapsiksi. Näitä puhui Jesus ja meni pois, ja lymyi heitä.","Uskokaat valkeuden päälle, niinkauvan kuin teillä valkeus on, että te tulisitte valkeuden lapsiksi. Näitä puhui Jesus ja meni pois, ja lymyi heitä."],[12,37,"Ja vaikka hän teki monta ihmettä heidän nähtensä, ei he kuitenkaan uskoneet hänen päällensä,","Ja vaikka hän teki monta ihmettä heidän nähtensä, ei he kuitenkaan uskoneet hänen päällensä,"],[12,38,"Että Jesaias prophetan puhe täytettäisiin, jonka hän sanoi: Herra, kuka uskoi meidän saarnamme? ja kenelle on Herran käsivarsi ilmoitettu?","Että Jesaias prophetan puhe täytettäisiin, jonka hän sanoi: Herra, kuka uskoi meidän saarnamme? ja kenelle on Herran käsivarsi ilmoitettu?"],[12,39,"Sentähden ei he tainneet uskoa, sillä Jesaias on taas sanonut:","Sentähden ei he tainneet uskoa, sillä Jesaias on taas sanonut:"],[12,40,"Hän sokaisi heidän silmänsä, ja paadutti heidän sydämensä, ettei he näkisi silmillä, eikä ymmärtäisi sydämellä, ja kääntäisi itsiänsä, ja minä parantaisin heitä.","Hän sokaisi heidän silmänsä, ja paadutti heidän sydämensä, ettei he näkisi silmillä, eikä ymmärtäisi sydämellä, ja kääntäisi itsiänsä, ja minä parantaisin heitä."],[12,41,"Nämät sanoi Jesaias, koska hän näki hänen kunniansa ja puhui hänestä.","Nämät sanoi Jesaias, koska hän näki hänen kunniansa ja puhui hänestä."],[12,42,"Kuitenkin monta myös ylimmäisistä uskoivat hänen päällensä; vaan ei he Pharisealaisten tähden sitä tunnustaneet, ettei he olisi pannaan kuulutettu.","Kuitenkin monta myös ylimmäisistä uskoivat hänen päällensä; vaan ei he Pharisealaisten tähden sitä tunnustaneet, ettei he olisi pannaan kuulutettu."],[12,43,"Sillä he rakastivat enemmin ihmisten kunniaa, kuin Jumalan kunniaa.","Sillä he rakastivat enemmin ihmisten kunniaa, kuin Jumalan kunniaa."],[12,44,"Mutta Jesus huusi ja sanoi: joka uskoo minun päälleni, ei se usko minun päälleni, vaan sen päälle, joka minun lähetti.","Mutta Jesus huusi ja sanoi: joka uskoo minun päälleni, ei se usko minun päälleni, vaan sen päälle, joka minun lähetti."],[12,45,"Ja joka minun näkee, hän näkee sen, joka minun lähetti.","Ja joka minun näkee, hän näkee sen, joka minun lähetti."],[12,46,"Minä tulin valkeudeksi maailmaan, että jokainen, joka uskoo minun päälleni, ei pidä pimeissä oleman.","Minä tulin valkeudeksi maailmaan, että jokainen, joka uskoo minun päälleni, ei pidä pimeissä oleman."],[12,47,"Mutta jos joku minun sanani kuulee, ja ei usko, en minä häntä tuomitse; sillä en minä tullut maailmaa tuomitsemaan, vaan vapahtamaan.","Mutta jos joku minun sanani kuulee, ja ei usko, en minä häntä tuomitse; sillä en minä tullut maailmaa tuomitsemaan, vaan vapahtamaan."],[12,48,"Joka minun katsoo ylön, ja ei ota vastaan minun sanojani, hänellä on se, joka hänen tuomitsee: se puhe, jonka minä puhuin, pitää hänen tuomitseman viimeisenä päivänä.","Joka minun katsoo ylön, ja ei ota vastaan minun sanojani, hänellä on se, joka hänen tuomitsee: se puhe, jonka minä puhuin, pitää hänen tuomitseman viimeisenä päivänä."],[12,49,"Sillä en minä ole itsestäni puhunut; vaan Isä, joka minun lähetti, hän on minulle käskyn antanut, mitä minun tekemän ja puhuman pitää.","Sillä en minä ole itsestäni puhunut; vaan Isä, joka minun lähetti, hän on minulle käskyn antanut, mitä minun tekemän ja puhuman pitää."],[12,50,"Ja minä tiedän, että hänen käskynsä on ijankaikkinen elämä. Sentähden mitä minä puhun, sen minä puhun, niinkuin Isä on minulle sanonut.","Ja minä tiedän, että hänen käskynsä on ijankaikkinen elämä. Sentähden mitä minä puhun, sen minä puhun, niinkuin Isä on minulle sanonut."],[13,1,"Mutta ennen pääsiäisjuhlaa, kuin Jesus tiesi hetkensä tulleeksi, että hänen piti tästä maailmasta Isän tykö menemän, niinkuin hän oli rakastanut omiansa, jotka olivat maailmassa, niin hän loppuun asti rakasti heitä.","Mutta ennen pääsiäisjuhlaa, kuin Jesus tiesi hetkensä tulleeksi, että hänen piti tästä maailmasta Isän tykö menemän, niinkuin hän oli rakastanut omiansa, jotka olivat maailmassa, niin hän loppuun asti rakasti heitä."],[13,2,"Ja ehtoolisen jälkeen, (kuin perkele oli jo Juudaan Simonin Iskariotin sydämeen lykännyt, että hänen piti hänen pettämän,)","Ja ehtoolisen jälkeen, (kuin perkele oli jo Juudaan Simonin Iskariotin sydämeen lykännyt, että hänen piti hänen pettämän,)"],[13,3,"Tiesi Jesus Isän kaikki hänen käsiinsä antaneen, ja että hän oli Jumalasta lähtenyt ulos ja oli Jumalan tykö menevä:","Tiesi Jesus Isän kaikki hänen käsiinsä antaneen, ja että hän oli Jumalasta lähtenyt ulos ja oli Jumalan tykö menevä:"],[13,4,"Nousi hän ehtoolliselta ja riisui vaatteensa, ja otti liinaisen, ja vyötti itsensä.","Nousi hän ehtoolliselta ja riisui vaatteensa, ja otti liinaisen, ja vyötti itsensä."],[13,5,"Pani hän sitte vettä maljaan, ja rupesi pesemään opetuslasten jalkoja, ja kuivasi ne sillä liinaisella, jolla hän vyötetty oli.","Pani hän sitte vettä maljaan, ja rupesi pesemään opetuslasten jalkoja, ja kuivasi ne sillä liinaisella, jolla hän vyötetty oli."],[13,6,"Niin hän tuli Simon Pietarin tykö, joka sanoi hänelle: Herra, sinäkö minun jalkani peset?","Niin hän tuli Simon Pietarin tykö, joka sanoi hänelle: Herra, sinäkö minun jalkani peset?"],[13,7,"Jesus vastasi ja sanoi hänelle: mitä minä teen, et sinä sitä nyt tiedä, mutta tästedes saat sinä sen tietää.","Jesus vastasi ja sanoi hänelle: mitä minä teen, et sinä sitä nyt tiedä, mutta tästedes saat sinä sen tietää."],[13,8,"Pietari sanoi hänelle: ei sinun pidä ikänä pesemän minun jalkojani. Vastasi häntä Jesus: ellen minä sinua pese, niin ei sinulla ole osaa minun kanssani.","Pietari sanoi hänelle: ei sinun pidä ikänä pesemän minun jalkojani. Vastasi häntä Jesus: ellen minä sinua pese, niin ei sinulla ole osaa minun kanssani."],[13,9,"Simon Pietari sanoi hänelle: Herra, ei ainoastaan minun jalkojani, mutta myös kädet ja pää.","Simon Pietari sanoi hänelle: Herra, ei ainoastaan minun jalkojani, mutta myös kädet ja pää."],[13,10,"Sanoi Jesus hänelle: joka pesty on, ei se muuta tarvitse, vaan että jalat pestään, ja niin hän on kokonansa puhdas: ja te olette puhtaat, ette kuitenkaan kaikki.","Sanoi Jesus hänelle: joka pesty on, ei se muuta tarvitse, vaan että jalat pestään, ja niin hän on kokonansa puhdas: ja te olette puhtaat, ette kuitenkaan kaikki."],[13,11,"Sillä hän tiesi pettäjänsä; sentähden hän sanoi: ette kaikki ole puhtaat.","Sillä hän tiesi pettäjänsä; sentähden hän sanoi: ette kaikki ole puhtaat."],[13,12,"Sittekuin hän oli pessyt heidän jalkansa ja vaatteensa ottanut, istui hän taas ja sanoi heille: tiedättekö, mitä minä teille tehnyt olen?","Sittekuin hän oli pessyt heidän jalkansa ja vaatteensa ottanut, istui hän taas ja sanoi heille: tiedättekö, mitä minä teille tehnyt olen?"],[13,13,"Te kutsutte minun Mestariksi ja Herraksi, ja te sanotte oikein; sillä minä myös olen.","Te kutsutte minun Mestariksi ja Herraksi, ja te sanotte oikein; sillä minä myös olen."],[13,14,"Sentähden, jos minä, joka olen Herra ja Mestari, olen teidän jalkanne pessyt, niin pitää myös teidänkin toinen toisenne jalat pesemän.","Sentähden, jos minä, joka olen Herra ja Mestari, olen teidän jalkanne pessyt, niin pitää myös teidänkin toinen toisenne jalat pesemän."],[13,15,"Sillä minä annoin teille esikuvan, että te niin tekisitte, kuin minä tein teille.","Sillä minä annoin teille esikuvan, että te niin tekisitte, kuin minä tein teille."],[13,16,"Totisesti, totisesti sanon minä teille: ei ole palvelia suurempi herraansa, eikä sanansaattaja suurempi kuin se, joka hänen lähetti.","Totisesti, totisesti sanon minä teille: ei ole palvelia suurempi herraansa, eikä sanansaattaja suurempi kuin se, joka hänen lähetti."],[13,17,"Jos te nämät tiedätte, te olette autuaat, jos te niitä teette.","Jos te nämät tiedätte, te olette autuaat, jos te niitä teette."],[13,18,"En minä kaikista teistä puhu: minä tiedän ne, jotka minä valitsin: mutta että Raamattu täytettäisiin: joka syö leipää minun kanssani, hän tallasi minun jalallansa.","En minä kaikista teistä puhu: minä tiedän ne, jotka minä valitsin: mutta että Raamattu täytettäisiin: joka syö leipää minun kanssani, hän tallasi minun jalallansa."],[13,19,"Nyt minä sanon teille ennenkuin se tapahtuu, että sittekuin se tapahtunut on, te uskoisitte minun siksi.","Nyt minä sanon teille ennenkuin se tapahtuu, että sittekuin se tapahtunut on, te uskoisitte minun siksi."],[13,20,"Totisesti, totisesti sanon minä teille: joka korjaa sen, jonka minä lähetän, hän korjaa minun; mutta joka minun korjaa, hän korjaa sen, joka minun lähetti.","Totisesti, totisesti sanon minä teille: joka korjaa sen, jonka minä lähetän, hän korjaa minun; mutta joka minun korjaa, hän korjaa sen, joka minun lähetti."],[13,21,"Kuin Jesus nämät oli sanonut, tuli hän murheelliseksi hengessä, ja todisti ja sanoi: totisesti, totisesti sanon minä teille: yksi on teistä minun pettävä.","Kuin Jesus nämät oli sanonut, tuli hän murheelliseksi hengessä, ja todisti ja sanoi: totisesti, totisesti sanon minä teille: yksi on teistä minun pettävä."],[13,22,"Niin opetuslapset katselivat toinen toisensa päälle, ja epäilivät, kenestä hän sanoi.","Niin opetuslapset katselivat toinen toisensa päälle, ja epäilivät, kenestä hän sanoi."],[13,23,"Ja yksi hänen opetuslapsistansa istui pöydän tykönä Jesuksen helmassa, jota Jesus rakasti.","Ja yksi hänen opetuslapsistansa istui pöydän tykönä Jesuksen helmassa, jota Jesus rakasti."],[13,24,"Niin Simon Pietari viittasi sille, visusti kysymään, kuka se olis, josta hän sanoi.","Niin Simon Pietari viittasi sille, visusti kysymään, kuka se olis, josta hän sanoi."],[13,25,"Kuin hän nojasi Jesuksen rintaa vastaan, sanoi hän hänelle: Herra, kuka se on?","Kuin hän nojasi Jesuksen rintaa vastaan, sanoi hän hänelle: Herra, kuka se on?"],[13,26,"Jesus vastasi: se on se, jolle minä kastetun palan annan. Ja kuin hän oli kastanut leivän, antoi hän sen Juudaalle Simon Iskariotille.","Jesus vastasi: se on se, jolle minä kastetun palan annan. Ja kuin hän oli kastanut leivän, antoi hän sen Juudaalle Simon Iskariotille."],[13,27,"Ja sen palan jälkeen meni silloin häneen perkele. Niin Jesus sanoi hänelle: mitäs teet, niin tee pikemmin.","Ja sen palan jälkeen meni silloin häneen perkele. Niin Jesus sanoi hänelle: mitäs teet, niin tee pikemmin."],[13,28,"Mutta sitä ei yksikään atrioitsevista ymmärtänyt, mitä varten hän sen hänelle sanoi.","Mutta sitä ei yksikään atrioitsevista ymmärtänyt, mitä varten hän sen hänelle sanoi."],[13,29,"Sillä muutamat luulivat, koska Juudaalla oli kukkaro, Jesuksen hänelle sanovan: osta, mitä me juhlapäiväksi tarvitsemme, eli että hän vaivaisille jotakin antais.","Sillä muutamat luulivat, koska Juudaalla oli kukkaro, Jesuksen hänelle sanovan: osta, mitä me juhlapäiväksi tarvitsemme, eli että hän vaivaisille jotakin antais."],[13,30,"Kuin hän siis sen palan ottanut oli, meni hän kohta ulos; ja yö oli.","Kuin hän siis sen palan ottanut oli, meni hän kohta ulos; ja yö oli."],[13,31,"Kuin hän oli mennyt ulos, sanoi Jesus: nyt on Ihmisen Poika kirkastettu, ja Jumala on kirkastettu hänessä.","Kuin hän oli mennyt ulos, sanoi Jesus: nyt on Ihmisen Poika kirkastettu, ja Jumala on kirkastettu hänessä."],[13,32,"Jos Jumala on kirkastettu hänessä, niin on myös Jumala kirkastava hänen itsessänsä, ja kirkastaa hänen pian.","Jos Jumala on kirkastettu hänessä, niin on myös Jumala kirkastava hänen itsessänsä, ja kirkastaa hänen pian."],[13,33,"Rakkaat lapsukaiset, minä olen vielä vähän aikaa teidän kanssanne: teidän pitää minua etsimän, ja niinkuin minä sanoin Juudalaisille: ette taida sinne tulla, kuhunka minä menen, niin minä sanon myös nyt teille.","Rakkaat lapsukaiset, minä olen vielä vähän aikaa teidän kanssanne: teidän pitää minua etsimän, ja niinkuin minä sanoin Juudalaisille: ette taida sinne tulla, kuhunka minä menen, niin minä sanon myös nyt teille."],[13,34,"Uuden käskyn minä teille annan, että te rakastaisitte teitänne keskenänne, niinkuin minä teitä rakastin, että te myös toinen toistanne rakastaisitte.","Uuden käskyn minä teille annan, että te rakastaisitte teitänne keskenänne, niinkuin minä teitä rakastin, että te myös toinen toistanne rakastaisitte."],[13,35,"Siitä pitää kaikkein tunteman teidät minun opetuslapsikseni, jos te keskenänne rakkauden pidätte.","Siitä pitää kaikkein tunteman teidät minun opetuslapsikseni, jos te keskenänne rakkauden pidätte."],[13,36,"Sanoi Simon Pietari hänelle: Herra, kuhunkas menet? Jesus vastasi häntä: kuhunka minä menen, et sinä taida nyt minua seurata, mutta tästälähin sinä olet minua seuraava.","Sanoi Simon Pietari hänelle: Herra, kuhunkas menet? Jesus vastasi häntä: kuhunka minä menen, et sinä taida nyt minua seurata, mutta tästälähin sinä olet minua seuraava."],[13,37,"Pietari sanoi hänelle: Herra, miksi en minä nyt taida sinua seurata? minä panen henkeni sinun edestäs.","Pietari sanoi hänelle: Herra, miksi en minä nyt taida sinua seurata? minä panen henkeni sinun edestäs."],[13,38,"Jesus vastasi häntä: sinä panet henkes minun edestäni? Totisesti, totisesti sanon minä sinulle: ei laula kukko ennenkuin sinä olet kolmasti minun kieltänyt.","Jesus vastasi häntä: sinä panet henkes minun edestäni? Totisesti, totisesti sanon minä sinulle: ei laula kukko ennenkuin sinä olet kolmasti minun kieltänyt."],[14,1,"(Ja hän sanoi opetuslapsillensa:) älkööt teidän sydämenne murheellinen olko; jos te uskotte Jumalan päälle, niin uskokaat myös minun päälleni.","(Ja hän sanoi opetuslapsillensa:) älkööt teidän sydämenne murheellinen olko; jos te uskotte Jumalan päälle, niin uskokaat myös minun päälleni."],[14,2,"Minun Isäni huoneessa on monta asuinsiaa; jos ei niin olisi, niin minä sanoisin teille: minä menen valmistamaan teille siaa.","Minun Isäni huoneessa on monta asuinsiaa; jos ei niin olisi, niin minä sanoisin teille: minä menen valmistamaan teille siaa."],[14,3,"Ja vaikka minä menen pois valmistamaan teille siaa, niin minä tulen jälleen ja otan teidät tyköni, että kussa minä olen, siellä pitää myös teidän oleman.","Ja vaikka minä menen pois valmistamaan teille siaa, niin minä tulen jälleen ja otan teidät tyköni, että kussa minä olen, siellä pitää myös teidän oleman."],[14,4,"Ja kuhunka minä menen, te tiedätte, ja tien te myös tiedätte.","Ja kuhunka minä menen, te tiedätte, ja tien te myös tiedätte."],[14,5,"Sanoi Toomas hänelle: Herra, emme tiedä, kuhunkas menet: kuinka siis me taidamme tietää tien?","Sanoi Toomas hänelle: Herra, emme tiedä, kuhunkas menet: kuinka siis me taidamme tietää tien?"],[14,6,"Jesus sanoi hänelle: minä olen tie, totuus ja elämä. Ei kenkään tule Isän tykö, vaan minun kauttani.","Jesus sanoi hänelle: minä olen tie, totuus ja elämä. Ei kenkään tule Isän tykö, vaan minun kauttani."],[14,7,"Jos te tuntisitte minun, niin te tosin myös tuntisitte Isäni; ja nyt te tunnette hänen, ja te näette hänen.","Jos te tuntisitte minun, niin te tosin myös tuntisitte Isäni; ja nyt te tunnette hänen, ja te näette hänen."],[14,8,"Philippus sanoi hänelle: Herra, osoita meille Isä, niin me tyydymme.","Philippus sanoi hänelle: Herra, osoita meille Isä, niin me tyydymme."],[14,9,"Jesus sanoi hänelle: minä olen niin kauvan aikaa teidän tykönänne, ja et sinä minua tunne? Philippus, joka näki minun, hän näki myös Isän: kuinka siis sinä sanot: osoita minulle Isä?","Jesus sanoi hänelle: minä olen niin kauvan aikaa teidän tykönänne, ja et sinä minua tunne? Philippus, joka näki minun, hän näki myös Isän: kuinka siis sinä sanot: osoita minulle Isä?"],[14,10,"Etkös usko minun olevan Isässä ja Isän minussa? Ne sanat, jotka minä teille puhun, en minä itsestäni puhu: mutta Isä, joka minussa on, hän tekee työt.","Etkös usko minun olevan Isässä ja Isän minussa? Ne sanat, jotka minä teille puhun, en minä itsestäni puhu: mutta Isä, joka minussa on, hän tekee työt."],[14,11,"Uskokaat minua, että minä olen Isässä ja Isä on minussa; mutta jos ei, niin töiden tähden uskokaat minua.","Uskokaat minua, että minä olen Isässä ja Isä on minussa; mutta jos ei, niin töiden tähden uskokaat minua."],[14,12,"Totisesti, totisesti sanon minä teille: joka uskoo minun päälleni, ne työt, joita minä teen, hän on myös tekevä, ja suurempia, kuin ne ovat, on hän tekevä; sillä minä menen Isäni tykö.","Totisesti, totisesti sanon minä teille: joka uskoo minun päälleni, ne työt, joita minä teen, hän on myös tekevä, ja suurempia, kuin ne ovat, on hän tekevä; sillä minä menen Isäni tykö."],[14,13,"Ja mitä ikänä te anotte minun nimeeni, sen minä teen: että Isä kunnioitettaisiin Pojan kautta.","Ja mitä ikänä te anotte minun nimeeni, sen minä teen: että Isä kunnioitettaisiin Pojan kautta."],[14,14,"Mitä te anotte minun nimeeni, sen minä teen.","Mitä te anotte minun nimeeni, sen minä teen."],[14,15,"Jos te rakastatte minua, niin pitäkäät minun käskyni.","Jos te rakastatte minua, niin pitäkäät minun käskyni."],[14,16,"Ja minä olen rukoileva Isää, ja hän antaa teille toisen Lohduttajan, että hän teidän kanssanne olis ijankaikkisesti:","Ja minä olen rukoileva Isää, ja hän antaa teille toisen Lohduttajan, että hän teidän kanssanne olis ijankaikkisesti:"],[14,17,"Totuuden Hengen, jota ei maailma taida ottaa vastaan, sillä ei he näe häntä, eikä tunne häntä: mutta te tunnette hänen, sillä hän pysyy teidän tykönänne ja on teissä oleva.","Totuuden Hengen, jota ei maailma taida ottaa vastaan, sillä ei he näe häntä, eikä tunne häntä: mutta te tunnette hänen, sillä hän pysyy teidän tykönänne ja on teissä oleva."],[14,18,"En minä jätä teitä orvoiksi, vaan minä tulen teidän tykönne.","En minä jätä teitä orvoiksi, vaan minä tulen teidän tykönne."],[14,19,"Vielä on vähän aikaa, ja ei maailma silleen minua näe, mutta te näette minun; sillä minä elän, ja te myös elätte.","Vielä on vähän aikaa, ja ei maailma silleen minua näe, mutta te näette minun; sillä minä elän, ja te myös elätte."],[14,20,"Sinä päivänä pitää teidän ymmärtämän, että minä olen Isässä, ja te minussa ja minä teissä.","Sinä päivänä pitää teidän ymmärtämän, että minä olen Isässä, ja te minussa ja minä teissä."],[14,21,"Jolla minun käskyni ovat ja ne kätkee, se rakastaa minua: mutta joka minua rakastaa, hän rakastetaan minun Isältäni, ja minä tahdon häntä rakastaa, ja ilmoitan itseni hänelle.","Jolla minun käskyni ovat ja ne kätkee, se rakastaa minua: mutta joka minua rakastaa, hän rakastetaan minun Isältäni, ja minä tahdon häntä rakastaa, ja ilmoitan itseni hänelle."],[14,22,"Sanoi hänelle Juudas: (ei se Iskariot) Herra, kuinka se tulee, ettäs tahdot meille itses ilmoittaa, ja et maailmalle?","Sanoi hänelle Juudas: (ei se Iskariot) Herra, kuinka se tulee, ettäs tahdot meille itses ilmoittaa, ja et maailmalle?"],[14,23,"Jesus vastasi ja sanoi hänelle: joka minua rakastaa, se pitää minun sanani; ja minun Isäni rakastaa häntä, ja me tulemme hänen tykönsä, ja asumme hänen tykönänsä.","Jesus vastasi ja sanoi hänelle: joka minua rakastaa, se pitää minun sanani; ja minun Isäni rakastaa häntä, ja me tulemme hänen tykönsä, ja asumme hänen tykönänsä."],[14,24,"Joka ei minua rakasta, ei se minun sanojani kätke: ja se sana, jonka te kuulette, ei ole minun, vaan Isän joka minun lähetti.","Joka ei minua rakasta, ei se minun sanojani kätke: ja se sana, jonka te kuulette, ei ole minun, vaan Isän joka minun lähetti."],[14,25,"Näitä olen minä teille puhunut, ollessani teidän kanssanne.","Näitä olen minä teille puhunut, ollessani teidän kanssanne."],[14,26,"Mutta Lohduttaja, Pyhä Henki, jonka Isä on lähettävä minun nimeeni, hän opettaa teille kaikki ja muistuttaa teille kaikki, mitä minä teille sanonut olen.","Mutta Lohduttaja, Pyhä Henki, jonka Isä on lähettävä minun nimeeni, hän opettaa teille kaikki ja muistuttaa teille kaikki, mitä minä teille sanonut olen."],[14,27,"Rauhan minä jätän teille, minun rauhani minä annan teille: en minä anna teille niinkuin maailma antaa. Älkään teidän sydämenne murheellinen olko, älkään myös peljätkö.","Rauhan minä jätän teille, minun rauhani minä annan teille: en minä anna teille niinkuin maailma antaa. Älkään teidän sydämenne murheellinen olko, älkään myös peljätkö."],[14,28,"Te kuulitte minun sanovan: minä menen pois ja tulen jälleen teidän tykönne. Jos te minua rakastaisitte, niin te tosin iloitsisitte, että minä sanoin: minä menen Isän tykö; sillä Isä on suurempi minua.","Te kuulitte minun sanovan: minä menen pois ja tulen jälleen teidän tykönne. Jos te minua rakastaisitte, niin te tosin iloitsisitte, että minä sanoin: minä menen Isän tykö; sillä Isä on suurempi minua."],[14,29,"Ja nyt minä sanon teille ennen kuin se tapahtuu, että te uskoisitte, kuin se tapahtunut on.","Ja nyt minä sanon teille ennen kuin se tapahtuu, että te uskoisitte, kuin se tapahtunut on."],[14,30,"En minä tästedes puhu paljon teidän kanssanne; sillä tämän maailman päämies tulee, jolla ei ole mitään minussa.","En minä tästedes puhu paljon teidän kanssanne; sillä tämän maailman päämies tulee, jolla ei ole mitään minussa."],[14,31,"Mutta että maailma ymmärtäis minun Isää rakastavan, ja niinkuin Isä minulle käski, niin minä myös teen. Nouskaat, lähtekäämme täältä!","Mutta että maailma ymmärtäis minun Isää rakastavan, ja niinkuin Isä minulle käski, niin minä myös teen. Nouskaat, lähtekäämme täältä!"],[15,1,"Minä olen totinen viinipuu, ja minun Isäni on peltomies:","Minä olen totinen viinipuu, ja minun Isäni on peltomies:"],[15,2,"Jokaisen oksan minussa, joka ei kanna hedelmää, hän karsii pois, ja jokaisen, joka hedelmän kantaa, hän puhdistaa, että se kantais runsaamman hedelmän.","Jokaisen oksan minussa, joka ei kanna hedelmää, hän karsii pois, ja jokaisen, joka hedelmän kantaa, hän puhdistaa, että se kantais runsaamman hedelmän."],[15,3,"Te olette nyt puhtaat, sen sanan tähden, jonka minä teille puhuin.","Te olette nyt puhtaat, sen sanan tähden, jonka minä teille puhuin."],[15,4,"Pysykäät te minussa, ja minä teissä. Niinkuin ei oksa taida itsestänsä hedelmää kantaa, ellei hän viinapuussa kiinni ole, niin ette tekään, jollette minussa pysy.","Pysykäät te minussa, ja minä teissä. Niinkuin ei oksa taida itsestänsä hedelmää kantaa, ellei hän viinapuussa kiinni ole, niin ette tekään, jollette minussa pysy."],[15,5,"Minä olen viinapuu, te olette oksat: joka minussa pysyy ja minä hänessä, hän kantaa paljon hedelmää; sillä ilman minua ette voi mitään tehdä.","Minä olen viinapuu, te olette oksat: joka minussa pysyy ja minä hänessä, hän kantaa paljon hedelmää; sillä ilman minua ette voi mitään tehdä."],[15,6,"Jos ei joku minussa pysy, se heitetään ulos niinkuin oksa, ja kuivettuu, ja ne sidotaan kokoon, ja heitetään tuleen, ja palavat.","Jos ei joku minussa pysy, se heitetään ulos niinkuin oksa, ja kuivettuu, ja ne sidotaan kokoon, ja heitetään tuleen, ja palavat."],[15,7,"Jos te minussa pysytte ja minun sanani pysyvät teissä, mitkä ikänä te tahdotte, niin anokaat, ja te saatte.","Jos te minussa pysytte ja minun sanani pysyvät teissä, mitkä ikänä te tahdotte, niin anokaat, ja te saatte."],[15,8,"Siinä minun Isäni kunnioitetaan, että te paljon hedelmää kantaisitte, ja tulette minun opetuslapsikseni.","Siinä minun Isäni kunnioitetaan, että te paljon hedelmää kantaisitte, ja tulette minun opetuslapsikseni."],[15,9,"Niinkuin Isä rakasti minua, niin minä myös rakastin teitä: pysykäät minun rakkaudessani.","Niinkuin Isä rakasti minua, niin minä myös rakastin teitä: pysykäät minun rakkaudessani."],[15,10,"Jos te minun käskyni pidätte, niin te pysytte minun rakkaudessani, niinkuin minä pidän Isäni käskyn ja pysyn hänen rakkaudessansa.","Jos te minun käskyni pidätte, niin te pysytte minun rakkaudessani, niinkuin minä pidän Isäni käskyn ja pysyn hänen rakkaudessansa."],[15,11,"Näitä olen minä teille puhunut, että minun iloni teissä pysyis ja teidän ilonne tulis täydelliseksi.","Näitä olen minä teille puhunut, että minun iloni teissä pysyis ja teidän ilonne tulis täydelliseksi."],[15,12,"Se on minun käskyni, että te rakastatte teitänne keskenänne, niinkuin minä teitä rakastin.","Se on minun käskyni, että te rakastatte teitänne keskenänne, niinkuin minä teitä rakastin."],[15,13,"Ei ole kellään sitä suurempaa rakkautta, kuin että joku panis henkensä ystäväinsä edestä.","Ei ole kellään sitä suurempaa rakkautta, kuin että joku panis henkensä ystäväinsä edestä."],[15,14,"Te olette minun ystäväni, jos te teette, mitä minä teidän käsken.","Te olette minun ystäväni, jos te teette, mitä minä teidän käsken."],[15,15,"En minä tästedes sano teitä palvelijoiksi; sillä ei palvelia tiedä, mitä hänen herransa tekee; mutta minä kutsun teitä ystäviksi, sillä kaikki, mitä minä Isältäni kuulin, ne minä teille ilmoitin.","En minä tästedes sano teitä palvelijoiksi; sillä ei palvelia tiedä, mitä hänen herransa tekee; mutta minä kutsun teitä ystäviksi, sillä kaikki, mitä minä Isältäni kuulin, ne minä teille ilmoitin."],[15,16,"Ette minua valinneet, vaan minä valitsin teidät, ja sääsin teidät, että te menisitte hedelmää tekemään ja teidän hedelmänne pysyis: että mitä te anotte Isältä minun nimeeni, sen hän antaa teille.","Ette minua valinneet, vaan minä valitsin teidät, ja sääsin teidät, että te menisitte hedelmää tekemään ja teidän hedelmänne pysyis: että mitä te anotte Isältä minun nimeeni, sen hän antaa teille."],[15,17,"Näitä minä käsken teille, että te toinen toistanne rakastaisitte.","Näitä minä käsken teille, että te toinen toistanne rakastaisitte."],[15,18,"Jos maailma teitä vihaa, niin tietäkäät hänen ennen minua vihanneen kuin teitä.","Jos maailma teitä vihaa, niin tietäkäät hänen ennen minua vihanneen kuin teitä."],[15,19,"Jos te maailmasta olisitte, niin maailma omaansa rakastais; mutta ette ole maailmasta, vaan minä valitsin teidät maailmasta, sentähden maailma vihaa teitä.","Jos te maailmasta olisitte, niin maailma omaansa rakastais; mutta ette ole maailmasta, vaan minä valitsin teidät maailmasta, sentähden maailma vihaa teitä."],[15,20,"Muistakaat sitä sanaa, jonka minä teille sanoin: ei ole palvelia suurempi herraansa. Jos he minua vainosivat, niin he myös teitä vainoovat: jos he minun sanani kätkivät, niin he teidänkin sananne kätkevät.","Muistakaat sitä sanaa, jonka minä teille sanoin: ei ole palvelia suurempi herraansa. Jos he minua vainosivat, niin he myös teitä vainoovat: jos he minun sanani kätkivät, niin he teidänkin sananne kätkevät."],[15,21,"Mutta kaikkia näitä tekevät he teille minun nimeni tähden; sillä ei he tunne sitä, joka minun lähetti.","Mutta kaikkia näitä tekevät he teille minun nimeni tähden; sillä ei he tunne sitä, joka minun lähetti."],[15,22,"Jos en minä olisi tullut ja heitä puhutellut, niin ei heillä olisi syntiä; mutta nyt ei heillä ole, millä he syntinsä verhoovat.","Jos en minä olisi tullut ja heitä puhutellut, niin ei heillä olisi syntiä; mutta nyt ei heillä ole, millä he syntinsä verhoovat."],[15,23,"Joka minua vihaa, hän vihaa myös minun Isääni.","Joka minua vihaa, hän vihaa myös minun Isääni."],[15,24,"Ellen minä olisi niitä töitä heidän seassansa tehnyt, joita ei kenkään muu ole tehnyt, niin ei heillä olisi syntiä; mutta nyt he näkivät, ja vihasivat sekä minua että minun Isääni.","Ellen minä olisi niitä töitä heidän seassansa tehnyt, joita ei kenkään muu ole tehnyt, niin ei heillä olisi syntiä; mutta nyt he näkivät, ja vihasivat sekä minua että minun Isääni."],[15,25,"Vaan (se tapahtui) että se täytettäisiin, mitä heidän laissansa on kirjoitettu: he vihasivat minua ilman syytä.","Vaan (se tapahtui) että se täytettäisiin, mitä heidän laissansa on kirjoitettu: he vihasivat minua ilman syytä."],[15,26,"Mutta kuin Lohduttaja tulee, jonka minä teille Isältä lähetän, totuuden Henki, joka Isästä käy ulos, se on minusta todistava.","Mutta kuin Lohduttaja tulee, jonka minä teille Isältä lähetän, totuuden Henki, joka Isästä käy ulos, se on minusta todistava."],[15,27,"Ja teidän pitää myös todistaman; sillä te olette alusta minun kanssani.","Ja teidän pitää myös todistaman; sillä te olette alusta minun kanssani."],[16,1,"Näitä olen minä puhunut teille, ette pahenisi.","Näitä olen minä puhunut teille, ette pahenisi."],[16,2,"He panevat teitä pannaan. Ja aika tulee, että jokainen, joka teidät tappaa, se luulee tekevänsä Jumalalle palveluksen.","He panevat teitä pannaan. Ja aika tulee, että jokainen, joka teidät tappaa, se luulee tekevänsä Jumalalle palveluksen."],[16,3,"Ja näitä he tekevät teille, ettei he tunne Isää eikä minua.","Ja näitä he tekevät teille, ettei he tunne Isää eikä minua."],[16,4,"Vaan minä puhuin näitä teille, että kuin se aika tulee, te niistä muistaisitte, että minä teille sanonut olen; mutta en minä ole teille näitä alusta sanonut, sillä minä olin teidän kanssanne.","Vaan minä puhuin näitä teille, että kuin se aika tulee, te niistä muistaisitte, että minä teille sanonut olen; mutta en minä ole teille näitä alusta sanonut, sillä minä olin teidän kanssanne."],[16,5,"Mutta nyt minä menen sen tykö, joka minun lähetti, ja ei teistä minulta kenkään kysy: kuhunkas menet?","Mutta nyt minä menen sen tykö, joka minun lähetti, ja ei teistä minulta kenkään kysy: kuhunkas menet?"],[16,6,"Vaan että minä olen näitä teille puhunut, niin murhe täyttää teidän sydämenne.","Vaan että minä olen näitä teille puhunut, niin murhe täyttää teidän sydämenne."],[16,7,"Kuitenkin sanon minä teille totuuden: se on teille tarpeellinen, että minä menen pois; sillä ellen minä mene pois, niin ei Lohduttaja tule teidän tykönne; mutta jos minä menen pois, niin minä hänen teille lähetän.","Kuitenkin sanon minä teille totuuden: se on teille tarpeellinen, että minä menen pois; sillä ellen minä mene pois, niin ei Lohduttaja tule teidän tykönne; mutta jos minä menen pois, niin minä hänen teille lähetän."],[16,8,"Ja kuin hän tulee, niin hän nuhtelee maailmaa synnin tähden, ja vanhurskauden tähden, ja tuomion tähden.","Ja kuin hän tulee, niin hän nuhtelee maailmaa synnin tähden, ja vanhurskauden tähden, ja tuomion tähden."],[16,9,"Synnin tähden tosin, ettei he usko minun päälleni;","Synnin tähden tosin, ettei he usko minun päälleni;"],[16,10,"Mutta vanhurskauden tähden, että minä menen Isäni tykö, ja ettette minua silleen näe;","Mutta vanhurskauden tähden, että minä menen Isäni tykö, ja ettette minua silleen näe;"],[16,11,"Mutta tuomion tähden, että tämän maailman päämies on tuomittu.","Mutta tuomion tähden, että tämän maailman päämies on tuomittu."],[16,12,"Minulla on vielä paljo sanomista, mutta ette voi nyt kantaa.","Minulla on vielä paljo sanomista, mutta ette voi nyt kantaa."],[16,13,"Vaan kuin se tulee, totuuden Henki, hän johdattaa teitä kaikkeen totuuteen; sillä ei hän puhu itsestänsä, vaan mitä hän kuulee, sitä hän puhuu, ja tulevaisia hän teille ilmoittaa.","Vaan kuin se tulee, totuuden Henki, hän johdattaa teitä kaikkeen totuuteen; sillä ei hän puhu itsestänsä, vaan mitä hän kuulee, sitä hän puhuu, ja tulevaisia hän teille ilmoittaa."],[16,14,"Hän on minua kunnioittava; sillä hän ottaa minun omastani ja ilmoittaa teille.","Hän on minua kunnioittava; sillä hän ottaa minun omastani ja ilmoittaa teille."],[16,15,"Kaikki, mitä Isällä on, ne ovat minun; sentähden minä sanoin, että hän ottaa minun omastani ja ilmoittaa teille.","Kaikki, mitä Isällä on, ne ovat minun; sentähden minä sanoin, että hän ottaa minun omastani ja ilmoittaa teille."],[16,16,"Vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä te näette minun; sillä minä menen Isäni tykö.","Vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä te näette minun; sillä minä menen Isäni tykö."],[16,17,"Niin muutamat hänen opetuslapsistansa puhuivat keskenänsä: mikä se on, kuin hän sanoo meille: vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä ja te näette minun, ja: minä menen Isän tykö?","Niin muutamat hänen opetuslapsistansa puhuivat keskenänsä: mikä se on, kuin hän sanoo meille: vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä ja te näette minun, ja: minä menen Isän tykö?"],[16,18,"Niin he sanoivat: mikä se on, kuin hän sanoo: vähän ajan perästä? emme tiedä, mitä hän puhuu.","Niin he sanoivat: mikä se on, kuin hän sanoo: vähän ajan perästä? emme tiedä, mitä hän puhuu."],[16,19,"Niin Jesus ymmärsi, että he tahtoivat kysyä häneltä, ja sanoi heille: sitä te kysytte keskenänne, että minä sanoin: vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä ja te näette minun.","Niin Jesus ymmärsi, että he tahtoivat kysyä häneltä, ja sanoi heille: sitä te kysytte keskenänne, että minä sanoin: vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä ja te näette minun."],[16,20,"Totisesti, totisesti sanon minä teille: teidän pitää itkemän ja parkuman, mutta maailma iloitsee: te tulette murheellisiksi, mutta teidän murheenne käännetään iloksi.","Totisesti, totisesti sanon minä teille: teidän pitää itkemän ja parkuman, mutta maailma iloitsee: te tulette murheellisiksi, mutta teidän murheenne käännetään iloksi."],[16,21,"Kuin vaimo synnyttää, niin hänellä on kipu, sillä hänen hetkensä tuli; mutta kuin hän on lapsen synnyttänyt, niin ei hän enään muista vaivaansa ilon tähden, että ihminen on syntynyt maailmaan.","Kuin vaimo synnyttää, niin hänellä on kipu, sillä hänen hetkensä tuli; mutta kuin hän on lapsen synnyttänyt, niin ei hän enään muista vaivaansa ilon tähden, että ihminen on syntynyt maailmaan."],[16,22,"Niin teillä on myös nyt murhe; mutta minä tahdon teitä jällensä nähdä, ja teidän sydämenne on iloitseva, ja ei kenenkään pidä teidän iloanne teiltä ottaman pois.","Niin teillä on myös nyt murhe; mutta minä tahdon teitä jällensä nähdä, ja teidän sydämenne on iloitseva, ja ei kenenkään pidä teidän iloanne teiltä ottaman pois."],[16,23,"Ja sinä päivänä ette mitään kysy minulta. Totisesti, totisesti sanon minä teille: mitä ikänä te anotte Isältä minun nimeeni, niin hän antaa teille.","Ja sinä päivänä ette mitään kysy minulta. Totisesti, totisesti sanon minä teille: mitä ikänä te anotte Isältä minun nimeeni, niin hän antaa teille."],[16,24,"Ette ole mitään minun nimeeni tähän asti anoneet: rukoilkaat, niin te saatte, että teidän ilonne olis täydellinen.","Ette ole mitään minun nimeeni tähän asti anoneet: rukoilkaat, niin te saatte, että teidän ilonne olis täydellinen."],[16,25,"Näitä olen minä teille puhunut tapauksissa; mutta aika tulee, etten minä silleen puhu teille tapauksissa, vaan ilmoitan julkisesti teille minun Isästäni.","Näitä olen minä teille puhunut tapauksissa; mutta aika tulee, etten minä silleen puhu teille tapauksissa, vaan ilmoitan julkisesti teille minun Isästäni."],[16,26,"Sinä päivänä pitää teidän rukoileman minun nimeeni. Ja en minä sano teille, että minä rukoilen Isää teidän tähtenne;","Sinä päivänä pitää teidän rukoileman minun nimeeni. Ja en minä sano teille, että minä rukoilen Isää teidän tähtenne;"],[16,27,"Sillä Isä rakastaa itse teitä, että te minua rakastitte ja uskoitte minun Jumalasta lähteneen.","Sillä Isä rakastaa itse teitä, että te minua rakastitte ja uskoitte minun Jumalasta lähteneen."],[16,28,"Minä läksin Isästä ja tulin maailmaan: taas minä jätän maailman ja menen Isän tykö.","Minä läksin Isästä ja tulin maailmaan: taas minä jätän maailman ja menen Isän tykö."],[16,29,"Sanoivat hänen opetuslapsensa hänelle: katso, nyt sinä julkisesti puhut, ja et yhtään tapausta sano.","Sanoivat hänen opetuslapsensa hänelle: katso, nyt sinä julkisesti puhut, ja et yhtään tapausta sano."],[16,30,"Nyt me tiedämme sinun kaikki tietävän, ja et sinä tarvitse, että joku sinulta kysyy, sentähden me uskomme sinun Jumalasta lähteneen.","Nyt me tiedämme sinun kaikki tietävän, ja et sinä tarvitse, että joku sinulta kysyy, sentähden me uskomme sinun Jumalasta lähteneen."],[16,31,"Jesus vastasi heitä: nyt te uskotte.","Jesus vastasi heitä: nyt te uskotte."],[16,32,"Katso, aika tulee, ja nyt tuli, että te jokainen hajoitetaan omillensa, ja minun te yksinäni jätätte. En minä kuitenkaan yksinäni ole, sillä Isä on minun kanssani.","Katso, aika tulee, ja nyt tuli, että te jokainen hajoitetaan omillensa, ja minun te yksinäni jätätte. En minä kuitenkaan yksinäni ole, sillä Isä on minun kanssani."],[16,33,"Näitä olen minä teille puhunut, että teillä minussa rauha olis. Maailmassa on teillä tuska; mutta olkaat hyvässä turvassa, minä voitin maailman.","Näitä olen minä teille puhunut, että teillä minussa rauha olis. Maailmassa on teillä tuska; mutta olkaat hyvässä turvassa, minä voitin maailman."],[17,1,"Näitä puhui Jesus, ja nosti silmänsä taivasta päin ja sanoi: Isä, hetki tuli, kirkasta sinun Poikas, että sinun Poikas kirkastais myös sinun!","Näitä puhui Jesus, ja nosti silmänsä taivasta päin ja sanoi: Isä, hetki tuli, kirkasta sinun Poikas, että sinun Poikas kirkastais myös sinun!"],[17,2,"Niinkuin sinä annoit hänelle vallan kaiken lihan päälle, antaa ijankaikkisen elämän kaikille, jotka sinä hänelle annoit.","Niinkuin sinä annoit hänelle vallan kaiken lihan päälle, antaa ijankaikkisen elämän kaikille, jotka sinä hänelle annoit."],[17,3,"Mutta tämä on ijankaikkinen elämä, että he sinun ainoan totisen Jumalan tuntisivat, ja jonkas lähetit, Jesuksen Kristuksen.","Mutta tämä on ijankaikkinen elämä, että he sinun ainoan totisen Jumalan tuntisivat, ja jonkas lähetit, Jesuksen Kristuksen."],[17,4,"Minä kirkastin sinun maan päällä: minä täytin sen työn, jonkas minulle annoit tehdäkseni.","Minä kirkastin sinun maan päällä: minä täytin sen työn, jonkas minulle annoit tehdäkseni."],[17,5,"Ja nyt Isä, kirkasta sinä minua itse tykänäs sillä kirkkaudella, joka minulla sinun tykönäs oli ennenkuin tämä maailma olikaan.","Ja nyt Isä, kirkasta sinä minua itse tykänäs sillä kirkkaudella, joka minulla sinun tykönäs oli ennenkuin tämä maailma olikaan."],[17,6,"Minä ilmoitin sinun nimes ihmisille, jotkas minulle maailmasta annoit: he olivat sinun, ja minulle sinä ne annoit, ja sinun sanas he kätkivät.","Minä ilmoitin sinun nimes ihmisille, jotkas minulle maailmasta annoit: he olivat sinun, ja minulle sinä ne annoit, ja sinun sanas he kätkivät."],[17,7,"He tiesivät nyt kaikki olevan sinusta, mitkä sinä minulle annoit.","He tiesivät nyt kaikki olevan sinusta, mitkä sinä minulle annoit."],[17,8,"Sillä ne sanat, jotka sinä minulle annoit, annoin minä heille; ja he ne ottivat vastaan, ja totisesti tunsivat minun sinusta lähteneen, ja uskoivat, että sinä minun lähetit.","Sillä ne sanat, jotka sinä minulle annoit, annoin minä heille; ja he ne ottivat vastaan, ja totisesti tunsivat minun sinusta lähteneen, ja uskoivat, että sinä minun lähetit."],[17,9,"Minä rukoilen heidän edestänsä: en minä maailman edestä rukoile, vaan niiden edestä, jotka sinä minulle annoit, että he ovat sinun omas.","Minä rukoilen heidän edestänsä: en minä maailman edestä rukoile, vaan niiden edestä, jotka sinä minulle annoit, että he ovat sinun omas."],[17,10,"Ja kaikki minun omani ovat sinun, ja sinun omas ovat minun: ja minä olen kirkastettu heissä.","Ja kaikki minun omani ovat sinun, ja sinun omas ovat minun: ja minä olen kirkastettu heissä."],[17,11,"En minä silleen ole maailmassa, mutta he ovat maailmassa, ja minä tulen sinun tykös. Pyhä Isä! kätke niitä, jotka sinä minulle annoit, sinun nimes tähden, että he olisivat yksi niinkuin mekin!","En minä silleen ole maailmassa, mutta he ovat maailmassa, ja minä tulen sinun tykös. Pyhä Isä! kätke niitä, jotka sinä minulle annoit, sinun nimes tähden, että he olisivat yksi niinkuin mekin!"],[17,12,"Kuin minä olin heidän kanssansa maailmassa, niin minä kätkin heitä sinun nimessäs: ne, jotkas minulle annoit, kätkin minä, ja ei niistä kenkään kadonnut, vaan se kadotuksen lapsi, että Raamattu täytettäisiin.","Kuin minä olin heidän kanssansa maailmassa, niin minä kätkin heitä sinun nimessäs: ne, jotkas minulle annoit, kätkin minä, ja ei niistä kenkään kadonnut, vaan se kadotuksen lapsi, että Raamattu täytettäisiin."],[17,13,"Mutta nyt minä tulen sinun tykös ja puhun näitä maailmassa, että heissä olis minun iloni täydellinen.","Mutta nyt minä tulen sinun tykös ja puhun näitä maailmassa, että heissä olis minun iloni täydellinen."],[17,14,"Minä annoin heille sinun sanas, ja maailma vihasi heitä; sillä ei he ole maailmasta, niinkuin en minäkään maailmasta ole.","Minä annoin heille sinun sanas, ja maailma vihasi heitä; sillä ei he ole maailmasta, niinkuin en minäkään maailmasta ole."],[17,15,"En minä rukoile, ettäs heitä ottaisit pois maailmasta, vaan ettäs heitä pahasta varjelisit.","En minä rukoile, ettäs heitä ottaisit pois maailmasta, vaan ettäs heitä pahasta varjelisit."],[17,16,"Ei he ole maailmasta, niinkuin en minäkään maailmasta ole.","Ei he ole maailmasta, niinkuin en minäkään maailmasta ole."],[17,17,"Pyhitä heitä totuudessas! Sinun puhees on totuus.","Pyhitä heitä totuudessas! Sinun puhees on totuus."],[17,18,"Niinkuin sinä minun lähetit maailmaan, niin minä myös lähetin heidät maailmaan,","Niinkuin sinä minun lähetit maailmaan, niin minä myös lähetin heidät maailmaan,"],[17,19,"Ja minä pyhitän itseni heidän tähtensä, että hekin olisivat totuudessa pyhitetyt.","Ja minä pyhitän itseni heidän tähtensä, että hekin olisivat totuudessa pyhitetyt."],[17,20,"Mutta en minä ainoasti heidän edestänsä rukoile, vaan myös niiden edestä, jotka heidän sanansa kautta uskovat minun päälleni:","Mutta en minä ainoasti heidän edestänsä rukoile, vaan myös niiden edestä, jotka heidän sanansa kautta uskovat minun päälleni:"],[17,21,"Että he kaikki yhtä olisivat, niinkuin sinä Isä minussa olet ja minä sinussa, että hekin meissä niin yhtä olisivat: että maailma uskois sinun minua lähettäneeksi.","Että he kaikki yhtä olisivat, niinkuin sinä Isä minussa olet ja minä sinussa, että hekin meissä niin yhtä olisivat: että maailma uskois sinun minua lähettäneeksi."],[17,22,"Ja minä annoin heille sen kunnian, jonka sinä minulle annoit, että he yhtä olisivat, niinkuin mekin yhtä olemme.","Ja minä annoin heille sen kunnian, jonka sinä minulle annoit, että he yhtä olisivat, niinkuin mekin yhtä olemme."],[17,23,"Minä olen heissä ja sinä minussa, että he niin yhdessä täydelliset olisivat, ja maailma tietäis, että sinä minun lähetit, ja että sinä heitä rakastit, niinkuin sinä minua rakastit.","Minä olen heissä ja sinä minussa, että he niin yhdessä täydelliset olisivat, ja maailma tietäis, että sinä minun lähetit, ja että sinä heitä rakastit, niinkuin sinä minua rakastit."],[17,24,"Isä, minä tahdon, että kussa minä olen, siellä nekin olisivat minun kanssani, jotka sinä minulle antanut olet: että he minun kunniani näkisivät, jonkas minulle annoit; sillä sinä rakastit minua ennenkuin maailman perustus laskettu oli.","Isä, minä tahdon, että kussa minä olen, siellä nekin olisivat minun kanssani, jotka sinä minulle antanut olet: että he minun kunniani näkisivät, jonkas minulle annoit; sillä sinä rakastit minua ennenkuin maailman perustus laskettu oli."],[17,25,"Vanhurskas Isä! ei maailma sinua tuntenut, mutta minä tunsin sinun, ja nämät ymmärsivät, että sinä minun lähetit.","Vanhurskas Isä! ei maailma sinua tuntenut, mutta minä tunsin sinun, ja nämät ymmärsivät, että sinä minun lähetit."],[17,26,"Ja minä julistin heille sinun nimes, ja vielä julistan: että se rakkaus, jolla sinä minua rakastit, heissä olis, ja minä myös heissä.","Ja minä julistin heille sinun nimes, ja vielä julistan: että se rakkaus, jolla sinä minua rakastit, heissä olis, ja minä myös heissä."],[18,1,"Kuin Jesus nämät oli sanonut, meni hän ulos opetuslastensa kanssa Kedronin ojan ylitse: siellä oli yrttitarha, johon hän meni sisälle ja hänen opetuslapsensa.","Kuin Jesus nämät oli sanonut, meni hän ulos opetuslastensa kanssa Kedronin ojan ylitse: siellä oli yrttitarha, johon hän meni sisälle ja hänen opetuslapsensa."],[18,2,"Mutta Juudas, joka hänen petti, tiesi myös sen paikan; sillä Jesus tuli sinne usein opetuslastensa kanssa.","Mutta Juudas, joka hänen petti, tiesi myös sen paikan; sillä Jesus tuli sinne usein opetuslastensa kanssa."],[18,3,"Kuin siis Juudas oli joukon kanssansa ottanut ja palveliat ylimmäisiltä papeilta ja Pharisealaisilta, tuli hän sinne lyhdyillä, tulisoitoilla ja sota-aseilla.","Kuin siis Juudas oli joukon kanssansa ottanut ja palveliat ylimmäisiltä papeilta ja Pharisealaisilta, tuli hän sinne lyhdyillä, tulisoitoilla ja sota-aseilla."],[18,4,"Kuin siis Jesus tiesi kaikki, mitä hänelle tapahtuman piti, niin hän läksi ja sanoi heille: ketä etsitte?","Kuin siis Jesus tiesi kaikki, mitä hänelle tapahtuman piti, niin hän läksi ja sanoi heille: ketä etsitte?"],[18,5,"He vastasivat häntä: Jesusta Natsaretilaista. Sanoi Jesus heille: minä olen! Mutta Juudas, jonka hänen petti, seisoi myös heidän kanssansa.","He vastasivat häntä: Jesusta Natsaretilaista. Sanoi Jesus heille: minä olen! Mutta Juudas, jonka hänen petti, seisoi myös heidän kanssansa."],[18,6,"Kuin siis Jesus sanoi heille: minä olen, astuivat he takaperin ja lankesivat maahan.","Kuin siis Jesus sanoi heille: minä olen, astuivat he takaperin ja lankesivat maahan."],[18,7,"Niin hän taas kysyi heiltä: ketä te etsitte? Mutta he sanoivat: Jesusta Natsarealaista.","Niin hän taas kysyi heiltä: ketä te etsitte? Mutta he sanoivat: Jesusta Natsarealaista."],[18,8,"Jesus vastasi: minä sanoin teille, että minä olen. Jos te siis minua etsitte, niin antakaat näiden mennä,","Jesus vastasi: minä sanoin teille, että minä olen. Jos te siis minua etsitte, niin antakaat näiden mennä,"],[18,9,"Että se puhe täytettäisiin, jonka hän oli sanonut: en minä niistä yhtään kadottanut, jotka sinä minulle annoit.","Että se puhe täytettäisiin, jonka hän oli sanonut: en minä niistä yhtään kadottanut, jotka sinä minulle annoit."],[18,10,"Niin Simon Pietarilla oli miekka, jonka hän veti ulos, ja löi ylimmäisen papin palveliaa ja hakkasi pois hänen oikian korvansa; jonka palvelian nimi oli Malkus.","Niin Simon Pietarilla oli miekka, jonka hän veti ulos, ja löi ylimmäisen papin palveliaa ja hakkasi pois hänen oikian korvansa; jonka palvelian nimi oli Malkus."],[18,11,"Niin Jesus sanoi Pietarille: pistä miekkas tuppeen: eikö minun pidä juoman sitä kalkkia, jonka Isä minulle antoi?","Niin Jesus sanoi Pietarille: pistä miekkas tuppeen: eikö minun pidä juoman sitä kalkkia, jonka Isä minulle antoi?"],[18,12,"Niin joukko ja ylimmäinen päämies ja Juudalaisten palveliat ottivat kiinni Jesuksen ja sitoivat hänen,","Niin joukko ja ylimmäinen päämies ja Juudalaisten palveliat ottivat kiinni Jesuksen ja sitoivat hänen,"],[18,13,"Ja veivät ensin Hannaksen tykö, sillä hän oli Kaiphaan appi, joka oli sinä vuonna ylimmäinen pappi.","Ja veivät ensin Hannaksen tykö, sillä hän oli Kaiphaan appi, joka oli sinä vuonna ylimmäinen pappi."],[18,14,"Ja Kaiphas oli se, joka Juudalaisille oli neuvon antanut, että yhtä ihmistä olis tarpeellinen kuolettaa kansan edestä.","Ja Kaiphas oli se, joka Juudalaisille oli neuvon antanut, että yhtä ihmistä olis tarpeellinen kuolettaa kansan edestä."],[18,15,"Ja Simon Pietari seurasi Jesusta, ja toinen opetuslapsi. Mutta se opetuslapsi oli ylimmäisen papin tuttava ja meni sisälle Jesuksen kanssa ylimmäisen papin saliin.","Ja Simon Pietari seurasi Jesusta, ja toinen opetuslapsi. Mutta se opetuslapsi oli ylimmäisen papin tuttava ja meni sisälle Jesuksen kanssa ylimmäisen papin saliin."],[18,16,"Mutta Pietari jäi ulos oven eteen. Niin toinen opetuslapsi, joka ylimmäisen papin tuttava oli, meni ulos ja puhui ovenvartialle, ja toi Pietarin sisälle.","Mutta Pietari jäi ulos oven eteen. Niin toinen opetuslapsi, joka ylimmäisen papin tuttava oli, meni ulos ja puhui ovenvartialle, ja toi Pietarin sisälle."],[18,17,"Niin sanoi ovenvartiapiika Pietarille: etkö sinäkin olen tämän miehen opetuslapsia? Hän sanoi: en ole.","Niin sanoi ovenvartiapiika Pietarille: etkö sinäkin olen tämän miehen opetuslapsia? Hän sanoi: en ole."],[18,18,"Mutta palveliat, jotka hiilistä olivat tulen tehneet, sillä kylmä oli, seisoivat ja lämmittelivät. Ja Pietari seisoi myös heidän kanssansa ja lämmitteli.","Mutta palveliat, jotka hiilistä olivat tulen tehneet, sillä kylmä oli, seisoivat ja lämmittelivät. Ja Pietari seisoi myös heidän kanssansa ja lämmitteli."],[18,19,"Niin ylimmäinen pappi kysyi Jesukselta hänen opetuslapsestansa ja opetuksestansa.","Niin ylimmäinen pappi kysyi Jesukselta hänen opetuslapsestansa ja opetuksestansa."],[18,20,"Jesus vastasi häntä: minä olen maailman edessä julkisesti puhunut: minä olen synagogassa opettanut ja templissä, johonka Juudalaiset joka paikasta kokoon tulevat, ja en ole mitään salaisuudessa puhunut.","Jesus vastasi häntä: minä olen maailman edessä julkisesti puhunut: minä olen synagogassa opettanut ja templissä, johonka Juudalaiset joka paikasta kokoon tulevat, ja en ole mitään salaisuudessa puhunut."],[18,21,"Mitäs minulta kysyt? Kysy niiltä, jotka kuulivat, mitä minä heille puhunut olen. Katso, ne tietävät, mitä minä sanonut olen.","Mitäs minulta kysyt? Kysy niiltä, jotka kuulivat, mitä minä heille puhunut olen. Katso, ne tietävät, mitä minä sanonut olen."],[18,22,"Mutta kuin hän näitä puhui, antoi yksi niistä palvelioita, jotka läsnä seisoivat, Jesukselle korvapuustin ja sanoi: niinkö sinä vastaat ylimmäistä pappia!","Mutta kuin hän näitä puhui, antoi yksi niistä palvelioita, jotka läsnä seisoivat, Jesukselle korvapuustin ja sanoi: niinkö sinä vastaat ylimmäistä pappia!"],[18,23,"Jesus vastasi häntä: jos minä pahasti puhuin, niin tunnusta se pahaksi, mutta jos minä oikein puhuin, miksis minua lyöt?","Jesus vastasi häntä: jos minä pahasti puhuin, niin tunnusta se pahaksi, mutta jos minä oikein puhuin, miksis minua lyöt?"],[18,24,"Niin Hannas lähetti hänen sidottuna ylimmäisen papin Kaiphaan tykö.","Niin Hannas lähetti hänen sidottuna ylimmäisen papin Kaiphaan tykö."],[18,25,"Mutta Simon Pietari seisoi ja lämmitteli. Niin he sanoivat hänelle: etkö sinä ole myös hänen opetuslapsiansa? Hän kielsi ja sanoi: en ole.","Mutta Simon Pietari seisoi ja lämmitteli. Niin he sanoivat hänelle: etkö sinä ole myös hänen opetuslapsiansa? Hän kielsi ja sanoi: en ole."],[18,26,"Sanoi hänelle yksi ylimmäisen papin palvelioista, sen lanko, jonka korvan Pietari hakkasi pois: enkö minä sinua nähnyt yrttitarhassa hänen kanssansa?","Sanoi hänelle yksi ylimmäisen papin palvelioista, sen lanko, jonka korvan Pietari hakkasi pois: enkö minä sinua nähnyt yrttitarhassa hänen kanssansa?"],[18,27,"Niin Pietari taas kielsi, ja kohta kukko lauloi.","Niin Pietari taas kielsi, ja kohta kukko lauloi."],[18,28,"Niin he veivät Jesuksen Kaiphaan tyköä raastupaan. Mutta se oli aamu, ja ei he menneet raastupaan, ettei he itsiänsä saastuttaisi, vaan söisivät pääsiäislampaan.","Niin he veivät Jesuksen Kaiphaan tyköä raastupaan. Mutta se oli aamu, ja ei he menneet raastupaan, ettei he itsiänsä saastuttaisi, vaan söisivät pääsiäislampaan."],[18,29,"Niin Pilatus meni ulos heidän tykönsä ja sanoi: mitä kannetta te tuotte tätä miestä vastaan?","Niin Pilatus meni ulos heidän tykönsä ja sanoi: mitä kannetta te tuotte tätä miestä vastaan?"],[18,30,"He vastasivat ja sanoivat hänelle: ellei hän pahantekiä olisi, emme olisi häntä sinun haltuus antaneet.","He vastasivat ja sanoivat hänelle: ellei hän pahantekiä olisi, emme olisi häntä sinun haltuus antaneet."],[18,31,"Niin Pilatus sanoi heille: ottakaat te häntä ja tuomitkaat häntä teidän lakinne jälkeen. Juudalaiset sanoivat siis hänelle: meidän ei sovi ketään tappaa;","Niin Pilatus sanoi heille: ottakaat te häntä ja tuomitkaat häntä teidän lakinne jälkeen. Juudalaiset sanoivat siis hänelle: meidän ei sovi ketään tappaa;"],[18,32,"Että jesuksen puhe täytettäisiin, kuin hän sanoi, merkiten, millä kuolemalla hänen piti kuoleman.","Että jesuksen puhe täytettäisiin, kuin hän sanoi, merkiten, millä kuolemalla hänen piti kuoleman."],[18,33,"Niin Pilatus taas meni raastupaan, kutsui Jesuksen ja sanoi hänelle: oletkos sinä Juudalaisten kuningas?","Niin Pilatus taas meni raastupaan, kutsui Jesuksen ja sanoi hänelle: oletkos sinä Juudalaisten kuningas?"],[18,34,"Jesus vastasi häntä: sanotko sinä sen itsestäs, eli ovatko muut sen minusta sinulle sanoneet?","Jesus vastasi häntä: sanotko sinä sen itsestäs, eli ovatko muut sen minusta sinulle sanoneet?"],[18,35,"Pilatus vastasi: olenko minä Juudalainen? Sinun kansas ja ylimmäiset papit antoivat ylön sinun minulle: mitäs tehnyt olet?","Pilatus vastasi: olenko minä Juudalainen? Sinun kansas ja ylimmäiset papit antoivat ylön sinun minulle: mitäs tehnyt olet?"],[18,36,"Jesus vastasi: ei minun valtakuntani ole tästä maailmasta. Jos minun valtakuntani olis tästä maailmasta, niin tosin minun palveliani olisivat sotineet, etten minä olisi tullut annetuksi ylön Juudalaisille; mutta ei minun valtakuntakuntani ole täältä.","Jesus vastasi: ei minun valtakuntani ole tästä maailmasta. Jos minun valtakuntani olis tästä maailmasta, niin tosin minun palveliani olisivat sotineet, etten minä olisi tullut annetuksi ylön Juudalaisille; mutta ei minun valtakuntakuntani ole täältä."],[18,37,"Niin Pilatus sanoi hänelle: niin sinä olet kuningas? Jesus vastasi: sinä sen sanot, että minä olen kuningas. Sitä varten olen minä syntynyt ja sitä varten maailmaan tullut, että minä totuden tunnustan. Jokainen, joka on totuudesta, se kuulee minun ääneni.","Niin Pilatus sanoi hänelle: niin sinä olet kuningas? Jesus vastasi: sinä sen sanot, että minä olen kuningas. Sitä varten olen minä syntynyt ja sitä varten maailmaan tullut, että minä totuden tunnustan. Jokainen, joka on totuudesta, se kuulee minun ääneni."],[18,38,"Pilatus sanoi hänelle: minä on totuus? Ja kuin hän sen sanonut oli, meni hän taas ulos Juudalaisten tykö ja sanoi heille: en minä löydä yhtään syytä hänessä.","Pilatus sanoi hänelle: minä on totuus? Ja kuin hän sen sanonut oli, meni hän taas ulos Juudalaisten tykö ja sanoi heille: en minä löydä yhtään syytä hänessä."],[18,39,"Mutta teillä on tapa, että minun pitää teille päästämän yhden pääsiäisenä: tahdotteko siis, että minä päästän teille Juudalaisten kuninkaan?","Mutta teillä on tapa, että minun pitää teille päästämän yhden pääsiäisenä: tahdotteko siis, että minä päästän teille Juudalaisten kuninkaan?"],[18,40,"Niin he huusivat taas kaikki, sanoen: ei tätä, vaan Barabbasta. Mutta Barabbas oli ryöväri.","Niin he huusivat taas kaikki, sanoen: ei tätä, vaan Barabbasta. Mutta Barabbas oli ryöväri."],[19,1,"Niin Pilatus otti silloin Jesuksen ja ruoskitsi hänen,","Niin Pilatus otti silloin Jesuksen ja ruoskitsi hänen,"],[19,2,"Ja sotamiehet väänsivät kruunun orjantappuroista, panivat sen hänen päähänsä ja puettivat hänen purpuravaatteesen,","Ja sotamiehet väänsivät kruunun orjantappuroista, panivat sen hänen päähänsä ja puettivat hänen purpuravaatteesen,"],[19,3,"Ja sanoivat: terve, Juudalaisten kuningas! ja antoivat hänelle korvapuusteja.","Ja sanoivat: terve, Juudalaisten kuningas! ja antoivat hänelle korvapuusteja."],[19,4,"Taas tuli Pilatus ulos ja sanoi heille: katsokaat, minä tuon hänen teille ulos, että te tietäisitte, etten minä löydä yhtään syytä hänessä.","Taas tuli Pilatus ulos ja sanoi heille: katsokaat, minä tuon hänen teille ulos, että te tietäisitte, etten minä löydä yhtään syytä hänessä."],[19,5,"Niin Jesus meni ulos, kantain orjantappuraista kruunua ja purpuraista vaatetta. Ja hän sanoi heille: katso ihmistä!","Niin Jesus meni ulos, kantain orjantappuraista kruunua ja purpuraista vaatetta. Ja hän sanoi heille: katso ihmistä!"],[19,6,"Mutta kuin ylimmäiset papit ja palveliat hänen näkivät, huusivat he, sanoen: ristiinnaulitse, ristiinnaulitse häntä! Pilatus sanoi heille: ottakaat te häntä ja ristiinnaulitkaat; sillä en minä löydä yhtään syytä hänessä.","Mutta kuin ylimmäiset papit ja palveliat hänen näkivät, huusivat he, sanoen: ristiinnaulitse, ristiinnaulitse häntä! Pilatus sanoi heille: ottakaat te häntä ja ristiinnaulitkaat; sillä en minä löydä yhtään syytä hänessä."],[19,7,"Vastasivat häntä Juudalaiset: meillä on laki, ja meidän lakimme jälkeen pitää hänen kuoleman, että hän teki itsensä Jumalan Pojaksi.","Vastasivat häntä Juudalaiset: meillä on laki, ja meidän lakimme jälkeen pitää hänen kuoleman, että hän teki itsensä Jumalan Pojaksi."],[19,8,"Kun siis Pilatus tämän puheen kuuli, pelkäsi hän vielä enemmin","Kun siis Pilatus tämän puheen kuuli, pelkäsi hän vielä enemmin"],[19,9,"Ja meni taas raastupaan ja sanoi Jesukselle: kusta sinä olet? Mutta ei Jesus vastannut häntä.","Ja meni taas raastupaan ja sanoi Jesukselle: kusta sinä olet? Mutta ei Jesus vastannut häntä."],[19,10,"Niin Pilatus sanoi hänelle: etkös mitään minulle puhu? Etkös tiedä, että minulla on valta sinua ristiinnaulita ja valta sinua päästää?","Niin Pilatus sanoi hänelle: etkös mitään minulle puhu? Etkös tiedä, että minulla on valta sinua ristiinnaulita ja valta sinua päästää?"],[19,11,"Jesus vastasi: ei sinulla olisi yhtään valtaa minua vastaan, jos ei se olisi sinulle annettu ylhäältä: sentähden on hänellä suurempi synti, joka minun sinulle antoi ylön.","Jesus vastasi: ei sinulla olisi yhtään valtaa minua vastaan, jos ei se olisi sinulle annettu ylhäältä: sentähden on hänellä suurempi synti, joka minun sinulle antoi ylön."],[19,12,"Ja siitä ajasta pyysi Pilatus häntä päästää. Mutta Juudalaiset huusivat, sanoen: jos sinä hänen päästät, niin et sinä ole keisarin ystävä; sillä jokainen, joka itsensä tekee kuninkaaksi, hän on keisaria vastaan.","Ja siitä ajasta pyysi Pilatus häntä päästää. Mutta Juudalaiset huusivat, sanoen: jos sinä hänen päästät, niin et sinä ole keisarin ystävä; sillä jokainen, joka itsensä tekee kuninkaaksi, hän on keisaria vastaan."],[19,13,"Kuin Pilatus tämän puheen kuuli, vei hän Jesuksen ulos ja istui tuomio-istuimelle, siihen paikkaan, joka kutsutaan Litostroton, mutta Hebreaksi Gabbata.","Kuin Pilatus tämän puheen kuuli, vei hän Jesuksen ulos ja istui tuomio-istuimelle, siihen paikkaan, joka kutsutaan Litostroton, mutta Hebreaksi Gabbata."],[19,14,"Mutta se oli pääsiäisen valmistuspäivä, lähes kuudennella hetkellä. Ja hän sanoi Juudalaisille: katso, teidän kuninkaanne.","Mutta se oli pääsiäisen valmistuspäivä, lähes kuudennella hetkellä. Ja hän sanoi Juudalaisille: katso, teidän kuninkaanne."],[19,15,"Mutta he huusivat: ota pois, ota pois, ristiinnaulitse häntä! Pilatus sanoi heille: pitääkö minun ristiinnaulitseman teidän kuninkaanne? Ylimmäiset papit vastasivat: ei meillä ole kuningasta, vaan keisari.","Mutta he huusivat: ota pois, ota pois, ristiinnaulitse häntä! Pilatus sanoi heille: pitääkö minun ristiinnaulitseman teidän kuninkaanne? Ylimmäiset papit vastasivat: ei meillä ole kuningasta, vaan keisari."],[19,16,"Niin silloin hän antoi hänen heille ristiinnaulittaa. Mutta he ottivat Jesuksen ja veivät pois.","Niin silloin hän antoi hänen heille ristiinnaulittaa. Mutta he ottivat Jesuksen ja veivät pois."],[19,17,"Ja hän kantoi ristiänsä ja meni siihen paikkaan, joka kutsutaan Pääkallon paikaksi, mutta Hebreaksi Golgata.","Ja hän kantoi ristiänsä ja meni siihen paikkaan, joka kutsutaan Pääkallon paikaksi, mutta Hebreaksi Golgata."],[19,18,"Siellä he ristiinnaulitsivat hänen ja kaksi muuta hänen kanssansa kahden puolen, mutta Jesuksen keskelle.","Siellä he ristiinnaulitsivat hänen ja kaksi muuta hänen kanssansa kahden puolen, mutta Jesuksen keskelle."],[19,19,"Niin Pilatus kirjoitti myös päällekirjoituksen ja pani ristin päälle, ja oli näin kirjoitettu: JESUS NATSARENUS JUUDALAISTEN KUNINGAS.","Niin Pilatus kirjoitti myös päällekirjoituksen ja pani ristin päälle, ja oli näin kirjoitettu: JESUS NATSARENUS JUUDALAISTEN KUNINGAS."],[19,20,"Tämän päällekirjoituksen luki monta Juudalaisista; sillä se paikka oli läsnä kaupunkia, jossa Jesus ristiinnaulittiin. Ja oli kirjoitettu Hebreaksi, Grekaksi ja Latinaksi.","Tämän päällekirjoituksen luki monta Juudalaisista; sillä se paikka oli läsnä kaupunkia, jossa Jesus ristiinnaulittiin. Ja oli kirjoitettu Hebreaksi, Grekaksi ja Latinaksi."],[19,21,"Niin sanoivat Juudalaisten ylimmäiset papit Pilatukselle: älä kirjoita: Juudalaisten kuningas; vaan että hän on sanonut: minä olen Juudalaisten kuningas.","Niin sanoivat Juudalaisten ylimmäiset papit Pilatukselle: älä kirjoita: Juudalaisten kuningas; vaan että hän on sanonut: minä olen Juudalaisten kuningas."],[19,22,"Pilatus vastasi: mitä minä kirjoitin, sen minä kirjoitin.","Pilatus vastasi: mitä minä kirjoitin, sen minä kirjoitin."],[19,23,"Kuin siis sotamiehet olivat Jesuksen ristiinnaulinneet, ottivat he hänen vaatteensa (ja tekivät neljä osaa, kullekin sotamiehelle osan), ja hameen; mutta hame ei ollut ommeltu, vaan kokonansa ylhäältä (alaspäin) kudottu.","Kuin siis sotamiehet olivat Jesuksen ristiinnaulinneet, ottivat he hänen vaatteensa (ja tekivät neljä osaa, kullekin sotamiehelle osan), ja hameen; mutta hame ei ollut ommeltu, vaan kokonansa ylhäältä (alaspäin) kudottu."],[19,24,"Niin he sanoivat keskenänsä: älkäämme tätä rikkoko, vaan heittäkäämme tästä arpaa, kenenkä se pitää oleman: että Raamattu täytettäisiin, joka sanoo: he ovat minun vaatteeni itsellensä jakaneet ja ovat heittäneet minun hameestani arpaa. Ja sotamiehet tosin näin tekivät.","Niin he sanoivat keskenänsä: älkäämme tätä rikkoko, vaan heittäkäämme tästä arpaa, kenenkä se pitää oleman: että Raamattu täytettäisiin, joka sanoo: he ovat minun vaatteeni itsellensä jakaneet ja ovat heittäneet minun hameestani arpaa. Ja sotamiehet tosin näin tekivät."],[19,25,"Mutta Jesuksen ristin tykönä seisoi hänen äitinsä ja hänen äitinsä sisar Maria, Kleopaan emäntä, ja Maria Magdalena.","Mutta Jesuksen ristin tykönä seisoi hänen äitinsä ja hänen äitinsä sisar Maria, Kleopaan emäntä, ja Maria Magdalena."],[19,26,"Kuin siis Jesus näki äidin ja opetuslapsen siinä seisovan, jota hän rakasti, sanoi hän äidillensä: vaimo, katso sinun poikaas.","Kuin siis Jesus näki äidin ja opetuslapsen siinä seisovan, jota hän rakasti, sanoi hän äidillensä: vaimo, katso sinun poikaas."],[19,27,"Sitte sanoi hän opetuslapselle: katso sinun äitiäs. Ja siitä hetkestä otti opetuslapsi hänen tykönsä.","Sitte sanoi hän opetuslapselle: katso sinun äitiäs. Ja siitä hetkestä otti opetuslapsi hänen tykönsä."],[19,28,"Sitte, kuin Jesus tiesi jo kaikki täytetyksi, ja että Raamattu täytettäisiin, sanoi hän: minä janoon.","Sitte, kuin Jesus tiesi jo kaikki täytetyksi, ja että Raamattu täytettäisiin, sanoi hän: minä janoon."],[19,29,"Oli siis yksi astia pantu etikkaa täyteen, ja he täyttivät sienen etikalla ja panivat sen ympärille isoppia, ja panivat sen hänen suunsa eteen.","Oli siis yksi astia pantu etikkaa täyteen, ja he täyttivät sienen etikalla ja panivat sen ympärille isoppia, ja panivat sen hänen suunsa eteen."],[19,30,"Kuin siis Jesus oli etikkaa ottanut, sanoi hän: se on täytetty! ja kallisti päänsä ja antoi henkensä.","Kuin siis Jesus oli etikkaa ottanut, sanoi hän: se on täytetty! ja kallisti päänsä ja antoi henkensä."],[19,31,"Mutta että valmistuspäivä oli, ja ei ruumiit pitänyt ristissä oleman sabbatina, (sillä se sabbatin päivä oli suuri,) rukoilivat siis Juudalaiset Pilatusta, että heidän sääriluunsa piti rikottaman ja he otettaman alas.","Mutta että valmistuspäivä oli, ja ei ruumiit pitänyt ristissä oleman sabbatina, (sillä se sabbatin päivä oli suuri,) rukoilivat siis Juudalaiset Pilatusta, että heidän sääriluunsa piti rikottaman ja he otettaman alas."],[19,32,"Niin sotamiehet tulivat ja rikkoivat ensimmäisen luut ja toisen, joka hänen kanssansa oli ristiinnaulittu;","Niin sotamiehet tulivat ja rikkoivat ensimmäisen luut ja toisen, joka hänen kanssansa oli ristiinnaulittu;"],[19,33,"Mutta kuin he tulivat Jesuksen tykö ja näkivät hänen jo kuolleeksi, niin ei he rikkoneet hänen luitansa;","Mutta kuin he tulivat Jesuksen tykö ja näkivät hänen jo kuolleeksi, niin ei he rikkoneet hänen luitansa;"],[19,34,"Vaan yksi sotamiehistä avasi hänen kylkensä keihäällä, josta kohta vuoti veri ja vesi.","Vaan yksi sotamiehistä avasi hänen kylkensä keihäällä, josta kohta vuoti veri ja vesi."],[19,35,"Ja joka tämän näki, hän on sen todistanut ja hänen todistuksensa on tosi, ja hän tietää totta sanovansa, että te myös uskoisitte.","Ja joka tämän näki, hän on sen todistanut ja hänen todistuksensa on tosi, ja hän tietää totta sanovansa, että te myös uskoisitte."],[19,36,"Sillä nämät ovat tapahtuneet, että Raamattu täytettäisiin: ei teidän pidä luuta rikkoman hänessä.","Sillä nämät ovat tapahtuneet, että Raamattu täytettäisiin: ei teidän pidä luuta rikkoman hänessä."],[19,37,"Ja taas toinen kirjoitus sanoo: he saavat nähdä, ketä he ovat pistäneet.","Ja taas toinen kirjoitus sanoo: he saavat nähdä, ketä he ovat pistäneet."],[19,38,"Mutta sen jälkeen rukoili Pilatusta Joseph Arimatiasta, (joka oli Jesuksen opetuslapsi, vaan salaa Juudalaisten pelvon tähden), että hän olis saanut ottaa Jesuksen ruumiin; ja Pilatus salli sen. Niin hän tuli ja otti Jesuksen ruumiin.","Mutta sen jälkeen rukoili Pilatusta Joseph Arimatiasta, (joka oli Jesuksen opetuslapsi, vaan salaa Juudalaisten pelvon tähden), että hän olis saanut ottaa Jesuksen ruumiin; ja Pilatus salli sen. Niin hän tuli ja otti Jesuksen ruumiin."],[19,39,"Niin tuli myös Nikodemus, (joka oli ensin yöllä Jesuksen tykö tullut,) ja toi mirhamia ja aloeta sekoitettua, lähes sata naulaa,","Niin tuli myös Nikodemus, (joka oli ensin yöllä Jesuksen tykö tullut,) ja toi mirhamia ja aloeta sekoitettua, lähes sata naulaa,"],[19,40,"Niin he ottivat Jesuksen ruumiin ja käärivät sen liinaiseen, hyvän-hajullisten yrttein kanssa, niinkuin Juudalaisten tapa on haudata.","Niin he ottivat Jesuksen ruumiin ja käärivät sen liinaiseen, hyvän-hajullisten yrttein kanssa, niinkuin Juudalaisten tapa on haudata."],[19,41,"Mutta siinä paikassa, jossa hän ristiinnaulittiin, oli yrttitarha, ja yrttitarhassa uusi hauta, johonka ei vielä kenkään ollut pantu:","Mutta siinä paikassa, jossa hän ristiinnaulittiin, oli yrttitarha, ja yrttitarhassa uusi hauta, johonka ei vielä kenkään ollut pantu:"],[19,42,"Siihen he panivat Jesuksen Juudalaisten valmistuspäivän tähden, että se hauta oli läsnä.","Siihen he panivat Jesuksen Juudalaisten valmistuspäivän tähden, että se hauta oli läsnä."],[20,1,"Mutta ensimmäisenä päivänä viikossa tuli Maria Magdalena varhain, kuin vielä pimiä oli, haudalle ja näki kiven otetuksi pois haudalta.","Mutta ensimmäisenä päivänä viikossa tuli Maria Magdalena varhain, kuin vielä pimiä oli, haudalle ja näki kiven otetuksi pois haudalta."],[20,2,"Niin hän juoksi ja tuli Simon Pietarin tykö ja sen opetuslapsen tykö, jota Jesus rakasti, ja sanoi heille: he ovat Herran ottaneet pois haudasta, ja emme tiedä, kuhunka he hänen panivat.","Niin hän juoksi ja tuli Simon Pietarin tykö ja sen opetuslapsen tykö, jota Jesus rakasti, ja sanoi heille: he ovat Herran ottaneet pois haudasta, ja emme tiedä, kuhunka he hänen panivat."],[20,3,"Niin Pietari meni ulos ja toinen opetuslapsi, ja tulivat haudalle.","Niin Pietari meni ulos ja toinen opetuslapsi, ja tulivat haudalle."],[20,4,"Mutta he juoksivat kahden ynnä, ja toinen opetuslapsi juoksi edellä nopeammin kuin Pietari, ja tuli ensin haudalle.","Mutta he juoksivat kahden ynnä, ja toinen opetuslapsi juoksi edellä nopeammin kuin Pietari, ja tuli ensin haudalle."],[20,5,"Ja kuin hän itsensä kumarsi, näki hän liinaiset pantuna, mutta ei hän kuitenkaan mennyt sisälle.","Ja kuin hän itsensä kumarsi, näki hän liinaiset pantuna, mutta ei hän kuitenkaan mennyt sisälle."],[20,6,"Niin Simon Pietari tuli seuraten häntä, ja meni hautaan, ja näki kääriliinat pantuna.","Niin Simon Pietari tuli seuraten häntä, ja meni hautaan, ja näki kääriliinat pantuna."],[20,7,"Ja hikiliinan, joka hänen päänsä päällä oli ollut, ei kääriliinan kanssa, vaan erinänsä käärittynä yhteen paikkaan.","Ja hikiliinan, joka hänen päänsä päällä oli ollut, ei kääriliinan kanssa, vaan erinänsä käärittynä yhteen paikkaan."],[20,8,"Niin meni myös toinen opetuslapsi sisälle, joka ensin haudalle tullut oli, ja näki sen ja uskoi.","Niin meni myös toinen opetuslapsi sisälle, joka ensin haudalle tullut oli, ja näki sen ja uskoi."],[20,9,"Sillä ei he vielä Raamattua ymmärtäneet, että hän oli nouseva kuolleista.","Sillä ei he vielä Raamattua ymmärtäneet, että hän oli nouseva kuolleista."],[20,10,"Niin ne opetuslapset menivät taas yhteen.","Niin ne opetuslapset menivät taas yhteen."],[20,11,"Mutta Maria seisoi ulkona haudan edessä ja itki. Ja kuin hän niin itki, kumarsi hän itsensä hautaan.","Mutta Maria seisoi ulkona haudan edessä ja itki. Ja kuin hän niin itki, kumarsi hän itsensä hautaan."],[20,12,"Ja näki kaksi enkeliä valkeissa vaatteissa istuvan, yhden pään puolessa ja toisen jalkain puolessa, siinä missä Jesuksen ruumis pantu oli.","Ja näki kaksi enkeliä valkeissa vaatteissa istuvan, yhden pään puolessa ja toisen jalkain puolessa, siinä missä Jesuksen ruumis pantu oli."],[20,13,"Ne sanoivat hänelle: vaimo, mitäs itket? Hän sanoi heille: he ovat minun Herrani ottaneet pois, ja en tiedä, kuhunka he hänen ovat panneet.","Ne sanoivat hänelle: vaimo, mitäs itket? Hän sanoi heille: he ovat minun Herrani ottaneet pois, ja en tiedä, kuhunka he hänen ovat panneet."],[20,14,"Ja kuin hän nämät sanonut oli, käänsi hän itsensä taapäin, ja näki Jesuksen seisovan, eikä tietänyt, että se oli Jesus.","Ja kuin hän nämät sanonut oli, käänsi hän itsensä taapäin, ja näki Jesuksen seisovan, eikä tietänyt, että se oli Jesus."],[20,15,"Sanoi Jesus hänelle: vaimo, mitäs itket? ketäs etsit? Mutta hän luuli sen yrttitarhan haltiaksi, ja sanoi hänelle: Herra, jos sinä hänen kannoit pois, niin sano minulle, kuhunkas hänen panit, ja minä tahdon hänen ottaa.","Sanoi Jesus hänelle: vaimo, mitäs itket? ketäs etsit? Mutta hän luuli sen yrttitarhan haltiaksi, ja sanoi hänelle: Herra, jos sinä hänen kannoit pois, niin sano minulle, kuhunkas hänen panit, ja minä tahdon hänen ottaa."],[20,16,"Jesus sanoi hänelle: Maria! niin hän käänsi itsensä ja sanoi hänelle: Rabboni, se on: Mestari.","Jesus sanoi hänelle: Maria! niin hän käänsi itsensä ja sanoi hänelle: Rabboni, se on: Mestari."],[20,17,"Jesus sanoi hänelle: älä minuun rupee; sillä en minä ole vielä mennyt ylös minun Isäni tykö, vaan mene minun veljeini tykö ja sano heille: minä menen ylös minun Isäni tykö ja teidän Isänne tykö, ja minun Jumalani tykö ja teidän Jumalanne tykö.","Jesus sanoi hänelle: älä minuun rupee; sillä en minä ole vielä mennyt ylös minun Isäni tykö, vaan mene minun veljeini tykö ja sano heille: minä menen ylös minun Isäni tykö ja teidän Isänne tykö, ja minun Jumalani tykö ja teidän Jumalanne tykö."],[20,18,"Maria Magdalena tuli ja ilmoitti opetuslapsille, että hän oli nähnyt Herran, ja että hän näitä hänelle sanoi.","Maria Magdalena tuli ja ilmoitti opetuslapsille, että hän oli nähnyt Herran, ja että hän näitä hänelle sanoi."],[20,19,"Kuin siis sen sabbatin päivän ehtoo oli, ja ovet olivat suljetut, jossa opetuslapset kokoontuneet olivat Juudalaisten pelvon tähden, tuli Jesus ja seisoi heidän keskellänsä ja sanoi heille: rauha olkoon teille!","Kuin siis sen sabbatin päivän ehtoo oli, ja ovet olivat suljetut, jossa opetuslapset kokoontuneet olivat Juudalaisten pelvon tähden, tuli Jesus ja seisoi heidän keskellänsä ja sanoi heille: rauha olkoon teille!"],[20,20,"Ja kuin hän sen sanonut oli, osoitti hän heille kätensä ja kylkensä. Niin opetuslapset ihastuivat, että he näkivät Herran.","Ja kuin hän sen sanonut oli, osoitti hän heille kätensä ja kylkensä. Niin opetuslapset ihastuivat, että he näkivät Herran."],[20,21,"Ja Jesus taas sanoi heille: rauha olkoon teille! niinkuin Isä minun lähetti, niin minä myös lähetän teidät.","Ja Jesus taas sanoi heille: rauha olkoon teille! niinkuin Isä minun lähetti, niin minä myös lähetän teidät."],[20,22,"Ja kuin hän nämät sanonut oli, puhalsi hän heidän päällensä ja sanoi heille: ottakaat Pyhä Henki:","Ja kuin hän nämät sanonut oli, puhalsi hän heidän päällensä ja sanoi heille: ottakaat Pyhä Henki:"],[20,23,"Joille te synnit anteeksi annatte, niille ne anteeksi annetaan, ja joille te ne pidätte, niille ne ovat pidetyt.","Joille te synnit anteeksi annatte, niille ne anteeksi annetaan, ja joille te ne pidätte, niille ne ovat pidetyt."],[20,24,"Mutta Toomas, yksi kahdestatoistakymmenestä, joka kaksoiseksi kutsutaan, ei ollut heidän kanssansa, kuin Jesus tuli.","Mutta Toomas, yksi kahdestatoistakymmenestä, joka kaksoiseksi kutsutaan, ei ollut heidän kanssansa, kuin Jesus tuli."],[20,25,"Niin muut opetuslapset sanoivat hänelle: me näimme Herran. Mutta hän sanoi heille: ellen minä näe hänen käsissänsä naulan reikää, ja pistä sormeani naulain siaan, ja pistä kättäni hänen kylkeensä, en minä usko.","Niin muut opetuslapset sanoivat hänelle: me näimme Herran. Mutta hän sanoi heille: ellen minä näe hänen käsissänsä naulan reikää, ja pistä sormeani naulain siaan, ja pistä kättäni hänen kylkeensä, en minä usko."],[20,26,"Ja kahdeksan päivän perästä olivat opetuslapset taas sisällä, ja Toomas heidän kanssansa. Niin Jesus tuli, kuin ovet suljetut olivat, ja seisoi heidän keskellänsä, ja sanoi: rauha olkoon teille!","Ja kahdeksan päivän perästä olivat opetuslapset taas sisällä, ja Toomas heidän kanssansa. Niin Jesus tuli, kuin ovet suljetut olivat, ja seisoi heidän keskellänsä, ja sanoi: rauha olkoon teille!"],[20,27,"Sitte sanoi hän Toomaalle: pistä sormes tänne, ja katso minun käsiäni, ja ojenna tänne kätes, ja pistä minun kylkeeni, ja älä ole epäuskoinen, vaan uskovainen.","Sitte sanoi hän Toomaalle: pistä sormes tänne, ja katso minun käsiäni, ja ojenna tänne kätes, ja pistä minun kylkeeni, ja älä ole epäuskoinen, vaan uskovainen."],[20,28,"Toomas vastasi ja sanoi hänelle: minun Herrani ja minun Jumalani!","Toomas vastasi ja sanoi hänelle: minun Herrani ja minun Jumalani!"],[20,29,"Jesus sanoi hänelle: ettäs näit minun, Toomas, niin sinä uskoit: autuaat ovat ne, jotka ei näe, ja kuitenkin uskovat.","Jesus sanoi hänelle: ettäs näit minun, Toomas, niin sinä uskoit: autuaat ovat ne, jotka ei näe, ja kuitenkin uskovat."],[20,30,"Niin teki myös Jesus monta muuta merkkiä opetuslastensa nähden, jotka ei tässä kirjassa ole kirjoitetut.","Niin teki myös Jesus monta muuta merkkiä opetuslastensa nähden, jotka ei tässä kirjassa ole kirjoitetut."],[20,31,"Mutta nämät ovat kirjoitetut, että te uskoisitte, että Jesus on Kristus, Jumalan Poika, ja että te saisitte elämän uskon kautta hänen nimeensä.","Mutta nämät ovat kirjoitetut, että te uskoisitte, että Jesus on Kristus, Jumalan Poika, ja että te saisitte elämän uskon kautta hänen nimeensä."],[21,1,"Sitte ilmoitti Jesus taas itsensä opetuslapsille Tiberiaan meren tykönä, ja hän ilmoitti itsensä näin:","Sitte ilmoitti Jesus taas itsensä opetuslapsille Tiberiaan meren tykönä, ja hän ilmoitti itsensä näin:"],[21,2,"Simon Pietari ja Toomas, joka kaksoiseksi kutsutaan, olivat ynnä ja Natanael, joka oli Galilean Kaanasta, ja Zebedeuksen pojat ja kaksi muuta hänen opetuslapsistansa.","Simon Pietari ja Toomas, joka kaksoiseksi kutsutaan, olivat ynnä ja Natanael, joka oli Galilean Kaanasta, ja Zebedeuksen pojat ja kaksi muuta hänen opetuslapsistansa."],[21,3,"Sanoi Simon Pietari heille: minä menen kalaan: ne sanoivat hänelle: me menemme myös kanssas. Niin he menivät ja astuivat kohta venheesen, ja ei he sinä yönä mitään saaneet.","Sanoi Simon Pietari heille: minä menen kalaan: ne sanoivat hänelle: me menemme myös kanssas. Niin he menivät ja astuivat kohta venheesen, ja ei he sinä yönä mitään saaneet."],[21,4,"Mutta kuin jo aamu oli, niin Jesus seisoi rannalle; mutta ei opetuslapset tietäneet, että se oli Jesus.","Mutta kuin jo aamu oli, niin Jesus seisoi rannalle; mutta ei opetuslapset tietäneet, että se oli Jesus."],[21,5,"Niin sanoi Jesus heille: lapset, onko teillä mitään syötävää? He vastasivat häntä: ei.","Niin sanoi Jesus heille: lapset, onko teillä mitään syötävää? He vastasivat häntä: ei."],[21,6,"Hän sanoi heille: laskekaat verkko oikialle puolelle venhettä, niin te löydätte. Niin he laskivat, ja tuli niin paljo kaloja, ettei he voineet vetää.","Hän sanoi heille: laskekaat verkko oikialle puolelle venhettä, niin te löydätte. Niin he laskivat, ja tuli niin paljo kaloja, ettei he voineet vetää."],[21,7,"Niin sanoi se opetuslapsi, jota Jesus rakasti, Pietarille: Herra se on. Kuin Simon Pietari sen kuuli, että se oli Herra, vyötti hän hameen ympärillensä, (sillä hän oli alasti,) ja heitti itsensä mereen.","Niin sanoi se opetuslapsi, jota Jesus rakasti, Pietarille: Herra se on. Kuin Simon Pietari sen kuuli, että se oli Herra, vyötti hän hameen ympärillensä, (sillä hän oli alasti,) ja heitti itsensä mereen."],[21,8,"Mutta muut opetuslapset tulivat venheellä, (sillä ei he olleet kaukana maalta, vaan lähes kaksisataa kyynärää,) ja vetivät verkon kaloinensa.","Mutta muut opetuslapset tulivat venheellä, (sillä ei he olleet kaukana maalta, vaan lähes kaksisataa kyynärää,) ja vetivät verkon kaloinensa."],[21,9,"Kuin he siis olivat maalle tulleet, näkivät he hiilet ja kalan, niiden päällä pantuna, ja leivän.","Kuin he siis olivat maalle tulleet, näkivät he hiilet ja kalan, niiden päällä pantuna, ja leivän."],[21,10,"Jesus sanoi heille: tuokaat tänne niistä kaloista, jotka te nyt saitte.","Jesus sanoi heille: tuokaat tänne niistä kaloista, jotka te nyt saitte."],[21,11,"Simon Pietari meni ja veti verkon maalle, täynnä suuria kaloja, sata ja kolmekuudettakymmentä. Ja vaikka niitä niin monta oli, ei kuitenkaan verkko revennyt.","Simon Pietari meni ja veti verkon maalle, täynnä suuria kaloja, sata ja kolmekuudettakymmentä. Ja vaikka niitä niin monta oli, ei kuitenkaan verkko revennyt."],[21,12,"Jesus sanoi heille: tulkaat rualle; mutta ei yksikään opetuslapsista uskaltanut häntä kysyä: kukas olet? sillä he tiesivät sen olevan Herran.","Jesus sanoi heille: tulkaat rualle; mutta ei yksikään opetuslapsista uskaltanut häntä kysyä: kukas olet? sillä he tiesivät sen olevan Herran."],[21,13,"Niin Jesus tuli, otti leivän ja antoi heille, niin myös kalan.","Niin Jesus tuli, otti leivän ja antoi heille, niin myös kalan."],[21,14,"Tämä on kolmas kerta, kuin Jesus opetuslapsillensa ilmestyi, sitte kuin hän oli noussut ylös kuolleista.","Tämä on kolmas kerta, kuin Jesus opetuslapsillensa ilmestyi, sitte kuin hän oli noussut ylös kuolleista."],[21,15,"Kuin he siis syöneet olivat, sanoi Jesus Simon Pietarille: Simon Jonan poika! rakastatkos minua enempi kuin nämät? Hän sanoi: jaa, Herra, sinä tiedät, että minä sinua rakastan. Hän sanoi hänelle: ruoki minun karitsoitani.","Kuin he siis syöneet olivat, sanoi Jesus Simon Pietarille: Simon Jonan poika! rakastatkos minua enempi kuin nämät? Hän sanoi: jaa, Herra, sinä tiedät, että minä sinua rakastan. Hän sanoi hänelle: ruoki minun karitsoitani."],[21,16,"Ja sanoi taas toisen kerran hänelle: Simon Jonan poika! rakastatkos minua? Hän vastasi: jaa, Herra, sinä tiedät, että minä sinua rakastan. Sanoi hän hänelle: kaitse minun lampaitani.","Ja sanoi taas toisen kerran hänelle: Simon Jonan poika! rakastatkos minua? Hän vastasi: jaa, Herra, sinä tiedät, että minä sinua rakastan. Sanoi hän hänelle: kaitse minun lampaitani."],[21,17,"Hän sanoi kolmannen kerran hänelle: Simon Jonan poika! rakastatkos minua? Pietari tuli murheelliseksi, että hän kolmannen kerran sanoi hänelle: rakastatkos minua? ja sanoi hänelle: Herra, sinä tiedät kaikki: sinä tiedät, että minä rakastan sinua. Jesus sanoi hänelle: ruoki minun lampaitani.","Hän sanoi kolmannen kerran hänelle: Simon Jonan poika! rakastatkos minua? Pietari tuli murheelliseksi, että hän kolmannen kerran sanoi hänelle: rakastatkos minua? ja sanoi hänelle: Herra, sinä tiedät kaikki: sinä tiedät, että minä rakastan sinua. Jesus sanoi hänelle: ruoki minun lampaitani."],[21,18,"Totisesti, totisesti sanon minä sinulle: kuin sinä olit nuori, niin sinä vyötit itses ja menit, kuhunkas tahdoit; mutta kuin vanhenet, niin sinä ojennat kätes, ja toinen vyöttää sinun, ja vie, kuhunka et sinä tahdo.","Totisesti, totisesti sanon minä sinulle: kuin sinä olit nuori, niin sinä vyötit itses ja menit, kuhunkas tahdoit; mutta kuin vanhenet, niin sinä ojennat kätes, ja toinen vyöttää sinun, ja vie, kuhunka et sinä tahdo."],[21,19,"Mutta sen hän sanoi, antain tietää, millä kuolemalla hänen piti kunnioittaman Jumalaa. Ja kuin hän sen sanonut oli, sanoi hän hänelle: seuraa minua.","Mutta sen hän sanoi, antain tietää, millä kuolemalla hänen piti kunnioittaman Jumalaa. Ja kuin hän sen sanonut oli, sanoi hän hänelle: seuraa minua."],[21,20,"Pietari käänsi itsensä, ja näki sen opetuslapsen seuraavan, jota Jesus rakasti, joka myös oli Jesuksen rinnoilla ehtoollisessa maannut, ja sanonut: Herra, kuka se on, joka sinun pettää?","Pietari käänsi itsensä, ja näki sen opetuslapsen seuraavan, jota Jesus rakasti, joka myös oli Jesuksen rinnoilla ehtoollisessa maannut, ja sanonut: Herra, kuka se on, joka sinun pettää?"],[21,21,"Kuin siis Pietari hänen näki, sanoi hän Jesukselle: Herra, mitästä tämä?","Kuin siis Pietari hänen näki, sanoi hän Jesukselle: Herra, mitästä tämä?"],[21,22,"Jesus sanoi hänelle: jos minä tahtoisin hänen siihenasti olevan kuin minä tulen, mitä sinun siihen tulee? Seuraa sinä minua.","Jesus sanoi hänelle: jos minä tahtoisin hänen siihenasti olevan kuin minä tulen, mitä sinun siihen tulee? Seuraa sinä minua."],[21,23,"Niin veljesten seassa kävi ulos se puhe, ettei sen opetuslapsen pitänyt kuoleman. Mutta ei Jesus hänelle sanonut: ei hän kuole, vaan: jos minä tahdon hänen siihenasti olevan kuin minä tulen, mitä sinun siihen tulee?","Niin veljesten seassa kävi ulos se puhe, ettei sen opetuslapsen pitänyt kuoleman. Mutta ei Jesus hänelle sanonut: ei hän kuole, vaan: jos minä tahdon hänen siihenasti olevan kuin minä tulen, mitä sinun siihen tulee?"],[21,24,"Tämä on se opetuslapsi, joka todistaa näistä ja on nämät kirjoittanut, ja me tiedämme hänen todistuksensa todeksi.","Tämä on se opetuslapsi, joka todistaa näistä ja on nämät kirjoittanut, ja me tiedämme hänen todistuksensa todeksi."],[21,25,"On myös paljon muuta, mitä Jesus teki, jos ne erinänsä kirjoitettaisiin, en minä luulisi koko maailman käsittävän niitä kirjoja, joita pitäis kirjoitettaman. Amen.","On myös paljon muuta, mitä Jesus teki, jos ne erinänsä kirjoitettaisiin, en minä luulisi koko maailman käsittävän niitä kirjoja, joita pitäis kirjoitettaman. Amen."]]}};